pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize residual gaps that are just below the smallest item size (1),
    // i.e. any positive dead space is bad; scale penalty by tightness.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Open bins pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // (avoids opening a new bin when a usable fit exists).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make empty bin attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced when many items remain.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 - 20.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        score -= (next_item_size as f64) * 0.3;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals too small for the smallest plausible future item (1..100 range).
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 2.0;
    }

    // Reward perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward; else penalize tight gaps.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering into many bins when residuals are large.
    if bin_residual < bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += pressure * 0.5;
    }

    // New-bin candidate: penalize slightly so we prefer filling existing bins,
    // unless the existing fit is very poor.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Late-stream tightening: as stream progresses, favor compacting into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A gap is "dead" if it is smaller than the minimum plausible item size.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_gap = 5.0;
    if (post_residual as f64) < min_gap + 10.0 * (1.0 - progress) {
        score += 40.0 + 30.0 * (1.0 - progress);
    }

    // Non-linear penalty: waste grows quadratically for tiny residuals.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (post_residual small but usable).
    if post_residual >= 1 && post_residual <= 20 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score += pressure * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is bad and bins are few.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 40 { 1.0 } else { 0.0 };
        score += 55.0 - bad_fit * 45.0 - pressure * 2.0;
    }

    // Slight preference for bins with less residual already (tighter bins first).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any plausible
    // future item (min size 1, but practically small gaps < 12) are pure waste.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 8.0; // heavy penalty for tiny dead gaps
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // filling bins fully is preferred.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 2.0 * (1.0 - progress);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0; // next item can still use this bin
    }

