            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
            // Fresh-bin capacity check: open bins collectively cannot absorb
            // the current item plus the next one.
            if open_bins_count > 0 && next_item_size > 0 {
                if total_fit_cap < (item_size + next_item_size) as f64 * 0.9 {
                    score -= 14.0;
                }
            }
            // Fresh bin leaving a residual exactly matching the next item is
            // a perfect chain — reward strongly.
            if next_item_size > 0 && post_residual == next_item_size {
                score -= 45.0;
            }
            // Fresh bin leaves a residual the next item almost fills: good.
            if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
                score -= 18.0;
            }
            // Fresh bin whose post-residual is a multiple of the next item
            // enables a clean multi-item chain — reward.
            if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
                score -= 6.0;
            }
            // Fresh bin residual exactly matching a common small size.
            if post_residual % 10 == 0 && post_residual <= 50 {
                score -= 4.0;
            }
            // NEW: fresh bin residual >= next item (chainable) is better than
            // a fresh bin that strands space when the stream is young.
            let progress1 = step_index as f64 / total_items.max(1) as f64;
            if next_item_size > 0 && post_residual >= next_item_size && progress1 < 0.7 {
                score -= 4.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 27.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Consolidation pressure early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mid-band residual (30..60) packs well with typical sizes.
    if post_residual >= 30 && post_residual <= 60 {
        let remaining = (total_items - step_index) as f64;
        let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
        score -= 5.0 + 3.0 * stream_left;
    }

    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Sharp penalty for the 5..12% sliver band.
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band attraction toward center.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Chain into small residual in the 10..18% band.
        if dead_ratio > 0.10 && dead_ratio < 0.18 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
        }
        // Mid-range dead space early in stream: penalize mildly.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
        // Tiny residual left after chaining next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
        }
        // Hard-to-fill residual with few fitting bins: avoid creating it.
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 2.5 * (0.08 - dead_ratio) * 100.0;
        }
        // Wide-open bins with next item smaller: strong chain candidate.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // Gap-based penalty when next item doesn't fit.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
        // Divisibility bonus.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        // Small-residual avoidance when many bins can still fit.
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        // Penalize residuals that neither the next item nor the mean open-bin
        // residual can absorb (dead-space coupling fix).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < next_item_size as f64 && after > mean_residual.max(1.0) {
                score += 3.0 * (1.0 - after / (next_item_size as f64)) * (1.0 - progress);
            }
        }
        // Avoid awkward 12..20% residuals when no chain is possible.
        if dead_ratio >= 0.12 && dead_ratio < 0.20 && stream_left2 > 0.5
            && (next_item_size == 0 || next_item_size > post_residual) {
            score += 3.0 * (dead_ratio - 0.12) * 50.0 * stream_left2;
        }
        // Reward exact multi-fit chains — residual divisible by next item
        // with at least two repetitions.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
        // Prefer bins whose post-residual can absorb next item AND leaves
        // a residual >= mean_residual (recyclable dead space).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= mean_residual.max(1.0) {
                score -= 1.5;
            }
        }
        // When many items remain, prefer bins whose post-residual is a
        // multiple of a common small size (5 or 10) — easier future packing.
        if stream_left2 > 0.4 && post_residual % 10 == 0 {
            score -= 1.5;
        } else if stream_left2 > 0.4 && post_residual % 5 == 0 {
            score -= 0.8;
        }
        // Late stream — strongly prefer tightest bins regardless of band.
        if stream_left2 < 0.25 {
            score += 0.08 * post_residual as f64;
        }
        // Combined coupling — when the stream is far from over and the
        // next item cannot use the leftover, penalize residuals that no
        // plausible future item (next item ± 10) can absorb either.
        if stream_left2 > 0.5 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < 10.0 {
                score -= 2.0 * (1.0 - after / 10.0) * stream_left2;
            }
        }
        // NEW: dead-space coupling — penalize residuals that are too small
        // for the next item yet exceed the mean absorbable residual, scaled
        // by how many items remain (likely permanent waste).
        if next_item_size > 0 && post_residual < next_item_size
            && post_residual as f64 > mean_residual.max(1.0) * 1.5 && stream_left2 > 0.3 {
            score += 2.0 * (1.0 - dead_ratio) * stream_left2;
        }
        // NEW: reward residuals in the 20..35% band when the next item can
        // chain into them and leave an absorbable remainder.
        if dead_ratio >= 0.20 && dead_ratio < 0.35 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after == 0.0 || after <= mean_residual.max(1.0) {
                score -= 4.0 * (1.0 - scarcity);
            }
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect match with the next item (2-step lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // ideal: next item fills this bin exactly
        } else if post_residual > next_item_size {
            // residual left for next item, penalize leftover after that hypothetical placement
            let second_leftover = post_residual - next_item_size;
            score += second_leftover as f64 * 0.6;
            if second_leftover < 10 {
                score -= 15.0; // near-perfect two-step chain
            }
        } else {
            // next item cannot fit here; penalize proportionally to the gap
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.35;
        }
    } else {
        // last item: prefer tightest fit
        score += post_residual as f64 * 0.5;
    }

    // Penalize dead space below typical minimum item size (1..100 range: harsh below ~15).
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Reward using bins whose residual is already below average (consolidating space).
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Mild preference for keeping the number of open bins low when many are open.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Early in the stream, be slightly more willing to open fresh bins (spread items).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if no open bin offers a tight fit.
        let tightness = post_residual as f64; // = capacity - item for new bin
        score = tightness - 25.0 * (1.0 - progress) - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size as f64 <= tightness as f64 {
            score -= 20.0; // fresh bin can also host next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize tiny dead space
    // that is unlikely to fit future items (below minimum item size 1 => dead space < 1 is impossible, so focus on small residuals).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize post_residual that is small but nonzero and cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins whose leftover can still host the next item.
            let slack_fit = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack_fit / bin_capacity as f64);
        } else {
            // Dead space relative to the lookahead item.
            let dead = (next_item_size - post_residual) as f64;
            score += 2.5 * dead;
        }

        // Bonus if this bin after placement could exactly take the next item.
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins => we can afford to be picky; penalize loose fits more.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0) * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive when open bins have poor residuals
    // relative to the item, or late in the stream with many bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.55;
        // Attractive if existing mean residual is large and fragmented.
        score -= 0.35 * mean_residual;
        // Early in the stream, prefer filling existing bins (cheap to keep few bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If no open bin fits besides this, opening is natural: handled by fitting_bins_count == 0.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
        // If the next item is large, a fresh bin is more valuable.
        score -= 0.15 * next_item_size as f64;
    }

    // Prefer bins whose residual is far from the mean (outliers with lots of space
    // should absorb large items, keeping tight bins for small items).
    let resid_gap = (bin_residual as f64 - mean_residual).abs();
    score -= 0.08 * resid_gap;

    // Slight preference for bins with larger current residual when item is large.
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Late-stream pressure: consolidate into fewer bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for accumulating many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 110.0;
        }
    }

    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Exact lookahead match: post residual equals next item => perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0;
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0;
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
                score -= 12.0 + 0.15 * (pr - nxt);
            }
            if after >= nxt {
                score -= 10.0;
                if after >= 2.0 * nxt {
                    score -= 6.0;
                    score -= 2.0 * ((after / nxt) - 2.0).min(2.0);
                }
            } else {
                score += 4.0;
            }
            if pr % nxt.max(1.0) == 0.0 && nxt <= pr {
                score -= 7.0;
            }
            // Chain leaves residual absorbable by average open bin.
            if after > 0.0 && after <= mean_residual.max(1.0) {
                score -= 2.5;
            }
            if after >= 3.0 && after <= 15.0 {
                score -= 3.5;
            }
            // after leaves a decile-aligned residual (easy to fill later).
            if after > 0.0 && after % 10.0 == 0.0 {
                score -= 4.0;
            }
            // chain leaves residual that is itself a multiple of next item
            if after > 0.0 && after % nxt.max(1.0) == 0.0 && after >= nxt {
                score -= 2.0 + 0.15 * (after / nxt);
            }
        } else {
            let gap = nxt - pr;
            if gap <= 8.0 {
                score += 60.0 + 6.0 * (8.0 - gap);
            } else {
                score += 25.0 * (1.0 - pr / nxt.max(1.0));
            }
            if gap <= 15.0 {
                let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
            if gap <= 20.0 && fitting_bins_count <= 2 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }
    }

    // Relative-to-mean: prefer tighter-than-average bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance: only fitting bin -> keep item out of a new bin.
    if fitting_bins_count == 1 {
        score -= 160.0;
    } else if fitting_bins_count == 0 {
        score += 80.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_cap = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                && mean_residual < next_item_size as f64 * 1.15
                && (fitting_bins_count as f64) < 4.0)
                || (total_fit_cap < next_item_size as f64 * 2.0
                    && fitting_bins_count <= 1));
        if big_item || crowded || next_needs_fresh {
            score -= 50.0;
        } else {
            score += 55.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 28.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Consolidation pressure early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mid-band residual (30..60) tends to pack well with typical sizes.
    if post_residual >= 30 && post_residual <= 60 {
        let remaining = (total_items - step_index) as f64;
        let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
        score -= 4.0 + 3.0 * stream_left;
    }

    // Dead-space shaping.
    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Sharp penalty for the 5..12% sliver band (hardest to fill later).
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band (20..45%) attraction toward center when next item can't fill it.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Chain into small residual in the 10..18% band.
        if dead_ratio > 0.10 && dead_ratio < 0.18 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
        }
        // Mid-range dead space early in stream: penalize mildly.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
        // Tiny residual left after chaining next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
            if after > 0.0 && after % 10 == 0 && after <= 40 {
                score -= 2.0 * (1.0 - scarcity);
            }
        }
        // Sliver band with few fitting bins: strongly discourage.
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 4.0 * (0.08 - dead_ratio) * 100.0 * 0.5;
        }
        // Reward bins that can still absorb a small extra item after chaining.
        if next_item_size > 0 && post_residual > next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
        }
        // 45-55% band with scarce fits and small next item: attract.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // Next item can't fit here with few fits: mild penalty scaled by fill.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
        // Wide-open bins with many fits: mild attraction to consolidate there.
        if dead_ratio > 0.15 && fitting_bins_count >= 4 {
            score -= 2.0 * (dead_ratio - 0.15) * 10.0 * scarcity;
        }
        // NEW: penalize slivers that even after chaining leave a tiny unusable remainder
        if next_item_size > 0 && post_residual >= next_item_size {
            let after2 = (post_residual - next_item_size) as f64;
            let frac = after2 / cap;
            if after2 > 0.0 && frac < 0.10 {
                score += 3.0 * (0.10 - frac) * 10.0 * (1.0 - scarcity);
            }
        }
        // NEW: divisible residual by next item is a clean chain.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size && post_residual > 0 {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        // NEW: many fitting bins and low dead ratio: discourage (use tighter bins first).
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        // Tiny dead space is nearly worthless.
        score += 120.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 20.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 6.0;
    }

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0; // exact 2-chain
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0; // near-perfect chain
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
                score -= 12.0 + 0.15 * (pr - nxt);
            }
            if after >= nxt {
                score -= 8.0; // room for a third item potentially
            }
        } else {
            let gap = nxt - pr;
            if gap <= 8.0 {
                // Almost usable: strong penalty so we don't strand it.
                score += 60.0 + 6.0 * (8.0 - gap);
            } else {
                score += 25.0 * (1.0 - pr / nxt.max(1.0));
            }
        }
    }

    // Relative-to-mean: prefer tighter-than-average bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance: only fitting bin -> keep item out of a new bin.
    if fitting_bins_count == 1 {
        score -= 160.0;
    } else if fitting_bins_count == 0 {
        score += 80.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_cap = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                && mean_residual < next_item_size as f64 * 1.15
                && (fitting_bins_count as f64) < 4.0)
                || (total_fit_cap < next_item_size as f64 * 2.0
                    && fitting_bins_count <= 1));
        if big_item || crowded || next_needs_fresh {
            score -= 60.0;
        } else {
            score += 70.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    // Consolidation pressure early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mid-band residual (30..60) tends to pack well with typical sizes.
    if post_residual >= 30 && post_residual <= 60 {
        let remaining = (total_items - step_index) as f64;
        let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
        score -= 5.0 + 3.0 * stream_left;
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: any small unusable gap is heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item
    // (items are 1..=100; treat gaps < 10 as dead, and taper the penalty up to 30).
    let gap = post_residual as f64;
    if gap > 0.0 {
        if gap < 10.0 {
            score += 500.0 * (10.0 - gap) / 10.0;
        } else if gap < 30.0 {
            // Mid-range gaps: penalize proportionally more when they cannot
            // accommodate the lookahead item.
            if next_item_size > 0 && (next_item_size as f64) > gap {
                score += 150.0 * (30.0 - gap) / 20.0;
            } else {
                score += 25.0;
            }
        }
    }

    // Reward bins whose residual still fits the next item (chaining placements).
    if next_item_size > 0 && (next_item_size as f64) <= gap && gap > 0.0 {
        score -= 40.0 + 0.5 * (gap - next_item_size as f64);
    }

    // Open-bin pressure: prefer consolidating into few bins, but only mildly,
    // so dead-space logic dominates.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using
    // it over opening a new bin (unless the gap penalty above is extreme).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when no open bin offers a decent fit. Give it a
    // baseline score that tracks the mean residual of open bins: if open bins
    // are already tight (low mean residual), opening fresh is cheap; if open
    // bins are roomy, discourage new bins.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.8 * mean_residual + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 120.0; // discourage opening when some bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: the smaller the waste relative to capacity, the better.
    let waste_frac = post_residual as f64 / cap;
    score += waste_frac * waste_frac * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - leftover_after_next as f64 / cap);
        } else {
            // Post-residual too small for next item: penalize dead space creation.
            score += (post_residual as f64) * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // Prefer new bin only if this item would leave a very awkward residual elsewhere,
        // or if open bins are already quite full on average.
        let awkward = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            10.0
        } else {
            0.0
        };
        let crowded = (open_bins_count as f64) * 1.5;
        score += 60.0 - awkward - crowded + mean_residual * 0.2;
    }

    // Mild time-horizon scaling: early in the stream, be slightly more conservative
    // about fragmentation (long horizon ahead); later, just fill bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    // Tie-break: prefer bins with residual close to the item (best-fit flavor)
    // when many bins can fit the item.
    if fitting_bins_count > 1 {
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "dead zones"
    // (very small remainders that nothing can fill) are penalized.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals that no plausible item (>=10) can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic quantization of residual: reward residuals divisible into
    // common item-size classes (mod 10 grid).
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0; // perfectly aligned residual
    } else if mod10 >= 5 {
        score += (mod10 as f64) * 0.6;
    } else {
        score += (mod10 as f64) * 1.2;
    }

    // Reward tight fits (waste minimization, non-linear).
    let fill_ratio = 1.0 - post / cap_f;
    if fill_ratio > 0.9 {
        score -= 15.0;
    } else if fill_ratio > 0.75 {
        score -= 7.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra harmonic bonus if next item exactly matches residual class.
        if post_residual % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize leaving awkward leftovers.
        score += 4.0;
    }

    // New-bin candidate logic: only attractive when current bin would be
    // badly fragmented or open bins are numerous.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_score = 55.0
            - 10.0 * progress
            - 0.5 * (open_bins_count as f64)
            + (mean_residual / cap_f) * 20.0;
        // Keep new bin competitive only when mean residual is low (bins are full-ish)
        score = new_bin_score;
    }

    // Mild pressure against hoarding many open bins.
    score += 0.15 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 28.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 110.0;
        }
    }

    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Exact lookahead match: post residual equals next item => perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    }

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0;
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0;
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
                score -= 12.0 + 0.15 * (pr - nxt);
            }
            if after >= nxt {
                score -= 10.0;
                if after >= 2.0 * nxt {
                    score -= 6.0;
                }
            }
            if pr % nxt.max(1.0) == 0.0 && nxt <= pr {
                score -= 6.0;
            }
            // Chain leaves residual absorbable by average open bin.
            if after > 0.0 && after <= mean_residual.max(1.0) {
                score -= 3.0;
            }
            if after >= 3.0 && after <= 15.0 {
                score -= 3.5;
            }
            // Chain of two next-items: strong reward.
            if after >= 2.0 * nxt {
                score -= 4.0 * ((after / nxt) - 2.0).min(2.0);
            }
            // after leaves a decile-aligned residual (easy to fill later).
            if after > 0.0 && after % 10.0 == 0.0 {
                score -= 4.0;
            }
        } else {
            let gap = nxt - pr;
            if gap <= 8.0 {
                score += 60.0 + 6.0 * (8.0 - gap);
            } else {
                score += 25.0 * (1.0 - pr / nxt.max(1.0));
            }
        }
    }

    // Relative-to-mean: prefer tighter-than-average bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance: only fitting bin -> keep item out of a new bin.
    if fitting_bins_count == 1 {
        score -= 160.0;
    } else if fitting_bins_count == 0 {
        score += 80.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_cap = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                && mean_residual < next_item_size as f64 * 1.15
                && (fitting_bins_count as f64) < 4.0)
                || (total_fit_cap < next_item_size as f64 * 2.0
                    && fitting_bins_count <= 1));
        if big_item || crowded || next_needs_fresh {
            score -= 50.0;
        } else {
            score += 60.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            // Open fresh bins eagerly late in the stream when leftovers are tiny.
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 28.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Consolidation pressure early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mid-band residual (30..60) tends to pack well with typical sizes.
    if post_residual >= 30 && post_residual <= 60 {
        let remaining = (total_items - step_index) as f64;
        let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
        score -= 4.0 + 3.0 * stream_left;
    }

    // Dead-space shaping.
    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Sharp penalty for the 5..12% sliver band (hardest to fill later).
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band (20..45%) attraction toward center when next item can't fill it.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Chain into small residual in the 10..18% band.
        if dead_ratio > 0.10 && dead_ratio < 0.18 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
        }
        // Mid-range dead space early in stream: penalize mildly.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
        // Tiny residual left after chaining next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
        }
        // Sliver band with few fitting bins: strongly discourage.
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 4.0 * (0.08 - dead_ratio) * 100.0 * 0.5;
        }
        // Reward bins that can still absorb a small extra item after chaining.
        if next_item_size > 0 && post_residual > next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
        }
        // 45-55% band with scarce fits and small next item: attract.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // Next item can't fit here with few fits: mild penalty scaled by fill.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post residual (fine-grained bands).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= bin_capacity / 10 {
        score += 60.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    // Awkward dead-space band: 11..=19 is too small for most items.
    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
    }

    // Lookahead coupling: exact/near match with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else if bin_residual >= next_item_size {
            // This placement destroys the only fit for the next item.
            score += 30.0;
        }
    }

    // Last-chance bin: strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate logic: penalize fresh bins unless item is big,
    // bins are crowded, or lookahead justifies it.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let mut new_bonus = -40.0;
        if big_item || bins_crowded {
            score -= 40.0;
        } else {
            score += 45.0;
            // Lookahead escape: next item huge and current fit poor -> soften.
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            let _ = new_bonus;
        }
        // Late-stream conservatism: fresh bins cost more late.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Fill-fraction coupling: reward large items placed in existing bins.
    if bin_residual != bin_capacity {
        score -= (item_size as f64 / cap) * 20.0;
    }

    // Mean-residual consolidation: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: never waste this bin again.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Modulo-10 class of post_residual.
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.4;

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            score -= 12.0;
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
            if after <= 3 {
                score -= 12.0;
            } else if after < next_item_size {
                // Residue can't host a repeat of next item: mild penalty.
                score += 4.0;
            } else {
                score -= 8.0;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            // Dead space relative to lookahead: penalize proportionally,
            // but less when the gap is tiny (item almost fits).
            score += gap * 0.5;
            if gap <= 8.0 {
                score += 3.0 + 0.5 * (8.0 - gap);
            }
        } else if bin_residual >= next_item_size {
            // Empty-ish bin (post_residual == 0 handled above) that could
            // host the lookahead item after this one.
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 42.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins below the mean (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Small-residue dead-space shaping.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    // Scarcity-aware dead-space handling.
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Mid-band residue (30-60) is valuable for medium items.
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        // Chained fits: post_residual can host next item twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 10.0;
            }
            if chain > 0 && chain % 10 == 0 {
                score -= 4.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (capacity fractions) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class the post-residual into harmonic bands: dead space becomes
    // progressively more costly the smaller (less reusable) it is.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual <= bin_capacity / 10 {
        // Tiny unusable sliver (<=10): dead space penalty.
        score += 60.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    // Integer-division thresholds: post_residual divisible by common
    // item sizes (10,20,25,50) is "harmonic" and likely reusable.
    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
    }

    // Lookahead coupling: reward residual that can still host the next item,
    // penalize when the next item is stranded by this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys the only fit for the next item.
            score += 30.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive for very large items (poor fit
    // elsewhere) or when open bins are mostly full. Item size classes via
    // integer division.
    if bin_residual == bin_capacity {
        let size_class = item_size / 20; // 0..4 harmonic size class
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        if big_item || bins_crowded || size_class >= 3 {
            score -= 40.0;
        } else {
            // Prefer filling existing bins: penalize opening a new one.
            score += 70.0 + 0.5 * mean_residual;
        }
    }

    // Stream progression: late in the stream, be more conservative with
    // new bins and squeeze existing ones harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize wasted space quadratically relative to capacity.
    let waste_frac = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * waste_frac * waste_frac;

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact match bonus.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 + 0.5 * slack;
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Dead space that the next item cannot use: penalize.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.3 * dead;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bins are very full / poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // Open a new bin when open bins are quite full and many bins already exist.
        if avg_tightness > 0.7 && open_bins_count > 2 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 25.0;
        }
    }

    // Early stream: slightly discourage proliferating bins.
    if step_index < 10 {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

