pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item fits exactly into this bin afterwards: strong reward
            score -= 300.0 * (1.0 - gap / cap);
        } else {
            // next item would not fit: penalize leaving a nearly-fitting residual
            score += 150.0 * (1.0 - gap / cap);
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.5 * mean_gap;

    // Penalize large wasted residual (dead space), scaled by item size
    score += (post_residual as f64 / cap) * (item_size as f64);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let open_fits = fitting_bins_count.max(1) as f64;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score += 80.0 * pressure / open_fits;
        if next_item_size > 0 && (next_item_size as f64) >= cap * 0.5 {
            score -= 100.0; // big next item: fresh bin may be wise
        }
    }

    // Mild stream-position adaptation: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: zero waste is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item's size (chains two placements).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            score -= 500.0; // exact 2-chain match
        } else if pr >= nxt {
            score -= 250.0 * (1.0 - diff / bin_capacity as f64); // next item still fits
        } else {
            score += 60.0 * (1.0 - pr / nxt.max(1.0)); // dead space blocks lookahead item
        }
    }

    // Penalize post_residual that is small but unusable (typical sizes 10..80).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 400.0 } else { 0.0 };
        score += 120.0 - scarcity;
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
            score += 30.0;
        }
    }

    // Slight preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    // Base: prefer small post-residual, with non-linear decay so tiny residuals are strongly favored.
    let mut score = pr - 6.0 * (1.0 - (pr / cap).powf(2.0)) * (pr / cap) * cap * 0.25;

    // Smooth stream-progress coupling: late in the stream, tighten residual requirements.
    score += t * pr * 0.35;

    // Penalize new-bin opening progressively (more costly later, but cheap early).
    score += is_new * (18.0 + 30.0 * t * t);

    // Reward using the last fitting bin (avoid opening a bin for a poor fit).
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 12.0;
    }

    // Lookahead coupling: bonus if next item fits the post-residual, penalty if it barely misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference for bins with residuals near the mean (keeps bins homogeneous).
    score += ((pr - mean_residual) / cap).powi(2) * 4.0;

    // Mild load-balancing pressure across open bins.
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let base = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let norm_post = base / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = base;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + progress) - norm_post * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits more aggressively as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 20.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let waste = (next_item_size as f64 - base).min(cap);
        score += 6.0 * waste * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 && base >= norm_next * cap {
        // Smooth reward when post residual still accommodates next item
        score -= 4.0 * (1.0 - (base - norm_next * cap) / cap);
    }

