    // late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 10.0;

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current fits are very poor.
    if bin_residual == bin_capacity {
