        score = 35.0 + 20.0 * (1.0 - progress) - 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin leaves room for a possibly-large next item
        }
    }

    score
}

