        // Base cost of opening a new bin; offset by waste avoided elsewhere.
        score += 35.0 + open_bins_count as f64 * 0.3;
        // If the current item is large and nothing else is attractive, new bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins rather than leaving many open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can fit here afterwards: reward closeness of match.
            score -= (60.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
            if gap == 0.0 {
                score -= 250.0; // perfect chain: item then next item fills bin exactly
            }
        } else {
            // Post residual too small for next item: dead-space penalty scaled by gap.
            score += 20.0 + gap * 0.5;
        }
    }

    // Compare post_residual against mean residual: avoid making a bin an outlier
    // with tiny unusable residual relative to the fleet average.
    let cap = bin_capacity as f64;
    let mean_dev = (post_residual as f64 - mean_residual) / cap;
    score += 40.0 * mean_dev.abs();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins can fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus a term that shrinks as the stream
        // progresses (late in the stream, prefer consolidating into open bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 + 80.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin guarantees the next item fits too; slight discount.
            score -= 15.0;
        }
    }

    // Mild penalty for spreading across many open bins (fragmentation control).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Penalize dead space that can't fit the average incoming item.
    if post_residual > 0 {
        let dead = (post_residual as f64) < (next_item_size as f64);
        if dead && next_item_size > 0 {
            score += 18.0;
        }
    }

    // Lookahead: if this placement leaves room for the next item, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Global state: with many open bins, prefer consolidation into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 25.0 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score -= 40.0 * (1.0 - t);
        score += 35.0 * t;
        // If no existing bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        score -= 6.0 * t;
    }

    // Mean residual coupling: prefer bins near the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild penalty for very large leftover fragments (>25% of capacity).
    if post_residual as f64 > 0.25 * bin_capacity as f64 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_weight = 8.0 * t * (1.0 - t) + 2.0 * t * t; // peaks mid-stream
    score -= progress_weight * norm_pr * pr;

    // Penalize small post-residuals more as stream advances (dead space hardening)
    let small_penalty = (1.0 - norm_pr) * (1.0 - norm_pr);
    score += small_penalty * 12.0 * (0.3 + 0.7 * t);

    // Reward tight fits (post_residual near 0) with non-linear decay
    let tightness = (-norm_pr * 6.0).exp();
    score -= tightness * 15.0;

    // Lookahead coupling: reward leaving space for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let match_bonus = 1.0 - ((pr - ni) / cap).abs();
        score -= 10.0 * match_bonus.max(0.0) * match_bonus.max(0.0);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate: make it attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let open_pressure = (open_bins_count as f64).ln() / (1.0 + cap / 10.0);
        score -= 25.0 * fragmentation * (0.5 + t) - open_pressure;
    }

    // Mild preference for bins with below-average residual (consolidation)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (capacity fractions) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class the post-residual into harmonic bands: dead space becomes
    // progressively more costly the smaller (less reusable) it is.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual <= bin_capacity / 10 {
        // Tiny unusable sliver (<=10): dead space penalty.
        score += 60.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    // Integer-division thresholds: post_residual divisible by common
    // item sizes (10,20,25,50) is "harmonic" and likely reusable.
    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
    }

    // Lookahead coupling: reward residual that can still host the next item,
    // penalize when the next item is stranded by this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys the only fit for the next item.
            score += 30.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive for very large items (poor fit
    // elsewhere) or when open bins are mostly full. Item size classes via
    // integer division.
    if bin_residual == bin_capacity {
        let size_class = item_size / 20; // 0..4 harmonic size class
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        if big_item || bins_crowded || size_class >= 3 {
            score -= 40.0;
        } else {
            // Prefer filling existing bins: penalize opening a new one.
            score += 70.0 + 0.5 * mean_residual;
        }
    }

    // Stream progression: late in the stream, be more conservative with
    // new bins and squeeze existing ones harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are "dead" — penalize them heavily and non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0).powi(2);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else {
        // Usable residual: mild reward scaled by how much usable room remains.
        score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward;
    // if it almost fits (miss by a little), penalize — that residual is wasted.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else if next_item_size <= post_residual + 10 {
            score += 25.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few open
    // bins, opening a new one is cheaper so new-bin candidate gets a boost.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.8 * pressure;

    // New-bin candidate (empty bin): penalize mildly so it only wins when open
    // bins have poor fits; the penalty grows with open-bin scarcity.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Deviation from mean residual: prefer bins whose residual is close to the
    // mean (keeps bin states homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Tight fit bonus: reward placements that consume a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leaving nothing behind is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: strongly reward a post-residual that exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here afterwards; mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit after placement; penalize proportionally to wasted lookahead.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Penalize residuals below the minimum item size (dead space), harder late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (1.5 + 3.0 * progress) * (10 - post_residual) as f64;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New empty bin candidate: make it unattractive unless nothing else fits well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative fill after placement
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that is hard to reuse (post_residual in awkward zone)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 20.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't follow here; slight penalty proportional to wasted potential
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Time horizon: early in stream, be conservative (penalize fragmentation);
    // late in stream, prefer filling existing bins aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 15.0;

    // Global residual state: if mean residual is high, many bins have room;
    // prefer bins below mean residual (consolidation), penalize spreading
    if bin_residual as f64 > mean_residual + 1.0 {
        score += 12.0;
    } else {
        score -= 6.0;
    }

    // Many open bins: encourage consolidation into fuller bins
    score += open_bins_count as f64 * 0.5 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when fits are terrible
    if bin_residual == bin_capacity {
        score += 80.0;
        // If no good fit exists elsewhere (post_residual large relative to item),
        // soften the penalty so a new bin can win
        if post_residual > bin_capacity / 2 && (fitting_bins_count == 0 || fill_ratio < 0.5) {
            score -= 70.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn);
    let mut score = pr * (1.0 + 2.0 * poly * (0.5 - progress).abs());
    // Tight fits rewarded more as stream progresses
    score -= (1.0 - prn) * progress * 8.0;
    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }
    // Lookahead coupling: penalize residual that can't hold next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            score -= (pr - nx).min(20.0) as f64 * 0.2;
        }
    }
    // Penalize opening new bins when good fits exist
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0 - progress * 5.0;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }
    // Mean residual deviation penalty
    score += (mean_residual - pr).abs() * 0.3;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small,
    // unusable" classes are good terminals for this item.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // capacity fraction left after placement

    // Integer-division thresholds on post_residual: dead-space classes.
    let cls = post_residual / 10; // which decile of leftover we land in
    match cls {
        0 => score -= 30.0,             // near-perfect fit (0-9 left)
        1 => score -= 18.0,             // excellent (10-19)
        2 => score -= 8.0,              // good (20-29)
        3 | 4 => score += 2.0,          // mediocre (30-49)
        5 | 6 => score += 8.0,          // poor (50-69)
        7 | 8 => score += 14.0,         // wasteful (70-89)
        _ => score += 20.0,             // nearly empty usage (90+)
    }

    // Modulo arithmetic: leftover that is 0 is ideal; leftovers that are
    // multiples of small common item sizes are reusable.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits the post_residual exactly
    // or near-exactly, strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 40.0; // perfect chain
            } else if gap <= 5 {
                score -= 25.0;
            } else if gap <= 15 {
                score -= 12.0;
            }
        } else {
            // Next item cannot fit here: this leftover risks becoming dead space.
            let overflow = next_item_size - post_residual;
            score += (overflow.min(30)) as f64 * 0.4;
        }
    } else {
        // Last item: minimize leftover strictly.
        score += frac * 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual, so the
    // class penalties above already discourage it; but allow opening a new
    // bin early in the stream when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_f).abs();
        // Prefer a fresh bin when existing mean residual is small (fragmented)
        // and we are early/mid stream.
        score = 40.0 + fragmentation * 0.5 - (1.0 - progress) * 10.0 - (open_bins_count as f64) * 0.3;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // fresh bin can host the next item too
        }
    }

    // Mild tie-breaker: tighter fit wins.
    score += frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (1..=10) are nearly worthless.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0; // unusable sliver penalty
    } else if post_residual <= 20 {
        score += 20.0; // hard-to-fill gap
    } else if post_residual <= 35 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins are
    // crowded or the fit elsewhere is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count > 0 {
            score += 15.0; // discourage abandoning usable bins
        }
    }

    // Pressure from number of open bins: consolidate when many bins are open.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual is close to the current mean (balanced use),
    // but only mildly.
    score -= 0.3 * (bin_residual as f64 - mean_residual).abs().recip().max(0.0).min(1.0) * 5.0;

    // Lookahead: if the next item would fit exactly in the post_residual,
    // reward heavily; if post_residual is just barely too small for the next
    // item, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Late in the stream, waste matters relatively less than bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect chain: next item exactly fills the post residual -> huge reward.
        if next_item_size == post_residual {
            score -= 60.0;
        }
        // Next item fits into the leftover space -> reward proportional to how well it fills.
        else if next_item_size < post_residual {
            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - fill_after_next / bin_capacity as f64);
        }
        // Next item does NOT fit here: penalize leftovers that are likely dead space,
        // especially small unusable gaps relative to the known item-size range.
        else {
            // Small residuals below the typical minimum item size are dead space.
            if post_residual < 10 {
                score += 40.0;
            } else {
                score += 12.0;
            }
        }
        // Extra coupling: residual slightly above next_item_size is a good split target.
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 / (1.0 + gap / 20.0);
    } else {
        // Last item: prefer tightest fit strongly.
        score -= 50.0;
    }

    // --- Relative-to-mean-residual balancing ---
    // Favor bins whose post residual stays near the mean (keeps bins uniformly fillable),
    // but penalize bins that are far above mean (wasteful emptiness).
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev.abs();
    if dev > 0.0 {
        score += 0.25 * dev; // extra penalty for emptier-than-average bins
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 {
        // If no other bin fits, strongly prefer using this one over opening a new bin
        // unless the fit is terrible (huge post residual).
        let waste = post_residual as f64 / bin_capacity as f64;
        if waste < 0.6 {
            score -= 45.0 * (1.0 - progress);
        } else {
            score -= 15.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive early in the stream or when
        // the current item is large (would leave a big, useful residual).
        let base_cost = 100.0 - 30.0 * progress;
        let large_item_bonus = if item_size >= 50 { 20.0 } else { 0.0 };
        score = base_cost + item_size as f64 * 0.3 - large_item_bonus;
        // If next item is small, a fresh bin wastes its large residual.
        if next_item_size > 0 && next_item_size < 30 {
            score += 25.0;
        }
        // If few bins fit the item, discourage opening yet another bin.
        if fitting_bins_count >= 2 {
            score += 30.0;
        }
    }

    // Prefer bins that are already well-filled (small residual before placement).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: near-zero post residual gets a big discount.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Penalize large dead space (post_residual small but unusable chunks).
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        score += 10.0 * dead * (1.0 - dead);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits perfectly into the resulting residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item cannot fit here; slight penalty for wasting large residual.
            score += 3.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    } else {
        // Last item: purely minimize post residual.
        score -= 15.0 * tight;
    }

    // New-bin candidate handling: penalize opening a new bin unless it enables
    // a perfect pairing with the lookahead or few bins currently fit.
    if bin_residual == bin_capacity {
        let mut nb = 8.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            nb -= 20.0 * (1.0 - gap / (bin_capacity as f64));
        }
        if fitting_bins_count <= 1 {
            nb -= 12.0;
        }
        // Early in the stream, opening bins is cheaper; later, consolidate.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += 10.0 * t;
        score += nb;
    }

    // Global state coupling: if mean residual is high, prefer bins that
    // reduce dispersion (post_residual close to mean_residual).
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * diff;

    // Mild pressure to fill bins when many are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth coupling with stream progress: later in stream, penalize waste more strongly.
    score += 12.0 * progress * norm_post * norm_post * cap;

    // Dead-space penalty for residuals too small for any plausible item (smooth ramp).
    let dead = 1.0 - (post / 40.0).min(1.0).max(0.0);
    score += 25.0 * dead * dead;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits the post residual (smooth kernel).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 8.0 * (-gap / 20.0).exp();
    }

    // Mild penalty when this bin's residual is far above mean residual (imbalance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: keep it competitive only when open bins are crowded.
    let crowd = (open_bins_count as f64 / 8.0).tanh();
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - crowd) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: residues divisible by small denominators
    // are more likely to be filled by future items.
    let cap = bin_capacity as f64;

    // Fractional class of post residual relative to capacity
    let frac = post_residual as f64 / cap;

    // Reward small post_residual, with harmonic modulation:
    // post_residual in classes {10,20,25,50} are "harmonic" (divisors/fractions of 100)
    if post_residual == 10 || post_residual == 20 || post_residual == 25 || post_residual == 50 {
        score -= 15.0;
    }

    // Lookahead: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // Lookahead: next item fits into post_residual (chaining)
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }
    // Lookahead: next item would NOT fit here anyway; dead space penalty grows
    else if next_item_size > post_residual {
        score += 20.0 + frac * 30.0;
    }

    // Penalize mid-range unusable residuals (dead space) more than tiny ones
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual > 60 {
        score += 10.0; // leaving a very loose bin is fine, new-bin-like
    }

    // Last-chance bin: strong preference to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Many open bins: prefer consolidation (favor filling existing bins)
    score -= (open_bins_count as f64) * 0.5;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in stream: slightly favor opening bins for large items later
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless residual would be small/harmonic
        score += 60.0 - progress * 20.0;
        if item_size >= 50 {
            score -= 30.0; // large items start fresh bins happily
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Harmonic band penalty on post residual: tiny slivers are dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= bin_capacity / 10 {
        score += 60.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    // Harmonic divisibility reward.
    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
    }

    // Lookahead coupling: exact match with next item is a strong signal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (pr - next_item_size as f64);
        } else if bin_residual >= next_item_size {
            // Placement destroys the fit for the next item.
            score += 30.0;
        }
    }

    // Last-chance bin: strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate logic: borrow the "awkward window" idea — open a
    // fresh bin when the current fit leaves an awkward 11..=19 dead zone
    // that nothing can reuse, or when items are large / bins crowded.
    if bin_residual == bin_capacity {
        let size_class = item_size / 20;
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let awkward_fit = post_residual >= 11 && post_residual <= 19;
        if big_item || bins_crowded || size_class >= 3 || awkward_fit {
            score -= 40.0;
        } else {
            score += 70.0 + 0.5 * mean_residual;
        }
    }

    // Fill-fraction reward: favor placements that consume a large share
    // of the bin's remaining space (borrowed from best heuristic).
    let fill_fraction = item_size as f64 / cap;
    score -= fill_fraction * 20.0;

    // Consolidation pressure: prefer bins whose post residual is below
    // the mean residual (tightening the global distribution).
    score += (mean_residual - pr) * 0.05;

    // Stream progression: late-stream conservatism for new bins,
    // greedier tight-fit reward for existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress * (1.0 - pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse buckets; small class = tight fit.
    let class_width: u32 = 12;
    let post_class = post_residual / class_width;
    score -= (class_width.max(1) - post_class.min(class_width)) as f64 * 2.5;

    // Reward near-perfect fills (dead space below class width).
    if post_residual < class_width {
        score -= 35.0;
    }
    // Penalize awkward mid-range dead space (too big to waste, too small to trust).
    if post_residual >= 13 && post_residual <= 24 {
        score += 10.0;
    }

    // Lookahead coupling: strongly favor bins whose leftover hosts the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < class_width {
                score -= 20.0;
            } else if slack < 2 * class_width {
                score -= 6.0;
            }
        } else if post_residual >= 13 {
            // leftover can't host next item: dead-space risk, worse if next is large
            score += 6.0 + (next_item_size.min(100) as f64) * 0.05;
        }
    }

    // Last-chance bin: only fitting bin, prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate logic: penalize opening fresh bins, but relax when
    // remaining space in open bins is large relative to upcoming demand.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If open bins are slack-heavy and next item is large, a fresh bin
        // preserves tight bins for small items.
        if next_item_size > 55 && mean_residual > 20.0 {
            score -= 22.0;
        }
        // Early in stream, opening bins is cheaper; late stream, avoid it.
        let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Fractional capacity coupling: reward filling a large fraction of the bin.
    let fill_fraction = item_size as f64 / cap;
    score -= fill_fraction * 22.0;

    // Mean residual context: consolidate into tight bins when open bins are slack.
    score += (mean_residual - post_residual as f64) * 0.06;

    // Late-stream greediness on tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    score -= progress * 12.0 * (1.0 - post_residual as f64 / cap);

    // Waste ratio guard: penalize leaving residual that exceeds the largest
    // plausible next item by a wide margin (unusable space).
    if post_residual > next_item_size + 30 && next_item_size > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse buckets via integer division. Small classes = tight fit = good.
    let class_width: u32 = 10;
    let post_class = post_residual / class_width; // 0..10
    score -= (class_width.max(1) - post_class.min(class_width)) as f64 * 2.0;

    // Reward "perfect" or near-perfect fills (dead space below class width).
    if post_residual < class_width {
        score -= 30.0;
    }
    // Penalize mid-range dead space that is too small to be useful: 11..=19 awkward.
    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }
    // NEW: also penalize awkward 21..=29 leftovers that can't host mid items
    if post_residual >= 21 && post_residual <= 29 && next_item_size > post_residual {
        score += 6.0;
    }

    // Harmonic coupling with next item: if the leftover exactly (or nearly)
    // accommodates the lookahead item, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < class_width {
            score -= 18.0;
        } else if post_residual < next_item_size && post_residual >= 11 {
            // leftover can't host next item: dead space risk
            score += 8.0;
        }
        // NEW: two-item lookahead chain — leftover big enough for next item
        // plus a small item is very valuable; reward proportional slack.
        if post_residual >= next_item_size * 2 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // NEW: when several bins fit, prefer the tightest — scale a small bonus
    // by how few fitting bins exist (avoid scattering across many bins).
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score -= (3.0 / fitting_bins_count as f64).min(5.0);
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If next item is huge and current post fit is poor, opening
        // a new bin becomes more attractive (reduce the penalty).
        if next_item_size > 60 && post_residual > 25 {
            score -= 30.0;
        }
        // NEW: late in the stream, opening a new bin is rarely worth it —
        // tighten the penalty as we approach the end.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if progress > 0.8 {
            score += 10.0;
        }
    }

    // Fractional capacity coupling: reward filling a large fraction of the bin.
    let fill_fraction = item_size as f64 / cap;
    score -= fill_fraction * 20.0;

    // Mean residual context: when open bins are already slack-heavy,
    // prefer consolidating into tight bins (low residual).
    score += (mean_residual - post_residual as f64) * 0.05;

    // Late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - post_residual as f64 / cap);

    // NEW: exact-fit bonus scaled by item size — big items leaving zero waste
    // are the most valuable placements.
    if post_residual == 0 {
        score -= 20.0 + item_size as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

