    let post_class = post_residual / class_width; // 0..10
    score -= (class_width.max(1) - post_class.min(class_width)) as f64 * 2.0;

    // Reward "perfect" or near-perfect fills (dead space below class width).
    if post_residual < class_width {
        score -= 30.0;
    }
    // Penalize mid-range dead space that is awkward: 11..=19.
    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    // Harmonic coupling with next item: if the leftover exactly (or nearly)
    // accommodates the lookahead item, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < class_width {
            score -= 18.0;
        } else if post_residual < next_item_size && post_residual >= 11 {
            // leftover can't host next item: dead space risk
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If the next item is huge and the current post fit is poor, opening
        // a new bin becomes more attractive (reduce the penalty).
        if next_item_size > 60 && post_residual > 25 {
            score -= 30.0;
        }
        // MUTATION: when open bins are slack-heavy on average, a fresh bin is
        // less harmful — consolidation into tight existing bins is preferred,
        // so ease the new-bin penalty proportionally to mean residual slack.
        let slack_ratio = mean_residual / cap;
        if slack_ratio > 0.35 {
            score -= (slack_ratio - 0.35).min(0.4) * 60.0;
        }
    }

    // MUTATION: two-bin lookahead — if this bin's post residual would exactly
    // fit the next item AND the next-next context is unknown, add a mild extra
    // reward scaled by how scarce fitting bins currently are.
    if next_item_size > 0 && post_residual >= next_item_size {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score -= 10.0 * scarcity;
    }

    // Fractional capacity coupling: reward filling a large fraction of the bin,
    // with a superlinear term to strongly prefer near-full placements.
    let fill_fraction = item_size as f64 / cap;
    score -= fill_fraction * 20.0 + fill_fraction * fill_fraction * 10.0;

    // Mean residual context: when open bins are already slack-heavy,
    // prefer consolidating into tight bins (low residual).
    score += (mean_residual - post_residual as f64) * 0.05;

    // Late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

