pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Fine-grained residual classing: tiny residuals are gold.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 30.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    // Awkward dead-space band: 11..=19 too small for most items.
    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
    }

    // Lookahead coupling with chain analysis.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < class_width {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else if post_residual >= 11 {
            // Leftover too small for next item: mildly penalize but keep usable.
            score += 10.0;
        } else if bin_residual >= next_item_size {
            // This placement destroys the only fit for the next item.
            score += 30.0;
        }
        // Post-placement chain: leftover can still fit another copy of next item.
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after <= 3 {
                score -= 12.0;
            } else if after >= 20 && after <= 30 {
                score -= 6.0;
            } else if after >= 11 && after < next_item_size {
                score += 4.0;
            }
            if after >= next_item_size {
                score -= 10.0;
            }
            if after > 0 && after % 10 == 0 {
                score -= 4.0;
            }
            if after >= 2 * next_item_size {
                score -= 6.0;
            }
        }
        // Near-miss: next item barely misses the leftover — dead space ahead.
        if post_residual < next_item_size && next_item_size - post_residual <= 8 {
