        if next_item_size == post_residual {
            score -= 40.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            // partial chain fit: reward proportionally to how snugly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize wasted residual relative to mean residual
            score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Prefer tight fits overall: small post_residual relative to capacity
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discard near-empty new-bin openings when existing bins fit reasonably well:
    // penalize opening a fresh bin unless it enables a perfect lookahead chain
