    // Harmonic class of post_residual: dead space is only "usable" if a
    // future item (size 1..100) can land in it. Penalize residual classes
    // that are awkward (small but nonzero), reward large usable residuals.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    } else if pr < 10 {
        // Dead space below the minimum item size: penalize heavily.
        score += 25.0;
    } else {
        // Modulo-class penalty: residuals that are not multiples of common
        // gcds (e.g. 5, 10) tend to waste more across the stream.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else {
            score += 2.0;
        }
        // Fraction-of-capacity class thresholds via integer division.
        let quarter = pr / 25; // 0..4 harmonic class
        match quarter {
            0 => score += 8.0,  // 1..24 : nearly dead
            1 => score += 3.0,  // 25..49: small usable
            2 => score -= 2.0,  // 50..74: half-ish, decent
            _ => score -= 4.0,  // 75..99: large usable
        }
    }

    // Lookahead coupling: reward if next item fits in post_residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic match: next item lands here without new bin.
            let tightness = 1.0 - (pr - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * tightness;
            // Extra reward when next item exactly fills post_residual.
            if next_item_size == pr {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how close it was (near-miss = wasted potential).
            let miss = (next_item_size - pr) as f64;
            if miss <= 10.0 {
                score += 4.0; // painful near-miss
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + (post_residual.min(30) as f64) * 0.2;
    }

    // New-bin candidate handling: opening a fresh bin is attractive early
    // in the stream or when open bins are mostly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = mean_residual / bin_capacity as f64;
        // Prefer new bin when existing bins are packed tight and stream is long.
        score = 20.0 - 30.0 * (1.0 - openness) - 10.0 * progress;
        // Never open a new bin for a perfect fit elsewhere.
        if post_residual == 0 && bin_residual != bin_capacity {
            score -= 100.0;
        }
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
