        else if post_residual >= next_item_size && post_residual - next_item_size < class_width { score -= 20.0 ; }
        else if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            score -= 18.0 + 0.08 * (post_residual as f64 - next_item_size as f64) ;
            if after <= 3 { score -= 12.0 ; }
            if after >= 20 && after <= 30 { score -= 6.0 ; }
            if after >= next_item_size { score -= 8.0 ; }
            if after > 0 && after % 10 == 0 { score -= 4.0 ; }
        }
        else if post_residual < next_item_size && post_residual >= 11 { score += 8.0 ; }
        else if bin_residual >= next_item_size { score += 25.0 ; }
