    }

    // Sweet-spot bands for reusable leftovers.
    if post_residual >= 35 && post_residual <= 55 {
        score -= 7.0;
    } else if post_residual >= 56 && post_residual <= 70 && next_item_size > 0 && next_item_size <= 55 {
        score -= 3.0;
    }

    // Crowded-state small-residual preference.
    if fitting_bins_count > 3 && post_residual < class_width {
        score -= 5.0;
    }

    // Perfect-fit anticipation — exact match with current item beats everything.
    if bin_residual == item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Reward bins whose residual remains a multiple of a likely future item.
    if post_residual > 0 && next_item_size > 1 && post_residual % next_item_size == 0 {
        score -= 6.0;
    }

    // Avoid leaving residuals just below common small item sizes (11..=24).
    if post_residual >= 11 && post_residual <= 24 && next_item_size > post_residual {
        score += 5.0;
    }

    // NEW: combined lookahead-residual compaction — if placing the item here leaves
    // a residual that exactly matches a plausible small future item, favor it strongly.
    if post_residual > 0 && post_residual <= 50 && next_item_size > 0
        && next_item_size != post_residual && next_item_size < post_residual
        && post_residual - next_item_size <= 5 {
