pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, weighted by a smooth polynomial in progress.
    let w = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    let mut score = pr * w;

    // Non-linear penalty on wasted residual: quadratic in normalized post_residual,
    // scaled by stream progress (dead space matters more later).
    score += norm_pr * norm_pr * cap * (0.3 + 0.7 * progress);

    // Reward tight fits: cubic decay of bonus as post_residual grows.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * tightness * item_size as f64 * (0.5 + 0.5 * progress);

