        let tightness = pr / (item_size as f64);
        score += 2.0 * tightness;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate and loose placements).
    let pressure = (open_bins_count as f64) * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 25.0 + pressure;
    } else {
        // Filling an existing bin gets a discount under pressure.
        score -= pressure * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover < 10 && leftover > 0 {
            score -= 20.0; // next item will nearly perfectly fill this bin
        } else {
            score += 0.5 * (leftover as f64) / 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item cannot use this residual; small penalty scaled by waste.
        score += 0.3 * pr;
    }

    // Mean residual coupling: if this bin's post-residual deviates upward from the
    // mean residual, penalize (creating outlier dead space).
    let dev = pr - mean_residual;
    if dev > 0.0 {
        score += 0.4 * dev;
    }

    // Stream progression: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Fine-grained residual classing: tiny residuals are gold.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 30.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    // Awkward dead-space band: 11..=19 too small for most items.
    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
    }

    // Lookahead coupling with chain analysis.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < class_width {
            score -= 24.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else if post_residual >= 11 {
            score += 10.0;
        } else if bin_residual >= next_item_size {
            score += 30.0;
        }
        // Post-placement chain: leftover can still fit copies of next item.
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after <= 3 {
                score -= 16.0;
            } else if after >= 20 && after <= 30 {
                score -= 6.0;
            } else if after >= 11 && after < next_item_size {
                score += 4.0;
            }
            if after >= next_item_size {
                score -= 14.0;
            }
            if after > 0 && after % 10 == 0 {
                score -= 4.0;
            }
            if after >= 2 * next_item_size {
                score -= 10.0;
            }
        }
        // Near-miss: next item barely misses the leftover — dead space ahead.
        if post_residual < next_item_size && next_item_size - post_residual <= 8 {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.8 * (8.0 - gap);
        }
        // Two-step lookahead: can next item + one more copy chain fit?
        if post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 95.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        if big_item || bins_crowded {
            score -= 40.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Fill-fraction coupling: reward large items placed in existing bins.
    if bin_residual != bin_capacity {
        score -= (item_size as f64 / cap) * 20.0;
    }

    // Mean-residual consolidation.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Dead-space ratio analysis with scarcity and crowding weights.
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Waste relative to quarter-capacity target.
        if post_residual < bin_capacity / 4 {
            let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
            score += waste * 14.0;
        }
        // Mid-range residual keeps future options open.
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
    }

    // Sweet-spot bands for reusable leftovers.
    if post_residual >= 35 && post_residual <= 55 {
        score -= 7.0;
    } else if post_residual >= 56 && post_residual <= 70 && next_item_size > 0 && next_item_size <= 55 {
        score -= 3.0;
    }

    // Crowded-state small-residual preference.
    if fitting_bins_count > 3 && post_residual < class_width {
        score -= 5.0;
    }

    // Perfect-fit anticipation — exact match with current item beats everything.
    if bin_residual == item_size && bin_residual != bin_capacity {
        score -= 130.0;
    }

    // Reward bins whose residual remains a multiple of a likely future item.
    if post_residual > 0 && next_item_size > 1 && post_residual % next_item_size == 0 {
        score -= 7.0;
    }

    // Avoid leaving residuals just below common small item sizes (11..=24).
    if post_residual >= 11 && post_residual <= 24 && next_item_size > post_residual {
        score += 5.0;
    }

    // NEW: combined coupling — when few bins fit and the residual stays usable
    // by the next item, strongly consolidate instead of spreading waste.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (1.0 - fitting_bins_count as f64 / 2.0);
    }

    // NEW: penalize residuals in the 21..=29 awkward band when the next item
    // cannot use them, to steer placement toward cleaner leftovers.
    if post_residual >= 21 && post_residual <= 29 && next_item_size > post_residual {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: strong baseline penalty; only allow it when no open bin
    // offers a good fit (post_residual would be small or perfectly matched).
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    // 2-step lookahead: reward when the leftover space matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_gap = (post_residual as f64 - nxt).abs();
        // Perfect match: next item exactly fills the residual -> big reward.
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward proportional to tightness of match.
            score -= 15.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item cannot fit the leftover: penalize creating dead space
            // relative to how badly it misses.
            score += 8.0 * (match_gap / bin_capacity as f64);
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.3 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight preference to fill bins early in the stream (keep bins closed).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    // Prefer bins with less residual before placement (best-fit flavor).
    score += 0.2 * bin_residual as f64;

    score
}

