    let mut score = post_residual as f64;

    // Tight fits are valuable: reward low post-residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 4.0 * fill;
        } else {
            // next item won't fit here; penalize leaving large dead space
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 3.0 * dead * dead;
        }
    } else {
        // Last item: prefer leaving zero residual (perfect closure)
        score -= 8.0 * tight;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
