        let pressure = (open_bins_count as f64).ln().max(0.0);
        // early stream: new bins are cheap; late stream: prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 10.0 * (1.0 - progress) - 8.0 * crowded - 2.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            // pairing potential in a fresh bin
            if item_size + next_item_size <= bin_capacity {
                score -= 3.0;
            }
        }
    }

    // Prefer bins with residual close to the mean (balance preservation),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild bonus for using bins that would otherwise waste space.
    if bin_residual < bin_capacity && post_residual > 0 && post_residual < 10 {
        score -= 2.0; // small dead space is fine
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 1.5; // awkward mid-range gap
    }

    score
}

