    // Late in the stream, waste matters more (tighter packing), so weight grows.
    let mut score = r * (1.0 + 0.8 * progress) + 0.35 * cap * rn * rn;

    // Smooth non-linear coupling: post-residual vs mean residual across open bins.
    // Penalize bins whose leftover deviates strongly from the fleet mean (dead-space risk).
    let dev = (r - mean_residual) / cap;
    score += 12.0 * dev * dev * (1.0 + progress);

    // Reward near-perfect fits with a smooth saturating term.
    let fill = 1.0 - rn; // fraction of capacity used by this item
    score -= 30.0 * fill * fill * (2.0 - fill);

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let gap = (r - next_item_size as f64).abs();
        let coupling = (gap / cap).powi(2);
        score -= 20.0 * (-8.0 * coupling).exp() * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling: empty bin gets a mild opening cost that shrinks
    // as the stream progresses (late stream prefers consolidating into open bins).
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    } else {
        // Slight preference for bins that are already committed (fewer open bins better).
        score -= 0.3 * open_bins_count as f64 * progress;
    }

    score
}

