    // residue classes (near-perfect fits) are strongly rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Integer-division thresholds: post_residual / 10 classes
    let class = pr / 10; // 0..=10
    match class {
        0 => score -= 12.0,          // near-perfect fill
        1 => score -= 7.0,           // excellent
        2 => score -= 4.0,           // good
        3 => score -= 2.0,           // decent
        4 => score -= 0.5,
        5 => score += 1.0,           // half-full leftover: awkward
        6 => score += 2.5,
        7 => score += 4.0,
        8 => score += 5.5,
        9 => score += 7.0,           // mostly empty bin used: wasteful
        _ => score += 8.0,
    }

