    // sizes (multiples of 5, 10) are reusable dead-space-wise.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 3.0;
        } else if pr % 5 == 0 {
            score -= 1.5;
        } else {
            score += 0.5; // odd residues are less likely reusable
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        let ni = next_item_size;
        if ni == pr {
            score -= 10.0;
        } else if ni <= pr {
            // next fits: leftover after next item drives preference
            let post2 = pr - ni;
            score -= 4.0 - (post2 as f64) * 0.05;
        } else {
            // next item won't fit here: penalize proportionally
            score += ((ni - pr) as f64).min(20.0) * 0.15;
        }
    } else {
        // last item: prefer tightest fit
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a good fit. Penalize it by mean residual pressure.
    if bin_residual == bin_capacity {
        score += 9.0;
        if open_bins_count > 0 {
            score += (open_bins_count as f64) * 0.4;
        }
        // early stream: opening bins is cheap-ish
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 4.0;
    }

    // Mean residual alignment: prefer bins close to the mean residual
    // (keeps population uniform, preserves large slots elsewhere).
    let dev = (prf - mean_residual).abs();
    score += dev * 0.08;

    // Fractional capacity coupling: reward filling beyond 70% of capacity
    let fill_frac = (bin_residual as f64 - prf) / cap;
    if fill_frac > 0.7 {
        score -= 3.0;
    } else if fill_frac < 0.2 {
        score += 2.0;
    }

    score
}

