    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 32.0; // tiny slivers are effectively full: reward slightly
    } else if post_residual < 25 {
        score += 40.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
