    // Reward tight fits.
    let fill = item_size as f64 / cap;
    score -= 60.0 * fill;

    // Consolidation pressure.
    score += 6.0 * (open_bins_count as f64).sqrt();

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Lookahead on next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after < 10 {
                score -= 18.0; // next item leaves a near-perfect fit
            } else if after >= next_item_size {
                score -= 30.0; // chainable residual
            } else {
                score -= 20.0 - 0.1 * after as f64;
            }
        } else if post_residual >= 11 {
            score += 10.0;
        } else if bin_residual >= next_item_size {
            score += 30.0;
        }
    }

    // Mean-residual coupling: prefer fuller bins.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
