pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward bins whose residual can host the lookahead item exactly
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0; // still usable for next item
    } else if next_item_size > 0 && post_residual > 0 {
        score += 15.0; // gap too small for lookahead: dead space risk
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: keep it neutral-to-slightly-high unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 12.0;
        // Opening fresh bin is attractive early in the stream
        score -= 10.0 * (1.0 - progress);
    }

    score
}

