pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect (zero-waste) fits.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too: good, but less than perfect chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - 0.5 * slack;
        } else {
            // Next item cannot use the leftover; penalize proportionally to waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "tight" bins — using them is valuable; bins above mean are loose.
    let residual_f = bin_residual as f64;
    let rel = residual_f - mean_residual;
    score += 0.4 * rel;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize creating large dead space relative to capacity.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 50.0; // tiny unusable slivers are wasteful
    }

    // Late in the stream, prefer tighter packing (less tolerance for leftovers).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * progress * dead;

    // Slight preference to fill existing bins rather than open new ones
    // when many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
