        }
        // NEW: near-perfect dead-zone ridge — residuals just above 10% of capacity
        // are hard to fill later; penalize the 0.05..0.12 ridge softly.
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // NEW: reward residuals in the 20..45% band centered at 32.5% when they
