    // tail keeps bins tight; reward deeper exact matches.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after == next_item_size {
            score -= 10.0;
        }
    }

    // Scarcity-aware urgency: when few bins fit the item, prefer the bin that
    // leaves the most usable residual for the next item.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 2.0 * (1.0 - (fitting_bins_count as f64) / 2.0);
        }
    }

