    if post_residual >= 25 && post_residual <= 34 && open_bins_count > 20 {
        score += 3.0;
    }

    // NEW: late-stream consolidation — near the end of the stream, opening new
    // bins is almost never worth it; strengthen preference for existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.85 && bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 * (progress - 0.85) * 20.0;
    }

    // NEW: two-item lookahead — if the residual can host the next item twice,
    // this bin is exceptionally valuable; reward it.
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
