            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack);
        } else {
            // Dead space: post_residual can't host the next item.
            score += 8.0 + 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless it enables a great future fit
    // or current open bins are nearly full (mean residual small).
    if bin_residual == bin_capacity {
        let mut new_bin_score = 25.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // fresh bin leaves room for next item if item is small
            if bin_capacity - item_size >= next_item_size {
                new_bin_score -= 15.0;
            }
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 15.0 * progress;
        // many open bins with slack: discourage opening more
        new_bin_score += 0.5 * open_bins_count as f64;
        new_bin_score -= 0.1 * mean_residual;
        score = score.max(new_bin_score);
        score += new_bin_score * 0.0 + 0.0;
        score = if fitting_bins_count > 1 { score + 10.0 } else { score };
    }

    // Prefer bins whose residual deviates below mean (consolidate slack).
    if bin_residual != bin_capacity {
        score += 0.05 * (mean_residual - post_residual as f64);
    }

    score
}

