pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 32.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < class_width {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else if post_residual >= 11 {
            score += 10.0;
        } else if bin_residual >= next_item_size {
            score += 30.0;
        }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after <= 3 {
                score -= 14.0;
            } else if after >= 20 && after <= 30 {
                score -= 6.0;
            } else if after >= 11 && after < next_item_size {
                score += 4.0;
            }
            if after >= next_item_size {
                score -= 12.0;
            }
            if after > 0 && after % 10 == 0 {
                score -= 4.0;
            }
            if after >= 2 * next_item_size {
                score -= 10.0;
            }
        }
        if post_residual < next_item_size && next_item_size - post_residual <= 8 {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.8 * (8.0 - gap);
        }
        if post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 95.0;
    }

    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        if big_item || bins_crowded {
            score -= 40.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    if bin_residual != bin_capacity {
        score -= (item_size as f64 / cap) * 20.0;
    }

    score += (mean_residual - post_residual as f64) * 0.05;

    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        if post_residual < bin_capacity / 4 {
            let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
            score += waste * 14.0;
        }
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        // Borrowed: narrow dead-zone penalty around 5-12% residual.
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Borrowed: reward residuals near 32.5% band center when next item can't use them.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
    }

    if post_residual >= 35 && post_residual <= 55 {
        score -= 7.0;
    } else if post_residual >= 56 && post_residual <= 70 && next_item_size > 0 && next_item_size <= 55 {
        score -= 3.0;
    }

    if fitting_bins_count > 3 && post_residual < class_width {
        score -= 5.0;
    }

    // Perfect fit with current item.
    if bin_residual == item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Residual a multiple of likely future item.
    if post_residual > 0 && next_item_size > 1 && post_residual % next_item_size == 0 {
        score -= 6.0;
    }

    // Avoid residuals just below common small item sizes.
    if post_residual >= 11 && post_residual <= 24 && next_item_size > post_residual {
        score += 5.0;
    }

    // Exact-fit chain anticipation.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after == next_item_size {
            score -= 8.0;
        }
    }

    // Scarcity-aware urgency.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 2.0 * (1.0 - (fitting_bins_count as f64) / 2.0);
        }
    }

    // Penalize residuals in the 25..=34 dead zone when many bins remain open.
    if post_residual >= 25 && post_residual <= 34 && open_bins_count > 20 {
        score += 3.0;
    }

    // NEW: late-stream compaction — as the stream nears its end, tighten preference
    // for bins leaving small residuals, since fewer future items remain to fill gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && post_residual > 0 {
        let small_tail = (post_residual as f64 / cap) < 0.15;
        if small_tail {
            score -= 5.0 * (progress - 0.7) * 10.0;
        }
    }

    // NEW: when next item nearly fills the resulting residual exactly, boost the
    // lookahead reward proportionally to how tight the two-step fit is.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 6 {
            score -= 2.0 + (6 - after) as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_n = pr / cap;
    let fit_n = fitting_bins_count as f64;

    // Base: raw post residual
    let mut score = pr;

    // Non-linear polynomial coupling of residual with stream progress:
    // early on, prefer filling bins tightly (quadratic growth of penalty with residual);
    // later, weight residual even more via cubic term.
    let poly = pr_n * pr_n * (1.0 + 2.0 * progress) + pr_n * pr_n * pr_n * (3.0 * progress);
    score += poly * cap * 0.5;

    // Reward tight fits (small post_residual) with smooth exponential bonus
    score -= 30.0 * (-pr_n * 6.0).exp();

    // Penalize bins whose residual deviates from mean residual (fragmentation spreading)
    let dev = (mean_residual - pr).abs() / cap;
    score += 15.0 * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    } else {
        // Mild reward when many bins fit (choice available, pick best fit)
        score += 2.0 * (fit_n - 1.0).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= 25.0 * (1.0 - gap) * (1.0 - gap) * (1.0 + progress);
        } else {
            // next item won't fit here: slight penalty proportional to overflow
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // New-bin candidate handling: neutral-ish score so it only wins when open bins are bad
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - 10.0 * (1.0 - progress);
    }

    // Many open bins: discourage spreading, favor consolidation into existing bins
    score += (open_bins_count as f64).ln() * pr_n * 4.0;

    // Item size coupling: large items prefer bins with just-enough space
    score += 8.0 * (it / cap) * pr_n * (1.0 - pr_n);

    score
}

