    else if post_residual >= 20 { score -= 1.5; }
    else if post_residual > 0 { score -= 2.5; }     // tight fill

    // Dead space: leftover below the smallest plausible item is unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual
    // (harmonic chaining), penalize if next item nearly fits but not quite.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 - 0.05 * nxt;
        } else if nxt - post <= 10.0 {
            score += 4.0; // teasing near-miss creates future fragmentation
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin for a single item.
    if fitting_bins_count == 1 {
        score -= 9.0 + 5.0 * progress;
    }

    // Mild preference for consolidating into bins already below average residual.
    score += 0.08 * (mean_residual - post);

    // Slight late-stream conservatism: prefer tighter fits as stream progresses.
    score += 3.0 * progress * (post / cap);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let mut score = post_residual as f64 ;
    let class_width : u32 = 10 ;
    if post_residual == 0 { score -= 1000.0 ; }
    else if post_residual < class_width { score -= 32.0 ; }
    if post_residual >= 11 && post_residual <= 19 { score += 12.0 ; }
    if next_item_size > 0 {
        if post_residual == next_item_size { score -= 45.0 ; }
        else if post_residual >= next_item_size && post_residual - next_item_size < class_width { score -= 18.0 ; }
        else if post_residual >= next_item_size { score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64) ; }
        else if post_residual < next_item_size && post_residual >= 11 { score += 8.0 ; }
        // near-miss: residual slightly below next item is nearly dead
        if post_residual < next_item_size && next_item_size - post_residual <= 8 { score += 4.0 + 0.8 * (8 - (next_item_size - post_residual)) as f64 ; }
        // lookahead two-step: reward residuals that fit next item plus a small follow-up
        let after = post_residual - next_item_size ;
        if post_residual >= next_item_size {
            if after <= 3 { score -= 12.0 ; }
            if after >= 20 && after <= 30 { score -= 6.0 ; }
            if after >= next_item_size { score -= 8.0 ; }
        }
    }
    // penalize mid-range dead space that fits nothing typical
    if post_residual >= 31 && post_residual <= 45 && next_item_size > post_residual { score += 6.0 ; }
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2 ;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0 ;
        if big_item || bins_crowded { score -= 40.0 ; }
        else {
            score += 45.0 ;
            if next_item_size > 60 && post_residual > 25 { score -= 30.0 ; }
            if open_bins_count > 40 && next_item_size >= 50 { score -= 8.0 ; }
        }
    }
    // slight preference for tighter fits when many bins compete
    if fitting_bins_count > 3 && post_residual < class_width { score -= 4.0 ; }
    // dead-space shaping: discourage small-but-useless residuals, encourage mid bands
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap ;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0) ;
        if dead_ratio < 0.10 { score += dead_ratio * 100.0 * (0.5 + (open_bins_count as f64 / 60.0).min(1.0)) ; }
        else if dead_ratio > 0.55 && next_item_size > 0 && (next_item_size as f64) > dead_ratio * cap { score -= 10.0 * (1.0 - scarcity) ; }
        else if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let dist = ((post_residual as f64) - 0.325 * cap).abs() ;
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0) ;
        }
        // waste penalty relative to quarter capacity
        if post_residual < bin_capacity / 4 {
            let waste = (bin_capacity / 4 - post_residual) as f64 / cap ;
            score += waste * 12.0 ;
        }
    }
    // stream-progress drift: prefer consolidating into open bins early, fresh bins late
    let progress = step_index as f64 / total_items.max(1) as f64 ;
    if bin_residual != bin_capacity { score -= 8.0 * progress ; }
    // mean-residual pull toward tighter fills
    score += (mean_residual - post_residual as f64) * 0.05 ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the next item
    // are wasted space. Penalize proportionally to how "dead" the gap is.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 2.5 * dead;
        } else {
            // Gap that can still serve the next item: reward it.
            score -= 1.0 * (post_residual as f64 - next_item_size as f64).min(20.0);
        }
    }

    // Perfect fit bonus: leaving nothing behind is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize very tight fits only when they create tiny unusable slivers
    // relative to capacity scale.
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 8.0 * tightness * tightness;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (strong reward).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage new-bin opening
    // (the new bin has bin_residual == bin_capacity and gains nothing here,
    // so open bins get a relative advantage).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 - 0.5 * progress);
    score -= 3.0 * pressure * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Mild preference for bins with below-mean residual (consolidate fullness).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(-30.0);

    score
}

