    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // chain of two perfect fits
        } else if next_item_size < post_residual {
            let l_post = post_residual - next_item_size;
            // reward tight 2-step fits, penalize large leftover
            score -= 60.0 * (1.0 - l_post as f64 / bin_capacity as f64);
            if l_post <= 5 {
