    score -= 30.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening new bins when open bins fit well
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count > 0 {
            score += 80.0;
        }
        // early in stream, allow more bin openings
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 100.0 * (1.0 - progress);
    }

    // Slight preference to fill larger residual bins when many bins open
    if open_bins_count > 8 {
        score += 0.05 * post_residual as f64;
    }

    score
}

