    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small but unusable residuals: dead space in (0..10) is worst.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it if it fits well.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 0.3 * item_size as f64;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 35.0;
            } else {
                score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot use leftover; penalize proportionally.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Prefer filling bins with larger residual when many bins are open (consolidation).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be picky (favor tight fits more); late, just pack.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.3 * progress;

    // New-bin candidate: only attractive when open bins have poor fits or few fitting options.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let crowded = (open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64)) * 0.05;
