            - 30.0 * pressure
            - 15.0 * progress
            + crowded
            + 0.2 * (item_size as f64).max(next_item_size as f64);
        // If a very tight fit exists elsewhere, discourage new bin.
        if tightness > 0.9 && fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    score
}

