    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, mildly compressed non-linearly
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Smooth coupling: prefer bins whose post-residual matches the next item size
    // (quadratic mismatch penalty, scaled by stream progress)
    if next_item_size > 0 {
        let mismatch = norm_post - norm_next;
        score += (120.0 * (0.3 + 0.7 * progress)) * mismatch * mismatch;
        // Reward when next item fits perfectly into resulting residual
        if post_residual >= next_item_size {
            score -= 8.0 * norm_next * (1.0 - progress * 0.5);
