    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Crowd penalty: with many open bins, prefer tightening existing bins
    let crowd = (open_bins_count as f64).ln1p();
    score += 2.0 * crowd * (norm_post - 0.5).abs();

    // Deviation from mean residual: prefer bins tighter than average
    score -= 4.0 * ((mean_residual - post) / cap).clamp(-1.0, 1.0);

    // Smooth new-bin discouragement: empty bins get a progress-dependent penalty
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress * progress;
    }

    score
}

