pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Fine-grained residual classes.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 32.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    // Awkward dead-space band: 11..=19 rarely fits future items.
    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
    }

    // Lookahead coupling: exact/near match with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else if post_residual >= 11 {
            score += 10.0;
        } else if bin_residual >= next_item_size {
            score += 30.0;
        }
        // Chain-friendliness: residual can host next item more than once.
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after <= 3 {
                score -= 12.0;
            } else if after >= 20 && after <= 30 {
                score -= 6.0;
            } else if after >= next_item_size {
                score -= 8.0;
            }
            if after > 0 && after % 10 == 0 {
                score -= 4.0;
            }
        }
        // Just-barely-cannot-fit penalty.
        if post_residual < next_item_size && next_item_size - post_residual <= 8 {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.8 * (8.0 - gap);
        }
        if post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        if big_item || bins_crowded {
            score -= 40.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Fill-fraction coupling.
    if bin_residual != bin_capacity {
        score -= (item_size as f64 / cap) * 20.0;
    }

    // Mean-residual consolidation.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Dead-space shaping (borrowed refinement).
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Mid-band residual that likely hosts next item.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Waste below quarter capacity.
        if post_residual < bin_capacity / 4 {
            let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
            score += waste * 14.0;
        }
        // Sweet-spot 30..=60 residual, more valuable early.
        if post_residual >= 30 && post_residual <= 60 {
            let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
    }

    score
}

