pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item-size classes (10, 20, 25, 50) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut bonus = 0.0;

    if pr == 0 {
        bonus -= 60.0; // perfect fit: ideal
    } else {
        // integer-division thresholds: how many "typical" items still fit
        let fits10 = pr / 10;
        let fits20 = pr / 20;
        let fits25 = pr / 25;
        let fits50 = pr / 50;
        let harmonic = (fits10 + 2 * fits20 + 3 * fits25 + 6 * fits50) as f64;
        bonus -= harmonic * 1.5;

        // modulo classes: exact divisibility => future items can tile it
        if pr % 10 == 0 { bonus -= 8.0; }
        if pr % 20 == 0 { bonus -= 6.0; }
        if pr % 25 == 0 { bonus -= 6.0; }
        if pr % 50 == 0 { bonus -= 8.0; }
    }

    // Lookahead: does the next item tile into the post-residual exactly?
    if next_item_size > 0 && next_item_size <= pr {
        bonus -= 12.0;
        if pr % next_item_size == 0 { bonus -= 10.0; }
        if pr - next_item_size <= 5 { bonus -= 15.0; } // near-perfect pair
    } else if next_item_size > pr && next_item_size > 0 {
        bonus += 10.0; // next item won't fit here: dead space risk
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        bonus -= 20.0;
    } else {
        bonus += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize leaving tiny unusable slivers (dead space)
    if pr > 0 && pr < 10 {
        bonus += 25.0;
    }

    // New-bin candidate: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let new_bin_bonus = 55.0 - 30.0 * progress - 8.0 * congestion;
        bonus += new_bin_bonus.max(-45.0);
    }

    // Tightness reward: prefer bins that were nearly full before placement
    let tightness = 1.0 - (bin_residual as f64 / cap);
    bonus -= 10.0 * tightness;

    // Mild global pressure: when many bins are open, pack tighter
    score += (open_bins_count as f64).ln1p() * 2.0;

    score += bonus;
    score
}

