                score -= 6.0;
            } else if after >= 11 && after < next_item_size {
                score += 4.0;
            }
            if after >= next_item_size {
                score -= 12.0;
            }
            if after > 0 && after % 10 == 0 {
                score -= 4.0;
            }
            if after >= 2 * next_item_size {
                score -= 10.0;
            }
            if after == next_item_size {
                score -= 8.0;
            }
        }
        if post_residual < next_item_size && next_item_size - post_residual <= 8 {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.8 * (8.0 - gap);
        }
        if post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
        // near-perfect chain: residual within 2 of next item after placement
        if post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 95.0;
    }

    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        if big_item || bins_crowded {
            score -= 40.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    if bin_residual != bin_capacity {
        score -= (item_size as f64 / cap) * 20.0;
    }

    score += (mean_residual - post_residual as f64) * 0.05;

    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        if post_residual < bin_capacity / 4 {
            let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
            score += waste * 14.0;
        }
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        // narrow dead-space band refinement (from best heuristic)
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // penalize residuals that cannot fit next item but sit just below it
        if next_item_size > 0 && post_residual < next_item_size && dead_ratio > 0.15 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
        }
    }

    if post_residual >= 35 && post_residual <= 55 {
        score -= 7.0;
    } else if post_residual >= 56 && post_residual <= 70 && next_item_size > 0 && next_item_size <= 55 {
        score -= 3.0;
    }

    if fitting_bins_count > 3 && post_residual < class_width {
        score -= 5.0;
    }

    // Perfect fit with current item.
    if bin_residual == item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Residual a multiple of likely future item.
    if post_residual > 0 && next_item_size > 1 && post_residual % next_item_size == 0 {
        score -= 6.0;
    }

    // Avoid residuals just below common small item sizes.
    if post_residual >= 11 && post_residual <= 24 && next_item_size > post_residual {
        score += 5.0;
    }

    // Scarcity-aware urgency: prefer bins leaving usable residual for next item.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 2.0 * (1.0 - (fitting_bins_count as f64) / 2.0);
        }
    }

    // Penalize residuals in the 25..=34 dead zone when many bins are open.
    if post_residual >= 25 && post_residual <= 34 && open_bins_count > 20 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the minimum item (1..)
    // are wasted; heavier penalty for mid-range unusable gaps.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        // penalize gaps below ~10 units severely (unusable dead space)
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual < 25 {
            score += 8.0 * dead * 100.0; // awkward small gap
        } else {
            score -= 4.0 * dead; // large usable residual is fine
        }
    } else {
        // perfect fit
        score -= 30.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 15.0 * (fill_ratio - 0.85);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over opening new ones; make new-bin candidate less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins are open
        score += 10.0 + 2.5 * open_bins_count as f64 * (0.5 + progress);
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits in the post-residual, reward keeping
    // this residual; otherwise slightly penalize leaving a gap that wastes
    // the next item's potential.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Mild preference for bins below the mean residual (balance spreading)
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
