pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of post_residual with next item is gold.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nx).abs();
        // Strong reward for exact fit of the NEXT item into the leftover space.
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Penalize mismatch scaled by how far next item misses the hole.
            score += diff * 0.6;
            // If next item cannot fit in this residual at all, mild penalty.
            if pr < nx {
                score += (nx - pr) * 0.35;
            }
        }
        // Reward residuals that keep the hole large enough to stay useful
        // relative to the mean residual across open bins.
        if pr >= mean_residual {
            score -= 4.0;
        } else {
            score += (mean_residual - pr) * 0.25;
        }
    } else {
        // Last item: just minimize waste directly.
        score += post_residual as f64 * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more when few bins are open
    // or when an existing bin gives a decent (small) post_residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = 20.0 + 15.0 * (1.0 - progress);
        // If the current item nearly fills a bin, opening fresh is fine.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            nb -= 15.0;
        }
        // If many open bins already have large residuals, opening new is worse.
        nb += mean_residual * 0.15;
        score += nb;
    }

    // Tight-fit reward: small post_residual is generally good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Slight preference to keep number of open bins low when many are open.
    if open_bins_count > 8 {
        score -= 3.0;
    }

    score
}

