        }
        // chain-friendly residuals
        let chain = post_residual.saturating_sub(next_item_size);
        if chain >= next_item_size {
            score -= 10.0;
        }
        if chain > 0 && chain % 10 == 0 {
            score -= 4.0;
        }
    }

    // dead-space shaping
    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // mid-band residuals useful for future mid-size items
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
    }

    // new-bin decision
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        if big_item || bins_crowded {
            score -= 40.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // global residual alignment
    score += (mean_residual - post_residual as f64) * 0.05;

    // waste penalty in the awkward quarter-band
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    // prefer mid residuals (35-55) that commonly chain with typical items
    if post_residual >= 35 && post_residual <= 55 {
        score -= 7.0;
    } else if post_residual >= 56 && post_residual <= 70 && next_item_size > 0 && next_item_size <= 55 {
        score -= 3.0;
    }

    // tight fit bonus when many bins compete
    if fitting_bins_count > 3 && post_residual < class_width {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post_residual proportionally harder
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * item_size as f64;

    // Penalize dead space: residuals too small for any future item (items >= 1)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong bonus to use the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 120.0;
        } else {
            score -= 40.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }
    // Penalize if next item would fit residual but not post_residual
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 25.0;
    }

    // New-bin candidate logic: empty bin gets penalty unless open bins are poor fits
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fit_gap = (bin_capacity as f64 - item_size as f64) - mean_residual.abs();
        let mut newbin_pen = 40.0 + 60.0 * progress;
        // If mean residual across open bins is large, opening new bin is wasteful
        if mean_residual > item_size as f64 {
            newbin_pen += 30.0;
        }
        // Few fitting bins -> maybe new bin is fine
        if fitting_bins_count == 0 {
            newbin_pen -= 50.0;
        }
        if avg_fit_gap < 0.0 {
            newbin_pen -= 10.0;
        }
        score += newbin_pen;
    }

    // Prefer bins with residual close to item (best-fit flavor) among many options
    if fitting_bins_count > 1 {
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += 20.0 * waste_ratio;
    }

    // Time horizon: late in stream, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference to balance residuals toward mean
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect and near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Exact next-item match: chain the next item perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            // Leaving a residual the next item can also fill is great.
            if after == 0 {
                score -= 50.0;
            } else if after <= 3 {
                score -= 20.0;
            } else if after < 10 {
                score -= 12.0;
            } else if after <= 30 {
                score -= 6.0;
            } else {
                score -= 4.0 + 0.05 * (after as f64);
            }
            // Residual that can host next item twice is excellent.
            if after >= next_item_size {
                score -= 8.0;
            }
        } else {
            // Dead space: gap below next item size.
            let dead = (next_item_size - post_residual) as f64;
            if dead <= 8.0 {
                score += 3.0 + 0.6 * (8.0 - dead);
            } else if dead <= 20.0 {
                score += 8.0 * dead / 20.0;
            } else {
                score += 6.0;
            }
        }
    }

    // New-bin candidate logic: open a new bin only for big items or when
    // open bins are crowded with small residuals.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let crowded = mean_residual < cap * 0.25 && open_bins_count > 0;
        if big_item || crowded {
            score -= 45.0;
        } else {
            score += 50.0;
            // If the next item is large and this fresh bin could host both,
            // opening is more attractive.
            if next_item_size > 55 && post_residual > 30 {
                score -= 25.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    // Last-chance pressure: only fitting bin should be used.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count >= 2 {
        // With alternatives, prefer tighter bins (smaller post_residual wins naturally).
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        score += 5.0 * scarcity;
    }

    // Waste penalty for small residuals relative to capacity.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 15.0;
    }

    // Consolidation: prefer fuller bins (below-mean residual).
    score += 0.08 * (mean_residual - post_residual as f64).max(-40.0);

    // Dead-ratio bands: residuals in the 20-45% band are valuable staging
    // space for medium items; reward proximity to the band center.
    let dead_ratio = post_residual as f64 / cap;
    if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
        let band_center = 0.325 * cap;
        let dist = (post_residual as f64 - band_center).abs();
        score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
    }

    // Open-bin pressure: discourage new bins when many are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 2.0 * pressure * (bin_capacity - bin_residual) as f64 / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Later in the stream, tight fits (small post_residual) matter more;
    // dead space is penalized super-linearly.
    let norm_post = post / cap; // in [0,1]
    let tightness = 1.0 - norm_post; // fraction filled after placement
    let progress_coupling = (0.5 + 0.5 * progress) * (norm_post * norm_post) * cap;
    let tight_reward = tightness * tightness * (10.0 + 20.0 * progress);
    score -= tight_reward;
    score += progress_coupling;

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let snug = 1.0 - ((post - nx) / cap);
            score -= 8.0 * snug * snug * (1.0 + progress);
        } else {
            // Penalize leaving a gap that the next item cannot use,
            // scaled by how much of the residual is wasted.
            let waste = (post - nx).min(post) / cap;
            score += 12.0 * waste * waste * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - norm_post);
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin offers a good fit. Base cost grows
    // with open_bins_count (bin count economy), decays with mean residual
    // saturation across open bins.
    if bin_residual == bin_capacity {
        let mean_sat = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let base = cap * (0.35 + 0.15 * progress);
        score = base + cap * (1.0 - mean_sat).powi(2) + 2.0 * open_bins_count as f64;
        // If this item nearly fills a fresh bin, opening is cheap.
        let fill = item_size as f64 / cap;
        score -= 10.0 * fill * fill;
    } else {
        // Prefer bins whose residual is close to the item (best fit flavor)
        // via smooth cubic penalty on post_residual relative to mean residual.
        let dev = (post - mean_residual) / cap;
        score += 5.0 * dev * dev * dev.abs().max(0.0) * cap * 0.1;
    }

    score
}

