pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small unusable" classes (<=10, or awkward mid sizes) are good closures.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Perfect fit reward: post_residual exactly divisible into common divisors
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual % 10 == 0 && post_residual <= 30 {
        score -= 40.0; // leftover usable by the smallest items (1..=10 range)
    }

    // Penalize dead space: leftover too small for the smallest item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Integer division threshold: leftover in [10, 25) is semi-usable
    if (10..25).contains(&post_residual) {
        score += 8.0;
    }

    // Harmonic coupling with next item: reward if next item fits the leftover
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / cap_f);
        } else {
            // next item won't fit here; penalize based on how wasted the leftover is
            score += 15.0 * (next_item_size - post_residual) as f64 / cap_f;
        }
        // modulo-class match: leftover and next item share a divisor class of 10
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is bad
    if bin_residual == bin_capacity {
        // base penalty so new bins aren't opened frivolously
        score += 90.0;
        // but if the item is huge relative to capacity and mean residual is low,
        // opening fresh is attractive
        let frac = item_size as f64 / cap_f;
        if frac > 0.7 && mean_residual < frac * cap_f {
            score -= 80.0;
        }
        if next_item_size > 0 && next_item_size as f64 / cap_f > 0.8 {
            score -= 30.0; // keep space clean for a big follower
        }
    }

    // Progress-aware mild pressure to consolidate early, spread late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (1.0 - post_f / cap_f);

    // Prefer bins below mean residual (tighter bins) slightly
    score += 0.1 * (mean_residual - post_f).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 32.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < class_width {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else if post_residual >= 11 {
            score += 10.0;
        } else if bin_residual >= next_item_size {
            score += 30.0;
        }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after <= 3 {
                score -= 14.0;
            } else if after >= 20 && after <= 30 {
                score -= 6.0;
            } else if after >= 11 && after < next_item_size {
                score += 4.0;
            }
            if after >= next_item_size {
                score -= 12.0;
            }
            if after > 0 && after % 10 == 0 {
                score -= 4.0;
            }
            if after >= 2 * next_item_size {
                score -= 10.0;
            }
        }
        if post_residual < next_item_size && next_item_size - post_residual <= 8 {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.8 * (8.0 - gap);
        }
        if post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 95.0;
    }

    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        if big_item || bins_crowded {
            score -= 40.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    if bin_residual != bin_capacity {
        score -= (item_size as f64 / cap) * 20.0;
    }

    score += (mean_residual - post_residual as f64) * 0.05;

    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        if post_residual < bin_capacity / 4 {
            let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
            score += waste * 14.0;
        }
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        // borrowed: mid-band dead-space shaping around 0.325 capacity
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * ((1.0 - dist / (0.125 * cap)).max(0.0));
        }
        // borrowed: penalize residuals just below next item (unusable sliver)
        if next_item_size > 0 && post_residual < next_item_size && dead_ratio > 0.15 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
        }
        // borrowed: reward near-perfect chain fits
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
        // borrowed: low dead-ratio precision band
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // borrowed: scarce-fit large-residual anticipation
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
