    }

    // Scarcity-aware urgency.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 2.0 * (1.0 - (fitting_bins_count as f64) / 2.0);
        }
    }

    // Penalize dead-zone band when many bins remain open.
    if post_residual >= 25 && post_residual <= 34 && open_bins_count > 20 {
        score += 3.0;
    }

    // NEW: late-stream tightening — as the stream ends, strongly prefer bins
    // whose residual matches the next item exactly, since fewer chances remain.
    if next_item_size > 0 && post_residual == next_item_size {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // NEW: discourage opening new bins when existing bins can still absorb the
    // next item too (combined fit lookahead).
    if bin_residual == bin_capacity && next_item_size > 0 && open_bins_count > 0
        && mean_residual >= next_item_size as f64 && item_size <= 30 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are wasted.
    let dead_threshold = 12.0 + 0.08 * (bin_capacity as f64); // ~20 for C=100
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    }

    // Reward tight fits (small relative slack).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins.
    score += 0.4 * open_bins_count as f64;

    // Penalize bins whose residual deviates far below the mean (fragmented bins).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item would be blocked by post-residual, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size {
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // New-bin candidate: baseline competitive score; opened only when fits are poor.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64
            + 0.4 * open_bins_count as f64
            + 10.0
            - tightness * 5.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    // Late-stream nudge: toward the end, avoid leaving many near-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

