    }

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 10.0; // big next item: fresh bin is fine
