        // mid-band residuals useful for typical items
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64 ;
            let stream_left = (remaining / total_items . max (1) as f64) . min (1.0) ;
            score -= 4.0 + 3.0 * stream_left ;
        }
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap ;
            let dist = (post_residual as f64 - band_center) . abs () ;
            score -= 6.0 * (1.0 - dist / (0.125 * cap)) . max (0.0) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post residual (tight fit), with non-linear squashing
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Reward near-perfect fits: strong subtraction as post_residual -> 0
    let tightness = 1.0 - post / cap;
    score -= 30.0 * tightness * tightness * tightness;

    // Non-linear coupling of tightness with stream progress:
    // early on, keep bins flexible; late, squeeze aggressively
    score -= 25.0 * tightness * (0.5 + progress * progress);

    // Lookahead: bonus if next item fits exactly into the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 18.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // post residual too small for next item: penalize dead space
            score += 8.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly.
    // Empty bin has post_residual == capacity, so tightness ~ 0; add a mild
    // offset that shrinks with progress so late stream prefers filling bins.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    } else {
        // Slight penalty relative to mean residual: avoid fragmenting bins
        // that are already much emptier than average
        let dev = (post - mean_residual) / cap;
        score += 6.0 * dev * dev.abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Fine-grained residual class bands (best-heuristic style: strong reward for tiny residuals).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 32.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    // Awkward dead-space band: 11..=19 too small for most items.
    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
    }

    // Lookahead coupling: exact/near match with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
            // Chain potential: residual can host next item twice.
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 10.0;
            }
            if chain >= 2 * next_item_size {
                score -= 6.0;
            }
        } else if post_residual >= 11 {
            // This placement destroys the fit for the next item.
            score += 10.0;
        } else if bin_residual >= next_item_size {
            score += 30.0;
        }
        // After-next tightness: residual within 2 of next item.
        if post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
        // Near-miss penalty: residual just below next item.
        if post_residual < next_item_size && next_item_size - post_residual <= 8 {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.8 * (8.0 - gap);
        }
    }

    // Dead-space ratio shaping (from best heuristic).
    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
