        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
    }

    // Last-chance bin: strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        if big_item || bins_crowded {
            score -= 40.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Fill-fraction coupling: reward large items placed in existing bins.
    if bin_residual != bin_capacity {
        score -= (item_size as f64 / cap) * 20.0;
    }

    // Mean-residual consolidation.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Waste penalty for residuals just under a quarter capacity.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
