    // Residuals that are multiples of 10 are "harmonic" — small items (>=10)
    // can exactly fill them later, so reward them.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 12.0;
    } else {
        // Penalize non-harmonic dead space, worse the smaller it is
        let r = post_residual as f64;
        if r > 0.0 && r < 10.0 {
            score += 25.0; // tiny unusable sliver
        } else {
            score += (post_residual % 10) as f64 * 0.8;
        }
    }

    // Integer-division thresholds on post_residual
    let post = post_residual;
    if post == 0 {
        score -= 40.0; // perfect fill
    } else if post < 10 {
        score += 30.0; // dead space below min item size
    } else if post <= 20 {
        score += 5.0;
    }

    // Lookahead: does the next item fit the post residual exactly or well?
    if next_item_size > 0 {
        if next_item_size <= post {
            let next_fit_gap = post - next_item_size;
            if next_fit_gap == 0 {
                score -= 35.0; // chains a perfect fill
            } else if next_fit_gap % 10 == 0 {
                score -= 10.0;
            } else if next_fit_gap < 10 {
                score += 8.0;
            }
        } else {
            // next item cannot use this bin's leftover: leftover likely wasted
            score += 6.0;
        }
    } else {
        // last item: strongly prefer zero residual
        score += post as f64 * 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless residual is badly fragmented.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // nothing good exists — penalize the fresh bin so it wins only rarely
    // (e.g. when item is large and would leave harmonic space anyway).
    if bin_residual == bin_capacity {
        score += 55.0;
        // large items in a fresh bin leave harmonic room for medium items
        if item_size % 10 == 0 {
            score -= 20.0;
        }
        // early in the stream, having few bins, a fresh bin is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer tighter bins overall when many bins are open
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Coupling with mean residual: if this bin is tighter than average, reward
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

