pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_gap = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < min_gap {
        score += 120.0 + (min_gap - post_residual) as f64 * 15.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_frac;

    // Open-bin pressure: discourage scattering across many bins early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 + 1.4 * progress);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a bin unless current item leaves
    // a large residual (i.e., item is small) or no real alternative exists.
    if bin_residual == bin_capacity {
        score += 30.0 + 55.0 * (1.0 - fill_frac);
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    // Lookahead: avoid blocking the next item in a tight gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Mild preference toward bins with larger residuals (use fullest bins first).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    score
}

