        }
    }

    // Prefer bins tighter than the mean residual
    score += (mean_residual - bin_residual as f64) * 3.0;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening new bins when open bins fit well
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 5.0;
        // allow new bin if item is large relative to mean residual
        score -= (item_size as f64 - mean_residual).max(0.0) * 1.5;
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 80.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let mut score = post_residual as f64 ;
    let class_width : u32 = 10 ;
    if post_residual == 0 { score -= 1000.0 ; }
    else if post_residual < class_width { score -= 32.0 ; }
    if post_residual >= 11 && post_residual <= 19 { score += 12.0 ; }
    if next_item_size > 0 {
        if post_residual == next_item_size { score -= 45.0 ; }
        else if post_residual >= next_item_size && post_residual - next_item_size < class_width { score -= 18.0 ; }
        else if post_residual >= next_item_size { score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64) ; }
        else if post_residual >= 11 { score += 8.0 ; }
        else if bin_residual >= next_item_size { score += 30.0 ; }
    }
    // lookahead two-step: reward residuals that fit next item plus a small follow-up
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size ;
        if after <= 3 { score -= 12.0 ; }
        if after >= 20 && after <= 30 { score -= 6.0 ; }
        // chain potential: residual can host the next item twice
        if after >= next_item_size { score -= 10.0 ; }
        if after > 0 && after % 10 == 0 { score -= 4.0 ; }
    }
    // near-perfect fit after placing next item
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 { score -= 5.0 ; }
    // penalize mid-range dead space that fits nothing typical
    if post_residual >= 31 && post_residual <= 45 && next_item_size > post_residual { score += 6.0 ; }
    // residual just below next item: dead space that narrowly misses
    if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 8 {
        let gap = (next_item_size - post_residual) as f64 ;
        score += 4.0 + 0.8 * (8.0 - gap) ;
    }
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2 ;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0 ;
