        else {
            score += 45.0 ;
            if next_item_size > 60 && post_residual > 25 { score -= 30.0 ; }
            if open_bins_count > 40 && next_item_size >= 50 { score -= 8.0 ; }
        }
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        score += 30.0 * progress ;
    } else {
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        score -= 10.0 * progress ;
    }
