        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap ;
            let dist = (post_residual as f64 - band_center) . abs () ;
            score -= 6.0 * (1.0 - dist / (0.125 * cap)) . max (0.0) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight_fit * tight_fit;

    // Penalize dead space that no plausible future item can use.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress); // small holes are costly early
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more fragmentation: mild reward scaled by fill
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate handling: only attractive when no good fit exists
    // or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // base cost of opening a new bin, discounted late in the stream or for big items
        score += 22.0 * (1.0 - desperation) * (1.0 - 0.5 * item_frac) - 8.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Slight bonus for filling bins as the stream nears its end.
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

