    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = rn * (1.0 - 0.6 * progress) - 1.4 * rn * rn + 0.8 * rn * rn * rn * (1.0 + progress);

    // Reward tight fits (small post_residual), smoothly scaled by progress
    let tightness = -3.0 * (1.0 - rn) * (1.0 - rn) * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins
    let dead = 0.5 * (r - mean_residual) / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    let last_chance = if fitting_bins_count == 1 { -2.5 * (1.0 + progress) } else { 0.0 };

    // Lookahead: reward residual that can still fit the next item smoothly
    let lookahead = if next_item_size > 0 {
        let fits = (r >= next_item_size as f64) as f64;
        -1.0 * fits * (1.0 - (r - next_item_size as f64) / cap)
    } else {
        0.0
    };

    // Mild penalty for proliferating bins late in the stream
    let spread = 0.05 * open_bins_count as f64 * (0.3 + progress) / (1.0 + rn);

    r * 0.01 + poly + tightness + dead + last_chance + lookahead + spread
}

