        score -= 3.0 ;
    }

    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2 ;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0 ;
        if big_item || bins_crowded {
            score -= 40.0 ;
        } else {
            score += 45.0 ;
            if next_item_size > 60 && post_residual > 25 { score -= 30.0 ; }
            if open_bins_count > 40 && next_item_size >= 50 { score -= 8.0 ; }
        }
        score += 30.0 * progress ;
    } else {
        score -= 10.0 * progress ;
    }

    score += (mean_residual - post_residual as f64) * 0.05 ;

    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap ;
        score += waste * 14.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose post-residual falls into
    // "usable" residue classes (multiples of common small item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // reward post-residuals divisible by likely future item sizes (harmonic classes)
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                harmony += 4.0;
            }
        }
        score -= harmony;
    } else {
        // perfect fit: strongly reward
        score -= 30.0;
    }

    // Dead space penalty: small awkward residuals that no item (>=10) can use
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Penalize wasting a nearly-full bin's identity: if post_residual is large
    // but the bin was tight before, mild penalty for over-fragmenting.
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score += tightness * 5.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish score, but prefer new bin when
    // the item fits poorly everywhere and next item is large.
    if bin_residual == bin_capacity {
        // fresh bin: score = its residual minus lookahead bonus
        score = post_residual as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0; // next item can slot into this fresh bin too
        }
        // discourage opening new bins when many good fits exist
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        // early stream: opening bins cheap is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 3.0;
    } else {
        // lookahead coupling: reward leaving room for the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 6.0;
                // harmonic bonus if post_residual exactly matches next item class
                if post_residual == next_item_size {
                    score -= 10.0;
                }
            } else {
                score += (next_item_size - post_residual) as f64 * 0.15;
            }
        }
    }

    // Mean residual coupling: prefer bins close to mean residual (balanced packing)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.2;

    // Many open bins: encourage closing bins out (prefer fullest bins)
    score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for any future item (min size 1..100,
    // but treat gaps < 10 as effectively unusable dead space).
    if post_residual < 10 {
        score += 50.0;
    }

    // Penalize gaps that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits: small relative post-residual gets a discount.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 8.0;

    // Last-chance bonus: only one bin fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer filling existing.
    score += (open_bins_count as f64) * 0.15 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference toward bins with below-mean residual (fill the emptier ones first)
    // to consolidate space; bins with large residuals are kept for larger future items.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: empty bin starts with a moderate penalty so that
    // it is only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Early stream: be more willing to open bins (keep options open);
    // late stream: strongly prefer packing into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 6.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact 2-chain match is best; otherwise proportional to leftover after next item.
            let after_next = post_residual - next_item_size;
            score -= 60.0 + 0.5 * after_next as f64;
            if after_next == 0 {
                score -= 200.0; // exact 2-item chain closure
            }
        } else {
            // Next item won't fit here: penalize small dead space (waste), but tolerate large residuals.
            score += 20.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when good fitting alternatives exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 120.0 + 10.0 * fitting_bins_count as f64;
        }
        // A new bin is attractive only if the item is large relative to capacity.
        score -= 1.2 * item_size as f64;
    }

    // Prefer packing into fewer bins when many are open.
    score += 0.3 * open_bins_count as f64;

    // Slight early-stream bias toward tight fills (build good structure early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

