        let fit_quality = (next_item_size as f64) / (pr + 1.0);
        score -= 12.0 * fit_quality * (1.0 + progress);
    } else if next_item_size > 0 {
        // smooth penalty when next item cannot use the leftover space
        let gap = (next_item_size as f64 - pr) / cap;
        score += 8.0 * gap * gap * cap;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so mid/late stream
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mild preference toward bins with residuals near the mean (smooth diversification)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    // Prefer tighter fits overall
    score -= 5.0 * (item_size as f64) / (bin_residual as f64 + 1.0);

