}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 32.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < class_width {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else if post_residual >= 11 {
            score += 10.0;
        } else if bin_residual >= next_item_size {
            score += 30.0;
        }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after <= 3 {
                score -= 14.0;
            } else if after >= 20 && after <= 30 {
                score -= 6.0;
            } else if after >= 11 && after < next_item_size {
                score += 4.0;
            }
            if after >= next_item_size {
                score -= 12.0;
            }
            if after > 0 && after % 10 == 0 {
                score -= 4.0;
            }
            if after >= 2 * next_item_size {
                score -= 10.0;
            }
        }
        if post_residual < next_item_size && next_item_size - post_residual <= 8 {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.8 * (8.0 - gap);
        }
        if post_residual >= 2 * next_item_size {
            score -= 6.0;
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 95.0;
    }

    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        if big_item || bins_crowded {
            score -= 40.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    if bin_residual != bin_capacity {
        score -= (item_size as f64 / cap) * 20.0;
    }

    score += (mean_residual - post_residual as f64) * 0.05;

    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        if post_residual < bin_capacity / 4 {
            let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
            score += waste * 14.0;
        }
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        // refined dead-space shaping (borrowed from best heuristic)
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // penalize residuals just below next item size that waste space
        if next_item_size > 0 && post_residual < next_item_size && dead_ratio > 0.15 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
        }
        // tighten near-perfect fits: residual within 2 of next item after placement
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
    }

    if post_residual >= 35 && post_residual <= 55 {
        score -= 7.0;
    } else if post_residual >= 56 && post_residual <= 70 && next_item_size > 0 && next_item_size <= 55 {
        score -= 3.0;
    }

    if fitting_bins_count > 3 && post_residual < class_width {
        score -= 5.0;
    }

    // Perfect fit with current item.
    if bin_residual == item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Residual a multiple of likely future item.
    if post_residual > 0 && next_item_size > 1 && post_residual % next_item_size == 0 {
        score -= 6.0;
    }

    // Avoid residuals just below common small item sizes.
    if post_residual >= 11 && post_residual <= 24 && next_item_size > post_residual {
        score += 5.0;
    }

    // exact-fit chain anticipation
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after == next_item_size {
            score -= 8.0;
        }
    }

    // scarcity-aware urgency
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 2.0 * (1.0 - (fitting_bins_count as f64) / 2.0);
        }
    }

    // dead-zone band penalty when many bins open
    if post_residual >= 25 && post_residual <= 34 && open_bins_count > 20 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does it fall into?
    // Classes: [0..10) tiny, [10..25) small, [25..50) medium, [50..100) large
    let pr = post_residual;
    let class_weight: f64 = if pr == 0 {
        -6.0 // perfect fill: strongly reward
    } else if pr < bin_capacity / 10 {
        -2.0 // nearly full
    } else if pr < bin_capacity / 4 {
        -0.5
    } else if pr < bin_capacity / 2 {
        1.5 // medium dead space
    } else {
        3.0 // large leftover: wasteful
    };
    score += class_weight;

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // small item sizes (10, 20, 25, 50) are reusable; reward them.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 1.0;
    }

    // Lookahead coupling: if the next item fits the post_residual exactly or well,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size <= pr {
        let fit_ratio = next_item_size as f64 / pr as f64;
        if fit_ratio > 0.8 {
            score -= 3.0;
        } else if fit_ratio > 0.5 {
            score -= 1.5;
        }
        // exact modulo match: next item divides residual cleanly
        if pr % next_item_size == 0 {
            score -= 1.0;
        }
    } else if next_item_size > pr && pr > 0 {
        // next item won't fit here: residual likely dead space
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: penalize mildly so we prefer filling existing bins,
    // unless the item is huge relative to mean residual (poor fits everywhere).
    if bin_residual == bin_capacity {
        score += 5.0;
        if mean_residual > 0.0 && (item_size as f64) > mean_residual * 1.5 {
            score -= 6.0; // poor fit everywhere -> fresh bin is better
        }
    }

    // Mild penalty for spreading across too many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        score += 0.5;
    }

    // Tie-break with mean residual alignment: prefer bins whose residual is near the mean.
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 12) are unusable dead space -> heavy penalty.
    if post_residual < 12 {
        score += 40.0;
    } else if post_residual < 25 {
        // "awkward gap" zone: quadratic penalty scaled by gap smallness
        score += 0.08 * (25.0 - post_residual as f64) * (25.0 - post_residual as f64);
    }

    // Reward near-perfect fits (tight packing is the goal).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement chains perfectly -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 12 {
            score -= 20.0; // next item leaves no dead space either
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 10.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance pressure: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins; the more bins
    // already open, the more we push toward filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Mean-residual coupling: if this bin's residual is far below average,
    // it is an outlier that should be drained first.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= 0.25 * residual_gap;
    } else {
        score += 0.15 * (-residual_gap);
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item would leave a large, flexible residual AND open bins are scarce
    // or this bin would otherwise be a poor fit. Otherwise penalize it.
    if bin_residual == bin_capacity {
        let flexible = post_residual as f64 >= 40.0;
        if flexible && open_bins_count == 0 {
            score -= 25.0;
        } else if flexible && fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 35.0 + open_bins_count as f64 * 2.0;
        }
    }

    score
}

