        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        if post_residual < bin_capacity / 4 {
            let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
            score += waste * 14.0;
        }
        // Sharpen the near-dead band: residuals that are too small for the next
        // item but close to it are the main source of wasted space.
        if next_item_size > 0 && post_residual < next_item_size && dead_ratio > 0.15 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
        }
        // Reward residuals in the 0.20..0.45 band near the band center — these
        // absorb a wide range of mid-size items later.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Scarce fitting bins + next item still fits: keep this bin alive.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
    }

    if post_residual >= 35 && post_residual <= 55 {
        score -= 7.0;
    } else if post_residual >= 56 && post_residual <= 70 && next_item_size > 0 && next_item_size <= 55 {
        score -= 3.0;
    }

    if fitting_bins_count > 3 && post_residual < class_width {
        score -= 5.0;
    }

    // Perfect fit with current item.
    if bin_residual == item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Residual a multiple of likely future item.
    if post_residual > 0 && next_item_size > 1 && post_residual % next_item_size == 0 {
        score -= 6.0;
    }

    // Avoid residuals just below common small item sizes.
    if post_residual >= 11 && post_residual <= 24 && next_item_size > post_residual {
        score += 5.0;
    }

    // Exact-fit chain anticipation: residual = next + next keeps bins tight.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after == next_item_size {
            score -= 8.0;
        }
    }

    // Scarcity-aware urgency: prefer the bin leaving usable residual for next item.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 2.0 * (1.0 - (fitting_bins_count as f64) / 2.0);
        }
    }

    // Penalize residuals in the 25..=34 dead zone when many bins are open.
    if post_residual >= 25 && post_residual <= 34 && open_bins_count > 20 {
        score += 3.0;
    }

    // Tighten near-perfect fits: residual within 2 of next item after placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fits the post residual (perfect 2-step chain)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        // Perfect chain: huge bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space that next item cannot use
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize post residual
        score += 0.0;
    }

    // Tight fits are good: small post residual relative to mean residual is attractive
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly-empty bin's flexibility (large residual consumed by small item)
    let waste = if item_size < bin_residual / 2 { (bin_residual / 2 - item_size) as f64 } else { 0.0 };
    score += 0.2 * waste;

    // Slight penalty for using a fresh bin when other bins could absorb the item
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0;
    }

    // Late in the stream, consolidate: prefer bins with low residual
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

