    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mild penalty for very empty open bins being consumed by small items.
    if item_size < 30 && bin_residual > 80 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

