    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: classify dead space into residue classes mod 10.
    let cls = (post_residual % 10) as f64;
    // Residuals that are "harmonically useful" (multiples of 5/10) are less penalized.
    let class_penalty = match post_residual % 10 {
        0 => -6.0,
        5 => -3.0,
        1 | 2 | 3 | 4 => 2.0 + cls * 0.3,
        _ => 1.0 + (9.0 - cls) * 0.2,
    };
    score += class_penalty;

    // Integer-division threshold: small post_residual (<= 10) is near-perfect packing.
    if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * frac;
            // harmonic class match between next item and post residual
            if next_item_size % 10 == post_residual % 10 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize wasting a good residual
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last chance: this is the only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if no open bin is decent, or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 * 0.5 + mean_residual * 0.1;
        score += 55.0 + progress * 10.0 - pressure * 0.3;
        // opening a new bin is fine if item is large relative to capacity
        score -= item_size as f64 * 0.1;
    }

    // Prefer tighter fits overall: reward small post_residual relative to capacity fraction.
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 8.0;

    // Mild preference for bins with below-mean residual (consolidate emptier bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

