    }

    // Lookahead coupling: reward if the next item exactly fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 22.0 / (1.0 + slack);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use leftover: mild penalty scaled by leftover size.
        score += 0.08 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // bins fit poorly and many bins are already open (fragmentation risk).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_alternatives = (fitting_bins_count as f64) * fit_ratio;
        score += 40.0 - 25.0 * poor_alternatives.min(1.0);
