pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction bands.
    let post = post_residual as f64;
    let frac = post / cap;

    // Reward small post_residual (tight fit), non-linearly.
    score -= (1.0 - frac) * (1.0 - frac) * 30.0;

    // Dead-space penalty: residuals in awkward harmonic classes are hard to fill.
    // Class 1: (0,10)  -> nearly dead, small penalty
    // Class 2: [10,30) -> moderate, often fillable by small items
    // Class 3: [30,50) -> awkward mid-range, strongest penalty
    // Class 4: [50,100] -> large residual, still useful
    let post_u = post_residual;
    if post_u > 0 && post_u < 10 {
        score += 5.0;
    } else if post_u >= 30 && post_u < 50 {
        score += 25.0;
    } else if post_u >= 10 && post_u < 30 {
        score += 8.0;
    }

    // Perfect-fit reward: post_residual exactly divisible into common item classes.
    if post_u == 0 {
        score -= 60.0;
    } else if post_u % 10 == 0 {
        score -= 12.0; // divisible by common item sizes
    } else if post_u % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_u {
            score -= 50.0;
        } else if next_item_size < post_u {
            let next_fit_waste = post_u - next_item_size;
            // Reward proportional to how well next item also fits
            score -= (next_fit_waste as f64).min(20.0) * 0.8;
            // Harmonic check: post_residual - next_item_size divisible by 10
            if next_fit_waste % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; penalize slightly less if post_residual
            // is in a "collectable" class (small sums of future items).
            if post_u < 20 {
                score -= 3.0;
            } else {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Give it a baseline penalty that shrinks when the
    // item is large relative to capacity (fewer future options).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score = 55.0 - item_frac * 25.0;
        // If open bins are nearly full on average, new bin is more attractive.
        score -= mean_residual / cap * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 15.0;
    }

    // Mild pressure to prefer bins below mean residual (balance load slightly).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width : u32 = 10;
    let mut score = post_residual as f64;
    if post_residual == 0 { score -= 1000.0; }
    else if post_residual < class_width { score -= 30.0; }
    else if post_residual >= 11 && post_residual <= 19 { score += 12.0; }

    if next_item_size > 0 {
        if post_residual == next_item_size { score -= 40.0; }
        else if post_residual >= next_item_size && post_residual - next_item_size < class_width { score -= 18.0; }
        else if post_residual < next_item_size && post_residual >= 11 { score += 8.0; }
        // lookahead two-step: reward residuals that fit next item plus a small follow-up
        let after = post_residual - next_item_size.min(post_residual);
        if post_residual >= next_item_size {
            if after <= 3 { score -= 10.0; }
            if after >= 20 && after <= 30 { score -= 6.0; }
            // chain potential: residual can host the next item twice
            if post_residual >= 2 * next_item_size { score -= 8.0; }
            // reward residuals that remain reusable after placing next item
            if after >= 5 && after <= 15 { score -= 3.0; }
