        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // slight preference for tighter fits when many bins compete
    if fitting_bins_count > 3 && post_residual < class_width { score -= 4.0; }

    // gen-40 additions: mean-residual alignment and small-dead-space penalty
    score += (mean_residual - post_residual as f64) * 0.05;
