        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 15.0 { score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity); }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals too small to hold
    // any plausible future item (min size 1, but practically small gaps
    // below a usable threshold are waste). Scale penalty by gap smallness.
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits: perfect or near-perfect fills get big bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
