        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: penalize placements into already-crowded bin sets
    // less than placements that would leave many bins open; encourage
    // consolidation by rewarding placement into existing bins.
    if bin_residual < bin_capacity {
        score -= 5.0 + (open_bins_count as f64) * 0.5;
    }

    // Penalize creating residuals that no next item could use at all
    // (wasted sliver) beyond the general dead-space penalty.
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Slight progression-aware scaling: early in the stream, be more
    // conservative (keep bins flexible); later, favor tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

