        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly matches the post residual,
    // this is a chained perfect fit — strongly favor.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size <= post_residual {
