    // but especially below typical small items) relative to mean residual.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Compare against mean residual: placing into a bin with residual far
    // above the mean wastes space; prefer bins with low residual that still fit.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.2 * mean_gap;

    // Last-chance bin: if this is the only bin that can fit, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless the fit into existing bins is terrible (large post_residual).
    if bin_residual == bin_capacity {
        let new_bin_score = 100.0
            + post_residual as f64
            + (open_bins_count as f64) * 5.0;
        // Opening a new bin keeps full residual 100; make it competitive only
        // when no good existing fit exists (handled by comparisons naturally).
        score = new_bin_score;
        if open_bins_count == 0 {
            score -= 500.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 100.0; // fresh bin can host next item too
        }
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

