        if next_item_size > 0 && post_residual < next_item_size && scarcity < 0.5 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 { score += 3.0 * (20.0 - gap) / 20.0; }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 5 && after <= 15 { score -= 3.0 * (1.0 - scarcity); }
            if after >= next_item_size { score -= 2.5 * (1.0 - scarcity); }
        }
        let remaining_frac = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio < 0.08 && dead_ratio > 0.0 {
            score += 6.0 * (1.0 - remaining_frac) * (0.08 - dead_ratio) * 100.0;
        }
        // gen-41: late-stream exact-fill bonus — reward residuals that the next item
        // fills perfectly when the stream is nearly done (no future to plan for)
        if next_item_size > 0 && post_residual == next_item_size && remaining_frac < 0.5 {
            score -= 8.0 * (0.5 - remaining_frac);
        }
    }
    if post_residual >= 35 && post_residual <= 55 { score -= 7.0; }
    else if post_residual >= 56 && post_residual <= 70 && next_item_size <= 55 && next_item_size > 0 { score -= 3.0; }
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        if chain >= next_item_size { score -= 10.0; }
        if chain > 0 && chain % 10 == 0 { score -= 4.0; }
        if chain >= 2 * next_item_size { score -= 6.0; }
    }
    if post_residual > 0 && post_residual % 5 == 0 { score -= 1.5; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no future small item (>= 1) can use well:
    // residual below the minimum item size is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // Neutral baseline for a new bin; penalize when many bins already open
        // (consolidation preferred) or when progress is late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (1.0 - progress) - (open_bins_count as f64).min(20.0);
    }

    // Global residual pressure: if mean residual is high, prefer bins that reduce it
    // relative to the average.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Prefer fuller bins (smaller residual) generally.
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Early stream: mild exploration bonus for spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
