    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        // gen-41: tighten new-bin decision — open fresh bin only when open bins
        // are effectively dead for the next item, or the item itself is huge
        let next_needs_fresh = next_item_size > 0
            && fitting_bins_count > 0
            && open_bins_count > 0
            && (mean_residual < next_item_size as f64 * 0.95);
        if big_item || bins_crowded || next_needs_fresh { score -= 40.0; }
