        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 5 && after <= 15 { score -= 3.0 * (1.0 - scarcity); }
            // gen-41: deeper lookahead — two-step chain, reward if the after-residual
            // can still host a small follow-up (assume ~mean residual size)
            let follow = mean_residual.min(cap * 0.5);
            if after as f64 >= follow && follow > 0.0 {
                score -= 4.0 * (after as f64 - follow) / cap.max(1.0) * 10.0;
            }
        }
        // gen-41: dead-space penalty scaled by how much stream remains —
        // late-stream dead space is nearly permanent waste
        let stream_left = 1.0 - (step_index as f64 / total_items.max(1) as f64);
