        if chain >= next_item_size { score -= 10.0; }
        if chain > 0 && chain % 10 == 0 { score -= 4.0; }
        if chain >= 2 * next_item_size { score -= 6.0; }
    }
    // gen-34: mild anti-fragmentation — prefer bins whose leftover stays divisible-friendly
    if post_residual > 0 && post_residual % 5 == 0 { score -= 1.5; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr / cap;

    // smooth non-linear coupling of post-residual with stream progress
    score += (pr / cap).powi(2) * (0.5 + progress);
    score += (pr / cap).powi(3) * progress * progress;

    // reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * (1.0 + progress);

    // last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 2.0 * tightness;
    }

    // penalize leaving space that the lookahead item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 0.3 * (pr - nxt) / cap;
        }
    }

    // mild penalty for spreading across many bins vs mean residual
    score += (open_bins_count as f64).ln() * 0.05;
    score += (mean_residual / cap - pr / cap).abs() * 0.2;

    // new-bin candidate: keep it moderately attractive only when residuals are bad
    if bin_residual == bin_capacity {
        score -= 1.5 * (1.0 - tightness) * (1.0 - progress);
    }

    score
}

