pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small slivers" are near-useless dead space -> penalize.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = post / cap;

    // Dead-space penalty: residuals that no typical item (1..=100) can pair
    // with well. Classify by modulo classes of 10 and 5.
    let r = post_residual;
    let class10 = r % 10;           // harmonic class mod 10
    let class5 = r % 5;

    // Slivers (< 10) are dead space unless exact-zero fill.
    if r > 0 && r < 10 {
        score += (10 - r) as f64 * 4.0; // tighter slivers are worse
    }

    // Odd harmonic classes (residual not divisible by 5) are harder to fill
    // exactly -> mild penalty proportional to how odd they are.
    if class5 != 0 {
        score += 2.0 + (class5 as f64) * 0.3;
    }
    // Residuals divisible by 10 are "harmonic" with common item sizes.
    if class10 == 0 && r > 0 {
        score -= 3.0;
    }

    // Perfect fit: zero residual is ideal.
    if r == 0 {
        score -= 25.0;
    }

    // Exact-match bonus: residual equals next item size -> this bin
    // perfectly serves the lookahead item.
    if next_item_size > 0 && r == next_item_size {
        score -= 20.0;
    }
    // Lookahead can also fill this bin exactly after current placement:
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit into the post residual, dead space risk rises.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += post_residual as f64 * 0.5;
    }

    // Tight fit reward: placing item leaves little but usable space.
    let tightness = 1.0 - frac;
    score -= tightness * 5.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual < 5 {
            score -= 8.0; // still worth it, near-perfect squeeze
        }
    }

    // New-bin candidate (bin_residual == bin_capacity): prefer it only when
    // the item is large and existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // Opening a new bin costs ~1 bin; only attractive if mean residual
        // is small (existing bins nearly full) or item is huge.
        let item_frac = item_size as f64 / cap;
        let open_bonus = if item_frac > 0.6 { 8.0 } else { 0.0 };
        score += 30.0 - open_bonus - fragmentation * 40.0 - progress * 5.0;
        // Harmonic: a fresh bin has perfectly harmonic residual = capacity.
        if item_size % 10 == 0 {
            score -= 6.0;
        }
    }

    // Prefer bins whose residual is closest above the item (best-fit core),
    // scaled by number of competing bins.
    let waste = (bin_residual - item_size) as f64;
    score += waste * 0.2 + open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Fine-grained residual class bands.
    if post_residual == 0 {
