        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else if bin_residual >= next_item_size {
            score += 30.0;
        }
        // Two-step lookahead: residual can host next item (and then some).
        if post_residual >= 2 * next_item_size { score -= 8.0; }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after <= 3 { score -= 12.0; }
            else if after >= 20 && after <= 30 { score -= 6.0; }
            else if after >= 5 && after <= 15 { score -= 3.0; }
        }
        // Destroying the only fit for next item.
        if post_residual < next_item_size && next_item_size - post_residual <= 8 {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.8 * (8.0 - gap);
        }
    }

    // Last-chance bin: strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let next_needs_fresh = next_item_size > 0
            && fitting_bins_count > 0
            && open_bins_count > 0
            && mean_residual < next_item_size as f64 * 0.9;
        if big_item || bins_crowded || next_needs_fresh {
            score -= 40.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 { score -= 30.0; }
            if open_bins_count > 40 && next_item_size >= 50 { score -= 8.0; }
        }
