    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly,
    // penalize if next item cannot fit the leftover gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            if post_residual == next_item_size {
                score -= 80.0;
            } else {
                score -= 15.0;
            }
        } else if post_residual > 0 {
            score += 20.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer packing into existing
    // bins; when few bins are open, opening a new one is cheaper.
    let pressure = open_bins_count as f64 * 2.5;
    score += pressure;

    // New-bin candidate handling: empty bin has high residual; make it
    // attractive only when current bin would leave a bad gap or when
    // this is the last fitting bin (avoid forcing a poor fit).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 5.0; // mild default preference for existing bins
        if fitting_bins_count == 1 && !next_item_fits_here(post_residual, next_item_size) {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it to avoid a new bin.
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (filling the emptier side of the fleet less aggressively).
    score += (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.3;

    // Stream progression: later in the stream, be more conservative,
    // tightening tolerance for wasted space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

