pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let t = step_index as f64 / (total_items.max(1) as f64);

    // Waste fraction of the placement
    let waste = post_residual as f64 / bin_capacity as f64;

    if is_new_bin {
        // Penalize opening a new bin, scaled by how well the item fits elsewhere.
        let mut penalty = 25.0 + 0.35 * open_bins_count as f64;
        // If many bins fit the item, opening a new bin is bad.
        penalty += 6.0 * (fitting_bins_count as f64).min(10.0);
        // If this is the only fitting bin, opening may be justified -> soften penalty.
        if fitting_bins_count == 0 {
            penalty -= 15.0;
        }
        // Tight fit in an existing bin would leave tiny post-residual; prefer it.
        // New bin leaves huge residual; penalize more late in stream when consolidation matters.
        penalty *= 0.5 + 0.5 * t;
        // Lookahead: if next item would fit in the fresh residual, opening is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            penalty -= 12.0;
        }
        score += penalty;
    } else {
        // Reward tight fits: low post_residual is already rewarded by base term.
        // Extra reward for near-perfect fill.
        if post_residual <= 5 {
            score -= 20.0;
        } else if post_residual <= 15 {
            score -= 8.0;
        }

        // Penalize creating dead space that no plausible item can use.
        if post_residual > 0 && post_residual < 10 {
            score += 10.0; // tiny sliver is dead space
        }

        // Last-chance bonus: if this is the only fitting bin, strongly prefer it
        // over opening a new bin (unless fit is terrible).
        if fitting_bins_count == 1 {
            score -= 18.0 + 10.0 * (1.0 - waste);
        }

        // Prefer bins whose residual is closest to the item (best-fit flavor)
        let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 5.0 * fit_gap;

        // Lookahead coupling: if next item fits exactly in the post residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 25.0;
            } else if next_item_size <= post_residual {
                score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
            } else {
                // next item won't fit here; slight penalty if we leave large residue
                score += 3.0 * waste;
            }
        }

        // Balance pressure: prefer bins with below-mean residual early (keep big holes open),
        // but consolidate onto large-residual bins late in the stream.
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += dev * (10.0 * (1.0 - t) - 6.0 * t);

        // Mild reward for using existing bins as the fleet grows.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

