    let class_width : u32 = 10;
    let mut score = post_residual as f64;
    if post_residual == 0 { score -= 1000.0; }
    else if post_residual < class_width { score -= 32.0; }
    else if post_residual <= bin_capacity / 5 { score += 25.0; }
    else if post_residual <= bin_capacity / 2 { score += 8.0; }
    if next_item_size > 0 {
        if post_residual == next_item_size { score -= 45.0; }
        else if post_residual >= next_item_size && post_residual - next_item_size < class_width { score -= 18.0; }
        else if post_residual >= next_item_size { score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64); }
        else if post_residual >= 11 { score += 10.0; }
        else if bin_residual >= next_item_size { score += 30.0; }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after <= 3 { score -= 12.0; }
            else if after >= 20 && after <= 30 { score -= 6.0; }
            else if after < next_item_size && after >= 11 { score += 4.0; }
        }
    }
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        // gen-48: richer fresh-bin gate — combine mean-residual scarcity with
        // total available fit capacity lookahead (borrowed idea from best)
        let total_fit_capacity : f64 = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                 && mean_residual < next_item_size as f64 * 1.10
                 && (fitting_bins_count as f64) < 4.0)
             || (total_fit_capacity < next_item_size as f64 * 2.0
                 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh { score -= 42.0; }
        else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 { score -= 30.0; }
            if open_bins_count > 40 && next_item_size >= 50 { score -= 8.0; }
            let remaining_frac = 1.0 - (step_index as f64 / total_items.max(1) as f64);
            if remaining_frac < 0.15 && fitting_bins_count <= 2 { score -= 12.0 * (0.15 - remaining_frac) / 0.15; }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }
    score += (mean_residual - post_residual as f64) * 0.05;
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 8 {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.8 * (8.0 - gap);
        }
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        if dead_ratio > 0.05 && dead_ratio < 0.12 { score += 10.0 * (0.12 - dead_ratio) * 100.0; }
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        if next_item_size > 0 && post_residual < next_item_size && dead_ratio > 0.15 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 { score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity); }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 { score -= 5.0; }
        if next_item_size > 0 && post_residual >= 2 * next_item_size { score -= 8.0; }
        if next_item_size > 0 && post_residual < next_item_size && scarcity < 0.5 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 { score += 3.0 * (20.0 - gap) / 20.0; }
        }
        // gen-48: reward residuals that remain reusable after placing next item,
        // widened mid-band and scaled by scarcity
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 3 && after <= 15 { score -= 3.5 * (1.0 - scarcity); }
            else if after > 15 && after <= 30 && scarcity < 0.7 { score -= 2.0 * (1.0 - scarcity); }
        }
        // gen-48: penalize residuals that strand a sliver below the next item
        if next_item_size > 0 && post_residual > next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after < 5 { score += 2.0 + 0.5 * (5 - after) as f64; }
        }
        // gen-48: divisible-friendly residual near next item reduces waste
        if next_item_size > 0 && post_residual < next_item_size && post_residual % 5 == 0 && post_residual >= 5 {
            score += 2.0 * (1.0 - scarcity);
        }
        // gen-48: dead-space penalty scaled by remaining stream length
        let stream_left2 = 1.0 - (step_index as f64 / total_items.max(1) as f64);
        if dead_ratio > 0.25 {
            score += dead_ratio * 6.0 * stream_left2;
        }
        // gen-48: dead-heavy bin with no alternative fit — discourage filling it now
        if dead_ratio > 0.50 && fitting_bins_count <= 1 {
            score += 4.0 * (dead_ratio - 0.50) * 10.0 * (1.0 - scarcity);
        }
        // gen-48: exact-fill lookahead — residual exactly equals next item
        // guarantees a perfectly packed bin afterwards
        if next_item_size > 0 && post_residual == next_item_size && stream_left2 < 0.5 {
            score -= 4.0;
        }
        // gen-48: half-capacity sweet spot — residual near half capacity pairs
        // well with mid-sized items in long streams
        if next_item_size > 0 && (post_residual as f64 - 0.5 * cap).abs() < 3.0
            && next_item_size >= 30 && next_item_size <= 50 {
            score -= 2.5;
        }
        // gen-48: near-perfect second placement — residual leaves almost nothing
        // after hosting the next item, in the 0.12–0.20 dead band
        if dead_ratio > 0.12 && dead_ratio < 0.20 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after < cap * 0.06 { score -= 3.0 * (1.0 - after / (cap * 0.06)); }
        }
    }
    if post_residual >= 35 && post_residual <= 55 { score -= 7.0; }
    else if post_residual >= 56 && post_residual <= 70 && next_item_size <= 55 && next_item_size > 0 { score -= 3.0; }
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        if chain >= next_item_size { score -= 10.0; }
        if chain > 0 && chain % 10 == 0 { score -= 4.0; }
        if chain >= 2 * next_item_size { score -= 6.0; }
    }
    // gen-48: mild anti-fragmentation — divisible-friendly leftovers
    if post_residual > 0 && post_residual % 5 == 0 { score -= 1.5; }
    // gen-48: late-stream consolidation — as the stream ends, favor tight fits
    // in existing bins to avoid spawning near-empty bins
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - (post_residual as f64 / cap));
    }
    // gen-48: very-late exact fit bonus
    if stream_left < 0.05 && post_residual >= next_item_size && next_item_size > 0 { score -= 2.0; }
    // gen-48: when few bins can host the next item, boost tight-fit bins so the
    // scarce capacity is consumed by the best available fit
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 3.0 * tightness;
    }
    score
}

