pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly concave via quadratic coupling with progress
    let mut score = pr * (1.0 + 0.35 * progress * (1.0 - norm_pr));

    // Penalize dead space that is too small to fit a typical future item
    let dead = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
    score += dead * (12.0 + 18.0 * progress) * (1.0 - norm_pr);

    // Reward leaving space for the lookahead item (smooth coupling)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-gap / cap).exp() * (1.0 + progress);
    }

    // Last-chance bonus: strongly prefer filling a nearly-unique fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate shaping: prefer new bins early, discourage late
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) * (1.0 - progress) - 6.0 * progress * progress;
        score += 0.5 * open_bins_count as f64;
    }

    // Coupling with mean residual: avoid bins far from the fleet mean late in stream
    score += 0.15 * progress * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Fine-grained residual bands.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 32.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    // Awkward dead-space band.
    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
    }

    // Lookahead coupling.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
            // Chain fit: residual can host next item again.
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 10.0;
            }
            if chain > 0 && chain % 10 == 0 {
                score -= 4.0;
            }
            if chain >= 2 * next_item_size {
                score -= 6.0;
            }
        } else if post_residual >= 11 {
            score += 10.0;
        } else if bin_residual >= next_item_size {
            score += 30.0;
        }
        // Near-miss gap penalty: next item barely doesn't fit.
        if post_residual < next_item_size && next_item_size - post_residual <= 8 {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.8 * (8.0 - gap);
        }
        // Two-item lookahead: residual fits next item twice.
        if post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity: f64 = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                && mean_residual < next_item_size as f64 * 1.15
                && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0
                    && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 42.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Fill-fraction coupling.
    if bin_residual != bin_capacity {
        score -= (item_size as f64 / cap) * 20.0;
    }

    // Mean-residual consolidation.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Dead-space scarcity-weighted adjustments.
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Sweet-spot band 30..60: residual large enough to be reusable.
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band valley around 0.325 capacity.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // After-fit micro-waste: penalize tiny leftovers after next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 3 && after <= 15 {
                score -= 3.5 * (1.0 - scarcity);
            } else if after > 15 && after <= 30 && scarcity < 0.7 {
                score -= 2.0 * (1.0 - scarcity);
            }
            if after > 0 && after < 5 {
                score += 2.0 + 0.5 * (5 - after) as f64;
            }
        }
    }

    // Waste-vs-quarter-capacity penalty.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    // Stream-end urgency: consolidate hard near the end.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - (post_residual as f64 / cap));
    }
    if stream_left < 0.05 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "usable" residue class (small, well-quantized leftovers) are favored.
    let post = post_residual;
    let class = post % 10; // residue class mod 10
    score -= (10 - class) as f64 * 0.35; // reward leftovers near a multiple of 10

    // Integer-division thresholds: leftover that still admits a mid-size item
    // is valuable; leftover below the minimum item size is dead space.
    let half = bin_capacity / 2;
    if post >= half {
        score -= 8.0; // room for another large item
    } else if post >= bin_capacity / 4 {
        score -= 3.0; // room for a medium item
    } else if post > 0 && post < 10 {
        score += 6.0; // nearly perfect fit is fine, tiny-but-nonzero is wasted
    } else if post == 0 {
        score -= 12.0; // perfect closure is best
    }

    // Lookahead coupling: reward leftover that exactly (or nearly) matches the
    // next item's harmonic class.
    if next_item_size > 0 && post >= next_item_size {
        let gap = post - next_item_size;
        if gap == 0 {
            score -= 10.0;
        } else if gap % 10 == 0 {
            score -= 5.0;
        } else {
            score -= (10 - (gap % 10)) as f64 * 0.4;
        }
    } else if next_item_size > 0 {
        // next item cannot use this leftover -> leftover likely dead space
        score += (next_item_size - post) as f64 * 0.15;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when no open bin
    // offers a decent fit; the base residual (full capacity) already makes it
    // score high, add a small progress-dependent tilt.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 14.0 + 4.0 * progress;
    }

    // Slight preference to fill bins that deviate from the mean residual
    // (consolidate emptiness into few bins).
    score -= (mean_residual - post as f64).abs() * 0.05;

    // Tightness reward: how fully the item fills the bin's current space.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 6.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
