        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 { score -= 5.0; }
        if next_item_size > 0 && post_residual >= 2 * next_item_size { score -= 8.0; }
        if next_item_size > 0 && post_residual < next_item_size && scarcity < 0.5 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 { score += 3.0 * (20.0 - gap) / 20.0; }
        }
        // gen-49: reward residuals that remain reusable after the next item,
        // scaled by scarcity of fitting options
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 3 && after <= 15 { score -= 3.5 * (1.0 - scarcity); }
            else if after > 15 && after <= 30 && scarcity < 0.7 { score -= 2.0 * (1.0 - scarcity); }
        }
        // gen-49: penalize residuals that strand a sliver below the next item
        if next_item_size > 0 && post_residual > next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after < 5 { score += 2.0 + 0.5 * (5 - after) as f64; }
        }
        // gen-49: divisible-friendly leftovers in scarce contexts
        if next_item_size > 0 && post_residual < next_item_size && post_residual % 5 == 0 && post_residual >= 5 {
            score += 2.0 * (1.0 - scarcity);
        }
        // gen-49: tight secondary fit in mid-dead band
        if dead_ratio > 0.12 && dead_ratio < 0.20 && next_item_size > 0 && post_residual >= next_item_size {
