        if chain >= 2 * next_item_size { score -= 6.0; }
    }
    // gen-51: mild anti-fragmentation — divisible-friendly leftovers
    if post_residual > 0 && post_residual % 5 == 0 { score -= 1.5; }
    // gen-51: late-stream consolidation — avoid spawning near-empty bins
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - (post_residual as f64 / cap));
    }
    // gen-51: final-stretch tight-fit bonus
    if stream_left < 0.05 && post_residual >= next_item_size && next_item_size > 0 {
        score -= 2.0;
    }
    // gen-51: when few bins can host the next item, boost tight fits
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 3.0 * tightness;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100, but
    // practically small) can use are pure waste. Penalize tiny unusable gaps super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // A gap is "dead" if it's smaller than a plausible small item (say < 15) and
        // doesn't match the lookahead item.
        let dead = gap < 15.0 && (next_item_size == 0 || (next_item_size as f64) > gap);
        if dead {
            score += 60.0 + (15.0 - gap) * 8.0;
        }
        // Perfect fit: extremely rewarded.
        if post_residual == 0 {
            score -= 200.0;
        }
        // Exact fit for the lookahead item: also excellent (pre-packing next item).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 120.0;
        }
        // Reward gaps that still fit the lookahead item (keeps chains going).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Tightness reward: fraction of the residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins) to keep bin count down.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + progress);
    // New-bin candidate: bin_residual == bin_capacity. Make it expensive unless the
    // current item is large relative to mean residual of open bins (poor fits everywhere).
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = mean_residual < item_size as f64 * 1.05;
        if fitting_bins_count == 0 || (poor_fit_everywhere && fitting_bins_count <= 1) {
            // Opening a new bin is justified: keep it cheap.
            score -= 30.0;
        } else {
            score += 90.0 + pressure * 3.0;
        }
    } else {
        // Existing bin: mild reward scaled by how many alternatives exist.
        if fitting_bins_count == 1 {
            // Last-chance bin before opening a new bin: strong reward.
            score -= 50.0;
        } else {
            score -= (pressure * 0.5).min(20.0);
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is near the mean
    // (keeps bin states homogeneous, easier future packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    score
}

