            else if after > 15 && after <= 30 && scarcity < 0.7 { score -= 2.0 * (1.0 - scarcity); }
        }
        // gen-53: penalize slivers stranded just below the next item size
        if next_item_size > 0 && post_residual > next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after < 5 { score += 2.0 + 0.5 * (5 - after) as f64; }
