            if after < cap * 0.06 { score -= 3.0 * (1.0 - after / (cap * 0.06)); }
        }
        // gen-53: nearly-dead bin with no alternatives — push toward opening fresh
        if dead_ratio > 0.50 && fitting_bins_count <= 1 {
            score += 4.0 * (dead_ratio - 0.50) * 10.0 * (1.0 - scarcity);
        }
        // gen-53: dead-space penalty scaled by remaining stream length
        let stream_left2 = 1.0 - (step_index as f64 / total_items.max(1) as f64);
        if dead_ratio > 0.25 {
            score += dead_ratio * 6.0 * stream_left2;
        }
        // gen-53: exact-fill lookahead in the late half of the stream
        if next_item_size > 0 && post_residual == next_item_size && stream_left2 < 0.5 {
            score -= 4.0;
        }
        // gen-53: half-capacity sweet spot for mid-sized next items
        if next_item_size > 0 && (post_residual as f64 - 0.5 * cap).abs() < 3.0
            && next_item_size >= 30 && next_item_size <= 50 {
            score -= 2.5;
        }
        // gen-53: divisible-friendly leftovers
        if next_item_size > 0 && post_residual < next_item_size && post_residual % 5 == 0 && post_residual >= 5 {
            score += 2.0 * (1.0 - scarcity);
        }
    }
    if post_residual >= 35 && post_residual <= 55 { score -= 7.0; }
    else if post_residual >= 56 && post_residual <= 70 && next_item_size <= 55 && next_item_size > 0 { score -= 3.0; }
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        if chain >= next_item_size { score -= 10.0; }
        if chain > 0 && chain % 10 == 0 { score -= 4.0; }
        if chain >= 2 * next_item_size { score -= 6.0; }
    }
    // gen-53: mild anti-fragmentation — multiples of 5 pair well downstream
    if post_residual > 0 && post_residual % 5 == 0 { score -= 1.5; }
    // gen-53: late-stream consolidation — avoid spawning near-empty bins at the end
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - (post_residual as f64 / cap));
    }
    if stream_left < 0.05 && post_residual >= next_item_size && next_item_size > 0 { score -= 2.0; }
    // gen-53: when few bins can host the next item, boost tight-fit bins
    if next_item_size > 0 && fitting_bins_count <= 2 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 3.0 * tightness;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (tight packing).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0 - (post_residual as f64) * 50.0;
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 10.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 300.0 - slack * 15.0;
            } else {
                // mild penalty for leaving a gap the next item cannot use well
                score += slack * 0.3;
            }
        } else {
            // next item cannot fit here at all: residual is dead space until later
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: strongly prefer filling existing bins completely.
        if bin_residual != bin_capacity {
            score -= 600.0;
        } else {
            score += 2000.0;
        }
    }

    // Prefer bins whose residual is already below average (they are "nearly done").
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.5;
    } else {
        score += (bin_res_f - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed
    // (no tight fits available and many open bins are fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // If open bins are highly fragmented (large mean residual), a new bin is OK.
        score += 350.0 - fragmentation * 250.0;
        // Early in the stream, opening new bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 100.0;
    }

    // Mild preference to keep number of open bins low when many are open.
    score += open_bins_count as f64 * 2.0;

    score
}

