pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness;

    // Penalize creating dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 18.0 + 0.2 * (next_item_size as f64);
        } else {
            // penalize leaving a residual that nothing useful can use
            score += 6.0 * (1.0 - (post_residual as f64) / cap);
        }
    }

    // Last chance: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in stream, prefer keeping flexibility (favor new bins
    // for large items); late in stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill_ratio = (item_size as f64) / cap;
    if fill_ratio > 0.5 {
        score -= 12.0 * progress;
    } else {
        score += 8.0 * (1.0 - progress);
    }

    // Global state: if many open bins with slack, discourage opening new bins;
    // penalize bins whose residual deviates wildly from the mean (fragmentation).
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
        score -= 1.5 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let waste_penalty = 10.0 * (1.0 - fill_ratio);
        score += waste_penalty - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: never waste this bin again.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Modulo-10 class of post_residual.
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.4;

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            score -= 12.0;
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
            if after <= 3 {
                score -= 12.0;
            } else if after < next_item_size {
                // Residue can't host a repeat of next item: mild penalty.
                score += 4.0;
            } else {
                score -= 8.0;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            // Dead space relative to lookahead: penalize proportionally,
            // but less when the gap is tiny (item almost fits).
            score += gap * 0.5;
            if gap <= 8.0 {
                score += 3.0 + 0.5 * (8.0 - gap);
            }
        } else if bin_residual >= next_item_size {
            // Empty-ish bin (post_residual == 0 handled above) that could
            // host the lookahead item after this one.
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 42.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins below the mean (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Small-residue dead-space shaping.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    // Scarcity-aware dead-space handling.
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Mid-band residue (30-60) is valuable for medium items.
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        // Chained fits: post_residual can host next item twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 10.0;
            }
            if chain > 0 && chain % 10 == 0 {
                score -= 4.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Progress-weighted penalty on residual: late in stream, small residuals matter more
    let poly = norm_pr * (1.0 + 2.0 * progress * norm_pr - 3.0 * progress * progress * norm_pr * norm_pr);
    score += 40.0 * poly;

    // Reward tight fits with a smooth quadratic bonus
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (1.0 + progress);

    // Next-item lookahead: reward residual that smoothly matches next item
    if next_item_size > 0 {
        let match_term = (norm_pr - norm_next) * (norm_pr - norm_next);
        score += 20.0 * match_term * (1.0 - progress);
        // reward if next item fits exactly in post residual
        let fits_next = (norm_next <= norm_pr) as i32 as f64;
        score -= 10.0 * fits_next * norm_next * (1.0 - progress);
    }

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize fragmenting bins with large residuals when few bins remain
    let open_pressure = 1.0 / (1.0 + open_bins_count as f64);
    score += 15.0 * norm_pr * norm_pr * open_pressure;

    // New-bin candidate handling: smooth neutral-ish score
    let is_new = (bin_residual == bin_capacity) as i32 as f64;
    score += is_new * (pr + 10.0 + 20.0 * (1.0 - progress));

    // Mean residual coupling: prefer bins below mean residual (tighter)
    let dev = (mean_residual - pr) / cap;
    score += 10.0 * dev * dev - 5.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Perfect fit: post_residual in {0} -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post residual divisible into useful chunks (mod arithmetic).
    // Classes: 0, exact halves (50), quarters (25/75), small slivers (<10 = dead space).
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 30.0; // leaves exact half-capacity, very reusable
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Dead space penalty: tiny slivers that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Coupling with next item: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 200.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // reward good chaining, penalize large leftover after chaining
            score -= 25.0 * (1.0 - gap / cap);
        } else {
            // next item cannot use this residual: mild penalty scaled by wasted fraction
            score += 10.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: make fresh bins attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.55;
        // cheaper to open a bin if item is large (would leave little residual anyway)
        score -= 0.3 * item_size as f64;
        // if many bins already open and mean residual is high, prefer reusing
        if open_bins_count > 0 {
            score += 0.35 * mean_residual;
        }
        // lookahead: if next item is large, a fresh bin is more valuable
        if next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // mild preference to consolidate into bins with smaller residuals (better fit)
        score += 0.2 * (mean_residual - post).max(0.0);
    }

    // Progress-based nudge: early in stream, be slightly conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Medium dead space (10..=20) that few items can use.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 18.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use leftover: penalize proportional to leftover.
        score += 0.3 * post_residual as f64;
    }

    // New-bin candidate handling: prefer new bin only when no good fit exists.
    if bin_residual == bin_capacity {
        // New bin is penalized when a decent fitting bin exists.
        if fitting_bins_count > 0 {
            score += 30.0 + 5.0 * fitting_bins_count as f64;
        }
        // But if the item would leave a large hole in existing bins, ease new bin.
        score -= 0.15 * mean_residual;
    }

    // Mild time pressure: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (bin_residual as f64 - item_size as f64).max(0.0) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let leftover_after_next = post_residual - next_item_size;
            score -= 150.0 - leftover_after_next as f64 * 2.0;
        } else {
            // next item cannot follow here -> penalize large post_residual waste
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin unless item is large and fits poorly elsewhere
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 120.0 + waste * 0.8;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 80.0; // large stream of items: new bin useful
        }
    }

    // Slight pressure to consolidate early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.85;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty for large waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 40.0;

    // Reward bins whose post-residual can still host the next item (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward when post_residual closely matches next item (near-perfect chain).
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= (1.0 - chain_waste / bin_capacity as f64).max(0.0) * 8.0;
        } else {
            // Penalize leaving a small unusable sliver relative to next item.
            let sliver = post_residual as f64 / next_item_size.max(1) as f64;
            score += sliver * 6.0;
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score -= (bin_residual - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: big reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins when open bins fit well,
    // but allow it when existing residuals are fragmented / mean residual is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 30.0;
        // If mean residual across open bins is small (bins nearly full), opening is fine.
        new_bin_penalty -= (mean_residual / bin_capacity as f64).min(1.0) * 20.0;
        // Early in stream: slightly cheaper to open bins (build diversity).
        new_bin_penalty -= (1.0 - progress) * 10.0;
        // If many bins already fit the item, discourage new bin.
        if fitting_bins_count > 1 {
            new_bin_penalty += (fitting_bins_count as f64 - 1.0) * 5.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild penalty for scattering across too many open bins when this bin is loose.
    let waste = (bin_residual - item_size) as f64;
    score += waste * 0.15 * (open_bins_count as f64).ln().max(1.0) * 0.5;

    // Prefer bins whose residual aligns with common future needs (mean-residual coupling).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits, non-linearly scaled by stream progress
    let mut score = post * (1.0 + 0.8 * post_norm * post_norm);

    // Smooth polynomial coupling: post_residual vs progress
    let coupling = post_norm * post_norm * (1.0 - post_norm);
    score += 15.0 * coupling * (0.5 + progress);

    // Penalize large residuals more as stream progresses
    score += 20.0 * post_norm.powi(3) * progress;

    // Reward filling bins nearly full
    let fill = 1.0 - post_norm;
    score -= 10.0 * fill * fill * fill;

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - (post - nxt) / cap;
            score -= 12.0 * snug * (0.5 + progress);
        } else {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln();

    // New-bin candidate: keep neutral-ish baseline, slightly discouraged early, allowed late
    if bin_residual == bin_capacity {
        score += 8.0 - 10.0 * progress;
    }

    // Tie-break with mean residual deviation
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Residual class rewards: exact fills are gold, tiny residues are good.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 32.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    } else {
        score -= 18.0; // large residue classes remain reusable (from parent)
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after < class_width {
                score -= 18.0;
            } else {
                score -= 20.0 + 0.1 * (after as f64);
            }
            if after >= 2 * next_item_size {
                score -= 8.0;
            }
            if after > 0 && after % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Dead space relative to lookahead: penalize proportional gap.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 8.0 {
                score += 4.0 + 0.8 * (8.0 - gap);
            } else if gap <= 20.0 {
                score += 3.0 * (20.0 - gap) / 20.0;
            } else if post_residual >= 11 {
                score += 10.0;
            } else if bin_residual >= next_item_size {
                score += 30.0;
            }
        }
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity: f64 = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0 && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 42.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Last-chance bin: only fitting bin, avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mean-residual coupling: prefer tighter bins.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Dead-space shaping.
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Mid-band residue attraction around 0.325 cap.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let dist = ((post_residual as f64) - 0.325 * cap).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Near-fit gap penalty: bin almost fits next item too.
        if next_item_size > 0 && post_residual < next_item_size && dead_ratio > 0.15 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
        }
        // Chain potential: residue can host next item twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 10.0;
            }
        }
        // Small waste penalty under quarter cap.
        if post_residual < bin_capacity / 4 {
            let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
            score += waste * 14.0;
        }
    }

    // Stream-end consolidation: late items prefer filling existing bins tightly.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - (post_residual as f64) / cap);
    }
    if stream_left < 0.05 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
    }

    // Modulo-10 dead space friendliness (from parent).
    score += ((post_residual % 10) as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity fraction buckets.
    // Small post-residuals are good; classify via integer division thresholds.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -40.0 // perfect fit
    } else if pr <= 10 {
        -20.0
    } else if pr <= 20 {
        -8.0
    } else if pr <= 30 {
        0.0
    } else if pr <= 50 {
        6.0
    } else {
        12.0 // large dead space
    };
    score += class;

    // Modulo arithmetic flavor: residuals that are multiples of common small
    // item sizes are more likely to be filled later -> reward them.
    if pr > 0 {
        let div_common = (pr % 10 == 0) as i32 as f64 * 3.0
            + (pr % 20 == 0) as i32 as f64 * 3.0
            + (pr % 25 == 0) as i32 as f64 * 2.0;
        score -= div_common;
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits exactly-ish -> strong reward, scaled by tightness.
            let tight = 1.0 - (pr - next_item_size as u32) as f64 / cap;
            score -= 10.0 + 15.0 * tight;
        } else {
            // Next item won't fit here: penalize leaving residual just above
            // the next item size (wasted opportunity).
            let gap = (pr - next_item_size as u32) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is bad
    // and the item is large (little chance of future pairing).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Opening a new bin is attractive for large items or when the stream
        // is early (more future items to fill the fresh bin).
        let early = 1.0 - step_index as f64 / (total_items.max(1) as f64);
        let penalty = 20.0 - 18.0 * item_frac - 10.0 * early * item_frac;
        score += penalty;
        // A new bin with a large item leaves residual = cap - item; if that
        // residual matches a harmonic class of common sizes, soften penalty.
        let new_res = bin_capacity - item_size;
        if new_res % 10 == 0 {
            score -= 4.0;
        }
    }

    // Mild pressure to prefer filling bins when many bins are open.
    score += open_bins_count as f64 * 0.3 * (1.0 - item_size as f64 / cap);

    // Prefer bins whose residual is close to the mean residual (balance loads).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ni = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let stream_left = ((total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64).min(1.0);
    let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);

    // Perfect fit is always ideal.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of post_residual.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if pr >= half {
        score -= 18.0;
    } else if pr >= quarter {
        score -= 6.0;
    } else {
        score += 8.0;
    }

    // Exact match with the lookahead item: extremely valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            score -= 18.0 + 0.1 * after as f64;
            // Chained fits: bin could host the next item twice.
            if after >= next_item_size as u32 {
                score -= 10.0;
            }
            if after <= 3 {
                score -= 12.0;
            } else if after >= 20 && after <= 30 {
                score -= 6.0;
            }
        } else {
            // Dead space relative to lookahead: penalize proportionally,
            // but soften when bins are scarce (item may have nowhere else).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5 * (0.4 + 0.6 * scarcity);
        }
    }

    // Modulo-10 class of post_residual.
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.4;
    if post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Last-chance bin: strongly avoid opening a new bin when scarce.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0 && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < ni * 1.15 && fitting_bins_count < 4)
                || (total_fit_capacity < ni * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 42.0;
        } else {
            score += 45.0;
            // A fresh bin is acceptable late in the stream for large items.
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
        }
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Coupling with mean residual: prefer tighter bins.
    score -= (mean_residual - pr) * 0.15;

    // Waste penalty for dead space just below a quarter of capacity.
    if post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    // Dead-ratio bands.
    let dead_ratio = pr / cap;
    if dead_ratio < 0.10 {
        let crowd = (open_bins_count as f64 / 60.0).min(1.0);
        score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
    } else if dead_ratio > 0.55 && next_item_size > 0 && ni > dead_ratio * cap {
        score -= 12.0 + 8.0 * (1.0 - scarcity);
    }

    // Near-miss gap penalty: bin almost fits the next item.
    if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 8 {
        let gap = (next_item_size - post_residual) as f64;
        score += 4.0 + 0.8 * (8.0 - gap);
    }

    // Mid-range residual band is useful for future small items.
    if post_residual >= 30 && post_residual <= 60 {
        score -= 4.0 + 3.0 * stream_left;
    }

    // Endgame consolidation: squeeze remaining items into open bins.
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    } else if post_residual > 10 && post_residual <= 25 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: reward leaving space that still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open,
    // but encourage consolidation when open bins are numerous.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (20.0 + 15.0 * progress + 2.0 * open_bins_count as f64);

    // Prefer bins with below-average residual (tighter bins first).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 5.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 3.0 * (res - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
