pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward residuals that exactly match the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if post_residual as u32 == next_item_size {
            score -= 300.0;
        }
        // Penalize residuals too small for the next item (dead space risk).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 50.0 * fill;

    // Penalize small unusable residuals relative to mean residual.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin can host the next item too
        }
    }

    // Mild preference to fill older/more crowded bins early in the stream.
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    score -= (cap - post_residual as f64).powf(1.8) * 0.05;

    // Penalize dead space relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.7;

    // Lookahead: reward bins whose post residual can host the next item (k=2).
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 + next_item_size as f64 * 0.08;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving residual too small to ever be useful again.
        score += (post_residual as f64).powf(1.4) * 0.25;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is penalized, but becomes
    // attractive when no open bin fits well or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 18.0 + open_bins_count as f64 * 1.5;
        if next_item_size > 0 && next_item_size >= item_size {
            open_cost -= 4.0; // fresh bin pairs well with a big next item
        }
        if progress < 0.2 {
            open_cost -= 5.0; // cheap to open early in the stream
        }
        score += open_cost;
    }

    // Prefer bins with smaller residual before placement (denser bins first).
    score += (bin_residual as f64 / cap) * 3.0;

    // Mild time-horizon coupling: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (cap - post_residual as f64) * progress * 0.15;

    // Small penalty for many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
