pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    // Base: prefer small post-residual, with non-linear decay so tiny residuals are strongly favored.
    let mut score = pr - 6.0 * (1.0 - (pr / cap).powf(2.0)) * (pr / cap) * cap * 0.25;

    // Smooth stream-progress coupling: late in the stream, tighten residual requirements.
    score += t * pr * 0.35;

    // Penalize new-bin opening progressively (more costly later, but cheap early).
    score += is_new * (18.0 + 30.0 * t * t);

    // Reward using the last fitting bin (avoid opening a bin for a poor fit).
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 12.0;
    }

    // Lookahead coupling: bonus if next item fits the post-residual, penalty if it barely misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference for bins with residuals near the mean (keeps bins homogeneous).
    score += ((pr - mean_residual) / cap).powi(2) * 4.0;

    // Mild load-balancing pressure across open bins.
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: never waste this bin again.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 32.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < class_width {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else if post_residual >= 11 {
            score += 10.0;
        } else if bin_residual >= next_item_size {
            score += 30.0;
        }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after <= 3 {
                score -= 12.0;
            } else if after >= 20 && after <= 30 {
                score -= 6.0;
            } else if after < next_item_size && after >= 11 {
                score += 4.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if gap <= 8.0 {
                score += 3.0 + 0.5 * (8.0 - gap);
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity: f64 = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 42.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins below the mean (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.05;

    // Small-residue dead-space shaping.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    // Scarcity-aware dead-space handling.
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 8 {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.8 * (8.0 - gap);
        }
        // Mid-band residue (30-60) is valuable for medium items.
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Attractor band around 0.325 of capacity.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * ((1.0 - dist / (0.125 * cap)).max(0.0));
        }
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        if next_item_size > 0 && post_residual < next_item_size && dead_ratio > 0.15 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual < next_item_size && scarcity < 0.5 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 3 && after <= 15 {
                score -= 3.5 * (1.0 - scarcity);
            } else if after > 15 && after <= 30 && scarcity < 0.7 {
                score -= 2.0 * (1.0 - scarcity);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after < 5 {
                score += 2.0 + 0.5 * (5 - after) as f64;
            }
        }
        if next_item_size > 0 && post_residual < next_item_size && post_residual % 5 == 0 && post_residual >= 5 {
            score += 2.0 * (1.0 - scarcity);
        }
        if dead_ratio > 0.12 && dead_ratio < 0.20 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after < cap * 0.06 {
                score -= 3.0 * (1.0 - after / (cap * 0.06));
            }
        }
        if dead_ratio > 0.50 && fitting_bins_count <= 1 {
            score += 4.0 * (dead_ratio - 0.50) * 10.0 * (1.0 - scarcity);
        }
    }

    // Absolute residue bands.
    if post_residual >= 35 && post_residual <= 55 {
        score -= 7.0;
    } else if post_residual >= 56 && post_residual <= 70 && next_item_size <= 55 && next_item_size > 0 {
        score -= 3.0;
    }

    // Chained fits: post_residual can host next item multiple times.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        if chain >= next_item_size {
            score -= 10.0;
        }
        if chain > 0 && chain % 10 == 0 {
            score -= 4.0;
        }
        if chain >= 2 * next_item_size {
            score -= 6.0;
        }
    }

    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 1.5;
    }

    // End-of-stream: tighten usage of nearly-full bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - (post_residual as f64 / cap));
    }
    if stream_left < 0.05 && post_residual >= next_item_size && next_item_size > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "reusable" class (small, or matching common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Modulo-10 class: leftover divisible by 10 is more likely reusable.
        let cls = pr % 10;
        if cls == 0 {
            score -= 6.0;
        } else {
            score += cls as f64 * 0.3;
        }
        // Perfectly filled bin is ideal.
        if pr < 5 {
            score -= 15.0;
        }
        // Integer-division thresholds: leftover in [20, 40] is a sweet spot
        // (fits half of typical items), leftover in dead zone (1..10) is bad.
        if pr / 10 == 2 || pr / 10 == 3 {
            score -= 4.0;
        }
        if pr < 10 && pr >= 5 {
            score += 8.0; // dead space penalty
        }
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            // Harmonic bonus: exact class match (next item fills leftover to a
            // multiple of 10).
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer tighter bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Late in the stream, favor closing bins tightly (fewer bins overall).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 { -20.0 } else { 25.0 };
        score = score.max(0.0) + penalty + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any nonzero leftover that is too small to
    // hold a typical item is nearly unusable dead space -> heavy penalty.
    if post_residual > 0 {
        // small gaps are the worst; scale penalty as gap shrinks
        let gap = post_residual as f64;
        score += 40.0 * (1.0 - gap / bin_capacity as f64).powi(6);
        // absolute dead-zone: gap below common minimum item size
        if post_residual < 10 {
            score += 60.0;
        }
        // gap that cannot fit the known next item
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0;
        }
    } else {
        // perfect fill: strong reward
        score -= 30.0;
    }

    // Reward tight fits (small post_residual relative to bin)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many open bins
    score += 2.5 * open_bins_count as f64;

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin would leave a very poor fit.
    if bin_residual == bin_capacity {
        // fresh bin baseline; make it unattractive unless dead-space penalty dominates
        score += 15.0;
        if post_residual == bin_capacity {
            score += 10.0; // avoid trivially opening bins early in stream
        }
    }

    // Lookahead: if next item fits exactly into the post residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Late in the stream, prefer closing bins tightly (consolidation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins below mean residual (balance loads)
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward: strongly favor bins whose residual exactly matches the item.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if next item exactly fills the post_residual, this is a perfect pairing.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 400.0;
    }
    // Next item fits comfortably into post_residual (with slack) — mild reward.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 50.0 - (post_residual as f64 - next_item_size as f64).min(40.0);
    }
    // Next item would NOT fit here: penalize leaving residual sized just below next item (dead space trap).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 30.0 + (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to residual: small post_residual is good, but not if unusable.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 80.0 * tightness;

    // Compare post_residual against mean residual across open bins.
    // Placing into a bin with residual well above mean keeps balance; placing into a
    // below-mean bin wastes a "fat" bin — prefer consuming the skinniest usable bin.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.6;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 120.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 60.0; // nearly exact fit in last-chance bin
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual; penalize it
    // moderately so open bins with decent fits win, but allow it when fits are poor
    // (its base score is high, so only bad fits in open bins will lose to it).
    if bin_residual == bin_capacity {
        score += 150.0;
        // Early in the stream, opening bins is cheaper; late in stream, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 100.0 * progress;
    }

    // Penalize creating small unusable slivers of dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Slight penalty per already-open bin to discourage bin sprawl.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: never waste this bin again.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Fine-grained residue shaping: small residues (<10) are near-perfect.
    if post_residual > 0 && post_residual < 10 {
        score -= 32.0;
    }
    // Modulo-10 class of post_residual.
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.4;
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            score -= 12.0;
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
            if after <= 3 {
                score -= 12.0;
            } else if after < next_item_size {
                score += 4.0;
            } else {
                score -= 8.0;
            }
            // Chained fits: post_residual can host next item twice.
            if after >= next_item_size {
                score -= 10.0;
                if after >= 2 * next_item_size {
                    score -= 6.0;
                }
            }
            if after > 0 && after % 10 == 0 {
                score -= 4.0;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if gap <= 8.0 {
                score += 3.0 + 0.5 * (8.0 - gap);
            } else if gap <= 20.0 {
                let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                score += 3.0 * (20.0 - gap) / 20.0 * (1.0 - scarcity);
            }
        } else if bin_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 42.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins below the mean (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Small-residue dead-space shaping.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    // Scarcity-aware dead-space handling.
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Mid-band residue (30-60) is valuable for medium items.
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        // Sweet-spot band: 35-55 residue pairs well with typical mid-size items.
        if post_residual >= 35 && post_residual <= 55 {
            score -= 7.0;
        } else if post_residual >= 56 && post_residual <= 70 && next_item_size > 0 && next_item_size <= 55 {
            score -= 3.0;
        }
        // Band around 0.325 capacity attracts medium lookahead items.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Large residue with few fitting bins: reward hosting lookahead.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // Endgame: squeeze remaining space hard.
        let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if stream_left < 0.15 && bin_residual != bin_capacity {
            score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - dead_ratio);
        }
        if stream_left < 0.05 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Penalize dead space: post_residual too small to fit any plausible item (1..=100).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this bin's leftover; mild penalty scaled by wasted potential.
        score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Perfect lookahead match: post_residual == next_item_size is ideal.
    if next_item_size == post_residual && next_item_size > 0 {
        score -= 35.0;
    }

    // Time horizon: late in the stream, prefer consolidating into existing bins
    // (fewer bins), so reward open-bin placements more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 15.0 * progress;
    } else {
        // New-bin candidate: penalize opening new bins when decent alternatives exist,
        // more so late in the stream and when many bins are already open.
        score += 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // But if open bins are all quite full (high mean fill), opening a new bin is fine.
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        if mean_fill > 0.7 {
            score -= 35.0 * (mean_fill - 0.7) / 0.3;
        }
    }

    // If mean residual is large (lots of slack around), prefer bins below-average residual
    // (fill the emptier ones first to consolidate).
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score += 6.0;
    } else if bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Slight preference for bins whose post residual is a "clean" divisible chunk
    // (friendly to future items): reward residuals >= 50 less harshly.
    if post_residual >= 50 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
