    if next > 0.0 {
        if next <= post {
            score -= 1.5 * (1.0 - (next / cap)) * (1.0 - progress * 0.5);
        } else {
            score += 0.8 * (post / cap) * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item would leave a large unusable gap in every existing bin.
    if bin_residual == bin_capacity {
        // Mild default penalty so existing decent fits win
        score += 0.6;
        // But if post-residual in a fresh bin is small (item nearly fills it), reward opening
        score -= 1.2 * (1.0 - norm_post) * (1.0 - norm_post);
        // Late in the stream, consolidation matters more; penalize new bins more
        score += 0.8 * progress;
    }

    // Slight preference for bins whose residual is close to the mean (balance),
    // coupled smoothly with open-bin pressure.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 0.3 * dev * (1.0 + (open_bins_count as f64).ln().max(0.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: never waste this bin again.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 32.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < class_width {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else if post_residual >= 11 {
            score += 10.0;
        } else if bin_residual >= next_item_size {
            score += 30.0;
        }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after <= 3 {
                score -= 12.0;
            } else if after >= 20 && after <= 30 {
                score -= 6.0;
            } else if after < next_item_size && after >= 11 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 42.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Coupling with mean residual (weakened vs parent).
    score += (mean_residual - post_residual as f64) * 0.05;

    // Small-residue dead-space shaping.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);

        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }

        // Tight-gap lookahead: next item almost fits.
        if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 8 {
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.8 * (8.0 - gap);
        }

        // Mid-band residue (30-60) valuable for medium items.
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }

        // Narrow dead-ratio spike shaping.
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }

        // Attractive band around 0.325 residual ratio.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }

        // Sparse bins with generous residue that host the lookahead item.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }

        // Moderate gap penalty scaled by scarcity.
        if next_item_size > 0 && post_residual < next_item_size && dead_ratio > 0.15 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
        }

        // Chain fits: post_residual can host next item multiple times.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 10.0;
            }
            if chain > 0 && chain % 10 == 0 {
                score -= 4.0;
            }
            if chain >= 2 * next_item_size {
                score -= 6.0;
            }
        }

        // Exact-fit residue classes.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual < next_item_size && scarcity < 0.5 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }

        // After-fit band shaping.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 3 && after <= 15 {
                score -= 3.5 * (1.0 - scarcity);
            } else if after > 15 && after <= 30 && scarcity < 0.7 {
                score -= 2.0 * (1.0 - scarcity);
            }
        }

        // Tiny leftover after fit: slight penalty (waste).
        if next_item_size > 0 && post_residual > next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after < 5 {
                score += 2.0 + 0.5 * (5 - after) as f64;
            }
        }

        // Round residue that can't host next: mild penalty when scarce.
        if next_item_size > 0 && post_residual < next_item_size && post_residual % 5 == 0 && post_residual >= 5 {
            score += 2.0 * (1.0 - scarcity);
        }

        // Post-fit near-zero residue shaping.
        if dead_ratio > 0.12 && dead_ratio < 0.20 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after < cap * 0.06 {
                score -= 3.0 * (1.0 - after / (cap * 0.06));
            }
        }

        // Large residue with only one fitting bin: mild penalty.
        if dead_ratio > 0.50 && fitting_bins_count <= 1 {
            score += 4.0 * (dead_ratio - 0.50) * 10.0 * (1.0 - scarcity);
        }
    }

    // Fixed mid-band residue shaping.
    if post_residual >= 35 && post_residual <= 55 {
        score -= 7.0;
    } else if post_residual >= 56 && post_residual <= 70 && next_item_size <= 55 && next_item_size > 0 {
        score -= 3.0;
    }

    // Round residue bonus.
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Endgame tightening: near the end, prefer bins with more usable residue.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - (post_residual as f64 / cap));
    }
    if stream_left < 0.05 && post_residual >= next_item_size && next_item_size > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic class of post_residual: classify dead space by divisibility
    let pr = post_residual;
    if pr > 0 {
        // Dead space smaller than smallest item (1) can't happen; but small dead space
        // that no plausible item can fill is waste. Penalize unusable slivers.
        if pr < 10 {
            score += 30.0; // tiny unusable fragment
        } else if pr % 10 == 0 {
            score -= 8.0; // residual in a harmonic class (multiple of 10) is reusable
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Odd/prime-ish residuals are harder to fill: mild penalty
        if pr % 2 == 1 {
            score += 2.0;
        }
    }

    // Reward bins whose residual matches the next item's harmonic class
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // sets up a perfect fit for lookahead item
        } else if post_residual > next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 6.0; // leaves another harmonic-class residual
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0; // blocks the lookahead item entirely
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: discourage opening a new bin when a decent fit exists
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin is fine if it can host the next item too
        }
    }

    // Late in the stream, prefer consolidating into tight residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    // Prefer bins below mean residual (fill emptier bins first, keep tight ones tight)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

