pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common
    // item sizes are reusable; prime/awkward leftovers are dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reusability bonus: leftover divisible by 10/20/25/50 classes
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 6.0;
            if post_residual % 50 == 0 { score -= 4.0; }
            else if post_residual % 25 == 0 { score -= 2.5; }
        }
        // Awkward prime-band leftovers (just above a half bin) are dead space
        if post_residual > 45 && post_residual < 60 && post_residual % 5 != 0 {
            score += 5.0;
        }
    } else {
        // Perfect closure is excellent
        score -= 15.0;
    }

    // Integer-division threshold classes on post_residual
    let quarter = (post / (cap / 4.0)).floor(); // 0..4 class
    score += quarter * 3.0 - 6.0; // prefer smaller quarter classes

    // Lookahead coupling: next item should fit the leftover class
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 8.0;
            // exact harmonic match: leftover is a multiple of next item
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot fit here: mild penalty scaled by gap
            score += (nxt - post) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (mean_residual.max(1.0) / cap);
        if post_residual as f64 >= item_size as f64 {
            score += 20.0; // default: discourage opening new bin
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        let _ = pressure;
    }

    // Late-stream tightening: minimize waste as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * (0.05 + 0.10 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste. Penalize them quadratically.
    let dead_threshold = 12.0; // gap below which nothing useful typically fits
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins rather than spreading out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.0 + 0.5 * progress);

    // Penalize new-bin opening unless the fit in existing bins is truly poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin grows with number of open bins.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If the current item would leave a large usable gap and the next item
        // is large, a fresh bin can be attractive.
        if next_item_size > 0 {
            let gap_for_next = post_residual as i64 - next_item_size as i64;
            if gap_for_next >= 0 {
                score -= 35.0; // fresh bin also accommodates the next item
            }
        }
        // Late in the stream, discourage spreading into fresh bins.
        score += 20.0 * progress;
    } else {
        // Favor bins whose residual is close to the mean (balanced packing),
        // slightly, to avoid extreme outlier gaps.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
        // Lookahead: if the post-placement gap exactly fits the next item,
        // this is a chained perfect fit — reward it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 10.0;
        }
    }

    score
}

