    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize mildly so it's only chosen when
    // open bins are poor fits, but allow it for large items.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, avoid leaving many partially filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64 / total_items.max(1) as f64);

