    // Strongly reward tight fits (low post residual) with a non-linear term.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr / cap) * (pr / cap) * 40.0;

    // Penalize dead space that can never be refilled by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
