        // Last item in stream: just minimize waste.
        score -= 10.0;
    }

    // New empty bin candidate: baseline penalty so it's chosen only when
    // open bins fit poorly, scaled by how many alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 55.0;
