    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - (post_residual as f64 / cap));
    }
    if stream_left < 0.05 && post_residual >= next_item_size && next_item_size > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (< 10, minimum item size) are pure waste: heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // Gaps too small for the next item (lookahead) are likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Perfect / near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // --- Open-bins pressure ---
    // With many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.15 + 0.1 * progress);
    // New-bin candidate: add a base opening cost so it only wins when existing
    // bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 25.0 + pressure;
    } else {
        score -= pressure.min(10.0);
    }

    // Last-chance bin (only one fitting bin): reward using it to avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bin).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild preference for placing large items into tighter bins.
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Residual class bands: dead space cost scales with unusability.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 32.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 25.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }

    // Harmonic residuals are more reusable.
    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= harmonic as f64 * 15.0;
        if post_residual % 5 == 0 { score -= 1.5; }
    }

    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            score -= 20.0 + 0.1 * after as f64;
            if after <= 3 { score -= 12.0; }
            if after >= next_item_size { score -= 10.0; }
            if after % 10 == 0 { score -= 4.0; }
            if after >= 2 * next_item_size { score -= 6.0; }
        } else if bin_residual >= next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 30.0;
            if gap <= 8.0 { score += 4.0 + 0.8 * (8.0 - gap); }
        } else if post_residual >= 11 {
            score += 10.0;
        }
        if post_residual < next_item_size && next_item_size - post_residual <= 15 {
            let gap = (next_item_size - post_residual) as f64;
            score += 2.5 * (15.0 - gap) / 15.0;
        }
        if post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
    }

    // Last-chance bin strongly preferred over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin decision: open a fresh bin only for big items, crowded state,
    // or when the next item genuinely needs fresh space.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity: f64 = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 42.0;
        } else {
            score += 45.0 + 0.5 * mean_residual;
            if next_item_size > 60 && post_residual > 25 { score -= 30.0; }
            if open_bins_count > 40 && next_item_size >= 50 { score -= 8.0; }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Global alignment with fleet mean residual.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Dead-space shaping near quarter capacity.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Sweet-spot band around 20-45% residual keeps bins reusable.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-range residual (30-60) is highly reusable late in stream.
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        // Near-miss gap for next item with scarcity weighting.
        if next_item_size > 0 && post_residual < next_item_size && dead_ratio > 0.15 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
        }
        // Almost-exact chain fits.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 3 && after <= 15 {
                score -= 3.5 * (1.0 - scarcity);
            }
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after < 5 {
                score += 2.0 + 0.5 * (5 - after) as f64;
            }
        }
        // Endgame: squeeze residual use hard as stream winds down.
        let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if stream_left < 0.15 && bin_residual != bin_capacity {
            score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - dead_ratio);
        }
        if stream_left < 0.05 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
        // Reserve large residuals when the next item is large.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match between post_residual and next item
    if next_item_size > 0 {
        let post = post_residual as i64;
        let nxt = next_item_size as i64;
        let diff = (post - nxt).abs() as f64;

        // Perfect match: post_residual exactly equals next_item_size -> huge reward
        if diff == 0.0 {
            score -= 200.0;
        } else {
            // Penalize proportional to mismatch, amplified near-perfect fits
            score += diff * 1.5;
            if diff <= 10.0 {
                score -= 30.0 - diff * 2.0; // near-match bonus
            }
        }

        // If next item cannot fit in post_residual, this bin leaves dead space
        if nxt > post {
            score += (nxt - post) as f64 * 1.2;
        }
    }

    // Tightness reward: small post_residual relative to capacity is good
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * -0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 + 20.0 * (open_bins_count as f64).sqrt() };
        score += pressure;
        // But if next item is large and current item small, a fresh bin may be good
        if next_item_size > 60 && item_size < 30 {
            score -= 25.0;
        }
    }

    // Late-stream consolidation: fewer open bins preferred near end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space that nothing can use (items >= 1)
    if post_residual > 0 && post_residual < 4 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when current bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is expensive; make it unattractive unless fit elsewhere is bad
        score += 30.0;
        // But if the item fits perfectly in a fresh bin and existing bins are fragmented, allow it
        if item_size == bin_capacity {
            score -= 100.0;
        }
        // If mean residual is low (bins nearly full), a new bin is more acceptable
        score -= (mean_residual / bin_capacity as f64) * 25.0;
    } else {
        // Reward using existing bins, more so when many are open (avoid bin proliferation)
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Lookahead coupling: if the next item would fit in the post-residual, reward this placement
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 10.0;
            // Extra reward for a near-perfect two-item chain
            let chain_waste = post_residual as f64 - next_item_size as f64;
            score -= 6.0 * (1.0 - chain_waste / bin_capacity as f64).max(0.0);
        } else {
            // Next item won't fit here; penalize leaving a large unusable gap
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 0.15 * gap;
            }
        }
    } else {
        // Last item: minimize waste outright
        score = post_residual as f64 - 50.0;
    }

    // Time horizon: early in the stream, be conservative with new bins; later, tolerate slack
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += (1.0 - progress) * 15.0;
    }

    // Prefer bins whose residual deviates from the mean (consolidate fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild penalty for very loose fits regardless
    if fit_ratio < 0.3 && !is_new_bin {
        score += 5.0 * (0.3 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
