pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear penalty for awkward residuals
    let mut score = pr
        + 40.0 * (norm_pr * (1.0 - norm_pr)).sin() * (0.5 + progress)
        - 30.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * 20.0 * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are open with room
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Lookahead coupling: favor residuals that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_term = if pr >= nx { (pr - nx) / cap } else { 1.0 };
        score += 20.0 * match_term * (1.0 - progress);
    }

    // Mean-residual deviation coupling
    score += 0.3 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
