pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (post_residual is the core signal).
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Harmonic classes: quantize post_residual into capacity/10 classes.
    // Residuals that are "harmonically useful" (multiples of 10, 20, 25, 50)
    // are favored; awkward residuals (1..9, 11..19 gaps) are penalized.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 { 60.0 }
        else if pr % 50 == 0 { 35.0 }
        else if pr % 25 == 0 { 28.0 }
        else if pr % 20 == 0 { 24.0 }
        else if pr % 10 == 0 { 18.0 }
        else { -12.0 * ((pr % 10) as f64 / 10.0) };
    score -= harmonic_bonus;

    // Lookahead coupling: does post_residual harmonically match next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let fit_gap = pr - next_item_size;
            score -= 25.0 * (1.0 - fit_gap as f64 / bin_capacity as f64);
            // Perfect two-item closure is excellent.
            if fit_gap == 0 { score -= 30.0; }
            // Integer-division threshold: leftover class after pairing.
            let left = fit_gap % 10;
            if left > 0 && left < 5 { score += 6.0; }
        } else {
            // Next item cannot use this bin's residual: residual likely dead.
            score += 10.0 + 0.15 * (pr as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins mildly; heavier when many bins open.
        score += 30.0 + 2.5 * open_bins_count as f64 + 20.0 * progress;
        // But if mean residual is small (all bins nearly full), opening is fine.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 35.0;
    } else {
        // Prefer bins with below-mean residual (consolidate emptiness).
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Penalize waste relative to item size: tiny items in huge bins.
    score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

