        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Scarce fitting bins with next item fitting: preserve.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // Near-miss gap penalty scaled by scarcity.
        if next_item_size > 0 && post_residual < next_item_size && dead_ratio > 0.15 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
        }
        // Exact/near exact next-item fit.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        // Dead-space ratio band 0.12-0.20 with lookahead.
        if dead_ratio > 0.12 && dead_ratio < 0.20 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after < cap * 0.06 {
                score -= 3.0 * (1.0 - after / (cap * 0.06));
            }
        }
        // Large residue with only one fitting bin: penalize.
        if dead_ratio > 0.50 && fitting_bins_count <= 1 {
            score += 4.0 * (dead_ratio - 0.50) * 10.0 * (1.0 - scarcity);
        }
    }

    // Targeted mid bands.
    if post_residual >= 35 && post_residual <= 55 {
        score -= 7.0;
    } else if post_residual >= 56 && post_residual <= 70 && next_item_size > 0 && next_item_size <= 55 {
        score -= 3.0;
    }

    // Multiples of 5 residues pack well.
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 1.5;
    }

    // End-of-stream: squeeze into existing bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }
    if stream_left < 0.05 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual relative to item, the better.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 4.0 * tightness * (bin_residual as f64);

    // Dead-space penalty: post_residual that is too small to be useful.
    // Anything below the minimum item size (1) is pure waste; penalize very
    // small gaps hard since they likely can never be filled.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Non-linear penalty peaking for small-but-nonzero gaps.
        let dead = (1.0 - gap / 30.0).max(0.0);
        score += 12.0 * dead * dead;
    } else {
        score -= 15.0; // perfect fit is excellent
    }

    // If the next item fits exactly in the post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty for stranding.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score -= pressure * 0.5;

    // Mean residual coupling: prefer bins with residual below mean (fill the emptier-feeling ones less),
    // i.e., penalize bins far above mean residual to balance loads.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when it would otherwise waste the item in a bad fit.
    if bin_residual == bin_capacity {
        // Baseline cost of a new bin, modulated by open bins pressure.
        score = 100.0 + pressure * 0.8 - tightness * 20.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        }
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 5.0;
        }
    }

    score
}

