pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize dead space
    // that can never be used by future items (items >= 1, so any residual > 0
    // is potentially usable; weight larger residuals more than linearly).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // Best-fit baseline: prefer bins where item fills a large fraction.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let slack_after_next = post_residual as f64 - next_item_size as f64;
        score -= 6.0 * (1.0 - slack_after_next / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize if we waste a near-full bin badly.
        score += 2.0 * (post_residual as f64 / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 12.0 + 6.0 * (1.0 - progress) + 0.5 * crowded;
        // Allow new bin when item barely fits anywhere (poor fit_ratio).
        score -= 10.0 * (1.0 - fit_ratio);
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - (post_residual as f64 / cap));

    // Prefer bins below mean residual (balancing residual distribution).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

