pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Normalized post-residual and its polynomial couplings with stream progress
    let x = pr / cap; // in [0,1)
    let x2 = x * x;
    let x3 = x2 * x;

    // Smooth base: penalize wasted space with convex growth
    let mut score = 2.0 * x + 3.0 * x2 + 1.5 * x3;

    // Non-linear interaction: late in the stream, waste is more costly
    let late = progress * progress;
    score += (1.0 + 4.0 * late) * x2 * (1.0 + 0.5 * (1.0 - progress));

    // Tight-fit reward: small post-residual is great, stronger when many bins compete
    let tight = (1.0 - x).powi(3);
    score -= tight * (1.0 + 0.3 * (fitting_bins_count as f64).ln().max(0.0));

    // Lookahead coupling: reward leaving space the next item can use
    let n = next_item_size as f64;
    if n > 0.0 {
        let usable = (n / cap - x).abs();
        score -= 1.5 * (-6.0 * usable).exp();
        // penalize leaving residual just below next item size (dead space)
        score += 2.0 * (-3.0 * (x - n / cap).abs()).exp() * (x < n / cap) as i32 as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 3.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no bin fits well
    if is_new_bin {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        // early stream: opening is cheap; late: prefer consolidation
        let openness = 1.0 - late;
        score = cap * (0.6 + 0.6 * late) - 2.5 * scarcity * openness;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64 * x;

    // Deviation from mean residual: prefer bins that are neither extreme outliers
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

