pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "useful" capacity fractions (small multiples of common item classes).
    let post = post_residual as u32;
    let class = post / 10; // integer-division threshold classes of 10
    let remainder = post % 10;
    // Residuals near multiples of 10 are more reusable; penalize ragged ones.
    score += remainder as f64 * 0.7;
    // Dead-space penalty for tiny unusable residuals (1..=9 class).
    if post > 0 && post < 10 {
        score += 12.0;
    }

    // Harmonic coupling with lookahead item: if the next item fits exactly
    // into the post-residual, this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post {
