        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post residual is good, super-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 30.0;

    // Lookahead: reward if next item fits into post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Perfect chain: next item exactly fills leftover.
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // Penalize dead space that next item cannot use.
            let waste = (post_residual as f64) - (next_item_size as f64 - post_residual as f64).abs();
            score += (post_residual as f64 - (next_item_size as f64).min(post_residual as f64)) * 0.35;
            let _ = waste;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; discourage
    // unless existing fit is very poor (large post residual relative to mean).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 45.0;
        // Early in stream, bins are cheap-ish to open; later, avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If many bins open, discourage spreading items further.
        score += open_bins_count as f64 * 1.5;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean:
        // use below-mean-residual bins first to consolidate.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += (bin_residual as f64 - mean_residual) * 0.25;
        }
    }

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Penalize leaving awkward residuals (small but unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: post residual, with non-linear polynomial shaping by stream progress
    let poly = 1.0 + 0.8 * progress * norm_pr + 0.6 * (1.0 - progress) * norm_pr * norm_pr;
    let mut score = pr * poly;

    // Reward tight fits more strongly as the stream progresses
    let tight = 1.0 - norm_pr;
    score -= 18.0 * tight * tight * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if nxt > 0.0 {
        let waste = (pr - nxt).max(0.0) / cap;
        score += 25.0 * waste * waste * (1.0 + progress);
        // Reward bins that can also host the next item
        if pr >= nxt {
            score -= 10.0 * (1.0 - progress) * (nxt / cap);
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins early
    score += 0.6 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    // Coupling with mean residual: prefer bins deviating from mean when tight
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize slightly unless current bin leaves bad residue
    if bin_residual == bin_capacity {
        let bad_fit = (pr - nxt).max(0.0) / cap;
        score += 8.0 + 20.0 * bad_fit - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let scarcity = (fitting_bins_count as f64 / 5.0).min(1.0);

    // Perfect fit: absolute winner.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of post_residual.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else {
        score += 8.0;
    }

    // Exact lookahead match is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            score -= 20.0 + 0.1 * after as f64;
            if after <= 3 {
                score -= 12.0;
            } else if after >= next_item_size {
                score -= 10.0; // room for another copy of next item
            }
            if after % 10 == 0 && after > 0 {
                score -= 4.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if gap <= 8.0 {
                score += 4.0 + 0.8 * (8.0 - gap);
            }
        }
    }

    // Modulo-10 granularity of dead space.
    score += (post_residual % 10) as f64 * 0.4;

    // Last-chance bin: only fitting bin -> keep using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // NEW-BIN CANDIDATE logic.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && fitting_bins_count < 4)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 42.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
        }
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.05;

    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        // Very small dead space: reward proportionally.
        if dead_ratio < 0.10 {
            let crowd = (open_bins_count as f64 / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        }
        // Large dead space that cannot host the next item: penalize less when scarce.
        else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        }
        // Mid-band residual near a "sweet spot" around 0.325 cap.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Near-miss gap to next item with moderate dead space.
        if next_item_size > 0 && post_residual < next_item_size && dead_ratio > 0.15 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
        }
        // Dead space just above next item: keep chains tight.
        if dead_ratio > 0.12 && dead_ratio < 0.20 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after < cap * 0.06 {
                score -= 3.0 * (1.0 - after / (cap * 0.06));
            }
        }
        // Big dead space with only one fitting option: mild penalty.
        if dead_ratio > 0.50 && fitting_bins_count <= 1 {
            score += 4.0 * (dead_ratio - 0.50) * 10.0 * (1.0 - scarcity);
        }
    }

    // End-of-stream consolidation: squeeze open bins harder.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;
    let item_frac = item_size as f64 / cap;

    // Integer-division thresholds on post_residual: perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Modulo classes: residuals that form "harmonic" pairs with common small items
    // (multiples of 10) are more recoverable than odd dead space.
    let harmonic = post_residual % 10 == 0;
    if harmonic && post_residual > 0 {
        score -= 8.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny non-harmonic sliver is nearly dead space
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 10 {
                score -= 40.0;
            }
        } else {
            // next item cannot use this bin's remainder: residual is stranded
            score += post_frac * 40.0;
        }
    }

    // Last-chance bin: strongly prefer filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: opening fresh is penalized mildly, but attractive
    // when all open residuals are poor (high mean residual with many open bins).
    if bin_residual == bin_capacity {
        score = cap * 0.55; // baseline new-bin score
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual > 45.0 && open_bins_count > 2 {
            score -= 20.0 + progress * 10.0;
        }
        if item_frac > 0.6 {
            score -= 15.0; // big items do fine in fresh bins
        }
    }

    // Slight preference for tighter existing bins when item is small.
    if item_size <= 30 && bin_residual < bin_capacity {
        score -= item_frac * 10.0;
    }

    score
}

