pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for unusable small gaps.
    // Gaps below the minimum item size (1) are unavoidable, but gaps that
    // are too small to matter relative to typical item sizes are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable slivers are heavily penalized
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0; // risky mid-range gaps
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space pressure scales with stream progress: late in the stream,
    // avoid creating gaps that can never be filled.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // rather than spreading; penalize placements that leave large residuals
    // when bin count is already high.
    let bin_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += bin_pressure * (post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 25.0; // next item nearly fills this bin afterwards
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the gap at all: penalize proportionally.
        score += 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit, i.e. when mean residual is small and
    // open bins are numerous. Give the fresh bin a moderate base so it wins
    // only under pressure.
    if bin_residual == bin_capacity {
        score += 20.0;
        score -= bin_pressure * 35.0;
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

