        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 8.0;
        }
        if dead_ratio > 0.12 && dead_ratio < 0.20 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after < cap * 0.06 {
                score -= 3.0 * (1.0 - after / (cap * 0.06));
            }
        }
    }

    // Small alignment bonuses.
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Endgame squeeze: prefer tight bins when the stream is nearly done.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - (post_residual as f64 / cap));
    }
    if stream_left < 0.05 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward filling bins completely (small post_residual strongly favored).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty for fragmenting residual.
            score += 5.0;
        }
    }

    // New-bin candidate handling: opening a new bin wastes capacity; penalize it
    // unless existing residuals are all poor fits for the item.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // If few bins fit the item, opening a new bin is less bad.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.5 * mean_residual;
    }

    // Prefer bins with residual below the mean (tighter bins get priority),
    // encouraging consolidation of small residual space.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Slight preference for using more-open bins state: avoid bin explosion.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
