pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth progress coupling: later in stream, penalize residuals more (less time to fill them)
    score += 30.0 * progress * pr_norm * pr_norm;

    // Reward tight fits with smooth exponential-ish term
    score -= 25.0 * (-pr_norm * 4.0) * (1.0 + progress);

    // Last-chance bin bonus: strongly favor when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Penalize opening new bins when many open bins exist and mean residual is high
    score += 8.0 * (open_bins_count as f64).sqrt() * (mean_residual / cap);

    // Lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = pr - n;
        if gap >= 0.0 {
            score -= 12.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Mild penalty for near-full waste (dead space) via cubic term
    score += 15.0 * pr_norm * pr_norm * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "nice" classes (multiples of 10 / small values) are more reusable.
    let pr = post_residual;
    let class_mod = (pr % 10) as f64;
    score += class_mod * 0.8; // penalize off-class leftovers (dead space)

    // Integer-division threshold classes on post_residual
    if pr == 0 {
        score -= 30.0; // perfect fit is ideal
    } else if pr < 10 {
        score -= 12.0; // tiny leftover, nearly perfect
    } else if pr < 20 {
        score += 4.0; // awkward class: few item sizes (1..100) fit later
    } else if pr < 35 {
        score -= 3.0; // decent class
    } else if pr < 50 {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: next item class aligns with leftover
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 + slack * 0.05;
            if (next_item_size % 10) == (pr % 10) {
                score -= 3.0; // same harmonic subclass
            }
        } else {
            score += 6.0; // leftover too small for lookahead item
            // if leftover < smallest plausible item, it's dead space
            if pr < 10 {
                score += 8.0;
            }
        }
    } else {
        // last item: prefer filling as tightly as possible
        score -= pr as f64 * 0.5;
    }

    // Last-chance bin: strongly reward using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when no open bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // big items prefer a fresh bin to avoid fragmentation
        if item_size > 50 {
            score -= 10.0 + 10.0 * progress;
        } else {
            score += 6.0 + mean_residual * 0.05; // prefer existing bins otherwise
        }
        // if many bins already fit the item, discourage opening another
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        // near end of stream, avoid opening bins
        if progress > 0.9 {
            score += 12.0;
        }
    }

    // Spread penalty: bins far from mean residual are less predictable
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for tighter existing bins
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=12) are nearly useless -> heavy penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 - (post_residual as f64) / 12.0);
    }
    // Mid-range dead space (13..=25) mildly wasteful.
    if post_residual > 12 && post_residual <= 25 {
        score += 8.0;
    }

    // Reward exact and near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Reward leaving room for the lookahead item if it can fit in the gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // gap too small for next item: dead space likely
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: mildly discourage opening new bins when few exist,
    // but allow opening when many bins are open and fragmented.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        } else {
            let pressure = 20.0 + 2.0 * (open_bins_count as f64).ln();
            score += pressure;
            // Opening a new bin is attractive if current bin fit is poor.
            if post_residual <= 12 { score -= 30.0; }
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (tight bins) when filling, but avoid over-fragmenting.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Progress term: as the stream advances, tighten packing discipline.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
