            } else if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0;
            } else if gap <= 20.0 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        } else if bin_residual >= next_item_size {
            score += 30.0;
        }
