    if stream_left < 0.05 && post_residual >= next_item_size && next_item_size > 0 {
        score -= 2.0;
    }
    if stream_left < 0.10 && post_residual > 0 && (post_residual as f64) < cap * 0.08 {
        score -= 5.0 * (0.10 - stream_left) / 0.10;
    }

    score
}

