pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: item now + next item perfectly fills bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Partial lookahead credit: next item fits into resulting residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        // Tighter fit after the pair is placed is better.
        score -= 0.5 * (next_item_size as f64) + 0.3 * ((post_residual - next_item_size) as f64);
    }
    // Penalize dead space: residual left that the next item cannot use.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 0.4 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it moderately attractive only via its raw residual,
    // but discourage abandoning open bins unless their fit is very poor.
    if bin_residual == bin_capacity {
        score += 10.0;
        // In late stream, opening new bins is relatively cheaper.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.5 {
            score -= 5.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit style).
    score += 0.2 * ((bin_residual as f64) - mean_residual);

    score
}

