pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base preference: tight fits (small post_residual) are good.
    // Penalize dead space quadratically when it can't hold the next item.
    let dead = post_residual as f64;
    let next_fits = next_item_size > 0 && (post_residual as u32) >= next_item_size;
    if !next_fits && next_item_size > 0 {
        score += dead * dead / (bin_capacity as f64);
    }

    // Best-fit style: reward small absolute slack relative to capacity
    score -= 0.5 * (bin_capacity as f64 - dead);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count == 1 {
        // new bin is the only option; neutral
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin. Prefer opening a new bin only when
    // the item would leave a large awkward hole in an existing bin, or when
    // mean residual across open bins is already fragmented.
    if bin_residual == bin_capacity {
        let awkwardness = if mean_residual > 0.0 {
            (mean_residual - item_size as f64).abs()
        } else { 0.0 };
        // Early in stream: opening new bins is cheap-ish; late: avoid it.
        score += 45.0 - 35.0 * progress;
        score += 0.3 * awkwardness;
        // If item is large, new bin keeps big residual for future big items
        score -= 0.2 * item_size as f64;
        // If next item is large and current item is large, fresh bin is good
        if next_item_size >= item_size && item_size >= 50 {
            score -= 25.0;
        }
        // Many open bins with high mean residual: don't fragment further
        score += 0.05 * open_bins_count as f64 + 0.05 * mean_residual;
    } else {
        // Placing into an existing bin: reward consolidation when bins are many
        score -= 0.05 * open_bins_count as f64;
        // Reward using bins whose residual is close to the item (good pairing)
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * tightness;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: prefer tight fits, with non-linear penalty on residuals
    let mut score = r * (1.0 + 0.5 * norm_r * norm_r);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, be stricter about wasted space
    let progress_coupling = 1.0 + 2.0 * t * t * (1.0 - t);
    score *= progress_coupling;

    // Reward bins that leave room for the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (n - r).abs();
        score -= 6.0 * (-gap / 30.0) * (1.0 - t);
        // smooth penalty if post_residual can't fit next item
        let fit_next = (r >= n) as i32 as f64;
        score -= 4.0 * fit_next * (1.0 - t * t);
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + 0.5 * t);
    }

    // Crowd pressure: many open bins -> prefer filling existing ones
    let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score -= 3.0 * crowd * (1.0 - norm_r);

    // New-bin candidate: penalize opening a new bin unless current residual is truly bad
    if bin_residual == bin_capacity {
        // smooth threshold: opening a bin is penalized by how good other fits would be
        score = cap * (1.2 + 0.3 * t) - 8.0 * (mean_residual / cap).max(0.0);
    }

    // Mild tie-breaker on mean residual alignment
    score += 0.05 * (mean_residual - r);

