pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: never waste this bin again.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        // Tiny residue is nearly a perfect fit.
        score -= 32.0;
    }

    // Harmonic class of post_residual.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Modulo-10 class of post_residual (divisible residues chain well).
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.4;
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            // Graded reward: tighter leftover after the lookahead fits is better.
            if after < class_width {
                score -= 20.0 + 0.5 * (class_width - after) as f64;
            } else {
                score -= 12.0 + 0.1 * after as f64;
            }
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
            if after <= 3 {
                score -= 12.0;
            } else if after >= 2 * next_item_size {
                // Room for two more lookahead items: strong chained fit.
                score -= 14.0;
            } else if after >= next_item_size {
                score -= 10.0;
            } else if after < next_item_size {
                score += 4.0;
            }
            if after >= 3 && after <= 15 {
                score -= 3.5;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            // Dead space relative to lookahead: penalize proportionally,
            // but less when the gap is tiny (item almost fits).
            score += gap * 0.5;
            if gap <= 8.0 {
                score += 3.0 + 0.5 * (8.0 - gap);
            }
            if post_residual >= 5 && post_residual % 5 == 0 {
                // Round residue may still serve future small items.
                score += 2.0;
            }
        } else if bin_residual >= next_item_size {
            // Fresh bin that could host the lookahead item after this one.
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 42.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins below the mean (tighter bins),
    // but with a gentler slope so post_residual dominates.
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Small-residue dead-space shaping.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    // Scarcity-aware dead-space handling.
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Narrow dead-ratio band: residues just above 5% are poor fits.
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band residue (30-60) is valuable for medium items.
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        // Chained fits: post_residual can host next item twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 10.0;
            }
            if chain >= 2 * next_item_size {
                score -= 6.0;
            }
            if chain > 0 && chain % 10 == 0 {
                score -= 4.0;
            }
        }
        // Almost-fits gap shaping with scarcity weighting.
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
            if gap <= 20.0 && scarcity < 0.5 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }
        // Mid dead-ratio band centered at 0.325: reward proximity to center.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Scarce fits with a large residue that can still host the next item.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // After-fit residue in a good band with low dead ratio.
        if dead_ratio > 0.10 && dead_ratio < 0.18 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
        }
    }

    // Endgame: squeeze remaining space harder near the stream's tail.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }
    if stream_left < 0.05 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // coarse buckets via integer division (dead-space quality classes).
    let class = post_residual / 10; // 0..10 harmonic class
    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Small leftovers (0..10) are near-perfect; reward strongly.
    if class == 0 && post_residual > 0 {
        score -= 40.0;
    }
    // Residuals in the 10..30 band are semi-usable for small items; mild reward.
    if class >= 1 && class <= 2 {
        score -= 10.0;
    }
    // Mid-band leftovers (30..60) can host medium items; slight reward.
    if class >= 3 && class <= 5 {
        score -= 5.0;
    }
    // Large leftovers (>=60) mean we barely used the bin; penalize.
    if class >= 6 {
        score += 8.0 * (class as f64 - 5.0);
    }

    // Lookahead coupling: does the leftover match the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly or snugly here -> big reward.
            let snug = (post_residual - next_item_size) as f64;
            if snug <= 5.0 {
                score -= 60.0;
            } else {
                score -= 20.0 * (1.0 - snug / 100.0);
            }
        } else {
            // Next item will NOT fit here -> this leftover is dead space.
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well. Penalize the empty-bin call mildly so it is
    // chosen only when all open bins score badly.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if many bins are already open, consolidation pressure favors reuse.
        score += 2.0 * open_bins_count as f64;
    }

    // Progress-based tie-breaking: late in the stream, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    // Deviation from mean residual: bins far from the mean are either
    // nearly full (good to finish) or too empty (bad to waste).
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Modulo harmonic penalty: residuals that are awkward multiples
    // (e.g. 7, 13 mod 20) tend to be dead space under typical item sizes.
    let m = post_residual % 20;
    if m == 7 || m == 13 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize the "unusable gap" band heavily.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bin pressure: with many open bins, discourage spreading; opening
    // new bins becomes less attractive as open_bins_count grows.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer using an existing bin unless the fit there is terrible
        // (large dead space or last-resort dynamics already captured).
        score += 15.0;
        // If no existing bin fits well (this call is the only candidate),
        // allow opening a new bin.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it over opening a new bin.
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement (chaining placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item nearly fills the bin afterwards.
        if post_residual - next_item_size < 12 {
            score -= 8.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "small hole" bin — prefer filling it to consolidate.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.5;
    }

    score
}

