        score -= 25.0; // perfect fill is great
    } else if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.6;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
        // If next item would also fit current residual, less urgency to fill perfectly.
        if next_item_size <= bin_residual {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += consolidation * 0.15 * (open_bins_count as f64).ln().max(1.0);
    }

    // Time horizon: early in the stream, prefer keeping bins flexible (larger residuals ok);
    // late in the stream, push for tight packing.
    score *= 1.0 - 0.3 * progress;
    if progress > 0.8 && post_residual <= 15 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0
