pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
    }

    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 48.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after < class_width {
                score -= 20.0 + 0.5 * (class_width - after) as f64;
            } else {
                score -= 12.0 + 0.1 * after as f64;
            }
            if post_residual % next_item_size == 0 {
                score -= 7.0;
            }
            if after <= 3 {
                score -= 13.0;
            } else if after >= 2 * next_item_size {
                score -= 14.0;
            } else if after >= next_item_size {
                score -= 10.0;
            } else if after < next_item_size {
                score += 4.0;
            }
            if after >= 3 && after <= 15 {
                score -= 3.5;
            }
