    score += 10.0 * (pr_norm - 0.25) * (pr_norm - 0.25);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Prefer bins below mean residual (denser bins)
    score += 0.3 * (mean_residual - pr);
    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            score -= 8.0 * (1.0 - (diff / cap).abs());
        } else {
            score += 6.0;
        }
    }
    // Mild penalty for spreading across many bins
    score += 0.5 * open_bins_count as f64 * pr_norm;
    // Encourage filling bins more aggressively later in the stream
    score -= 20.0 * progress * (1.0 - pr_norm);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space (capacity fraction thresholds) ---
    let frac = post_residual as f64 / bin_capacity as f64;

    // Perfect fit: reward heavily
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Dead-space penalty: leftover that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 150.0; // unusable sliver
    }

    // Modulo classes on post_residual: leftovers that pair with common small items
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 40.0; // decade-aligned leftover is reusable
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 15.0;
    }
    // Odd, awkward leftovers get a mild penalty
    if pr % 2 == 1 && pr < 25 {
        score += 10.0;
    }

    // --- Lookahead coupling: does this leftover fit the next item exactly or well? ---
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0; // perfect chain
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            if slack <= 10.0 {
                score -= 80.0; // near-perfect chain
            }
        } else {
            // next item cannot use this leftover: penalize proportionally to wasted potential
            score += 20.0 + frac * 30.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 {
        score -= 200.0; // strongly prefer using the only bin that fits
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits (implicit via post_residual)
        score += 0.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost of one fresh bin.
        score = bin_capacity as f64 * 0.75;
        // Open a new bin when existing bins would be badly fragmented
        if fitting_bins_count > 0 {
            let best_possible = mean_residual - item_size as f64;
            if best_possible < 0.0 || frac > 0.5 {
                score -= 100.0;
            }
        }
        // Early stream: fewer open bins -> opening is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // Don't open a new bin if some open bin fits nearly perfectly
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 && (mean_residual - item_size as f64) < 10.0 {
            score += 250.0;
        }
    }

    // --- Global fragmentation pressure ---
    // When many bins are open, tightening fits matters more
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Prefer bins with residual far from mean (specialize bin sizes)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
