pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible item (1..100) are wasted.
    // Treat post_residual < 10 as pure dead space; amplify it nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Reward bins whose residual is "consumed" proportionally well by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving a gap that exactly fails to fit the lookahead item (k=2):
    // post_residual < next_item_size <= bin_residual means we just broke a future fit.
    if next_item_size > 0 {
        if post_residual < next_item_size && bin_residual >= next_item_size {
            score += 25.0;
        }
        // Reward leaving a gap that still fits the next item.
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another bin
    // (the empty-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = 15.0 + 25.0 * (open_bins_count as f64 / (1.0 + mean_residual / 10.0));
        score += pressure * (0.5 + 0.5 * progress);
        // But allow a new bin if all existing fits would be terrible.
        if post_residual as f64 > mean_residual * 0.9 {
            score -= 20.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate into emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 22.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 120.0;
        }
    } else if post_residual <= bin_capacity / 5 {
        score += 20.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 6.0;
    } else {
        score -= 14.0;
    }

    // Exact lookahead match: post residual equals next item => perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0;
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0;
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
                score -= 12.0 + 0.15 * (pr - nxt);
            }
            if after >= nxt {
                score -= 8.0;
                if after >= 2.0 * nxt {
                    score -= 6.0;
                }
            }
            if pr % nxt.max(1.0) == 0.0 && nxt <= pr {
                score -= 5.0;
            }
            // Chain leaves residual absorbable by average open bin.
            if after > 0.0 && after <= mean_residual.max(1.0) {
                score -= 3.0;
            }
        } else {
            let gap = nxt - pr;
            if gap <= 8.0 {
                score += 60.0 + 6.0 * (8.0 - gap);
            } else {
                score += 25.0 * (1.0 - pr / nxt.max(1.0));
            }
        }
    }

    // Relative-to-mean: prefer tighter-than-average bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance: only fitting bin -> keep item out of a new bin.
    if fitting_bins_count == 1 {
        score -= 160.0;
    } else if fitting_bins_count == 0 {
        score += 80.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_cap = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                && mean_residual < next_item_size as f64 * 1.15
                && (fitting_bins_count as f64) < 4.0)
                || (total_fit_cap < next_item_size as f64 * 2.0
                    && fitting_bins_count <= 1));
        if big_item || crowded || next_needs_fresh {
            score -= 60.0;
        } else {
            score += 70.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            // Late-stream: open fresh bins eagerly when leftovers are tiny.
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Consolidation pressure early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mid-band residual (30..60) tends to pack well with typical sizes.
    if post_residual >= 30 && post_residual <= 60 {
        let remaining = (total_items - step_index) as f64;
        let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
        score -= 5.0 + 3.0 * stream_left;
    }

    // Dead-space shaping.
    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
