        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If many bins already open, discourage another unless item is huge.
        score += 0.5 * open_bins_count as f64;
        if item_size > bin_capacity * 3 / 4 {
            score -= 12.0;
        }
    }

    // Slight preference to fill bins with many existing contents (fewer open bins kept).
    score += 0.05 * open_bins_count as f64;

    score
}

