pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: shrink score when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.6 * tightness * (bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // Partial reward proportional to how well next item uses the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
        } else {
            // Penalize dead space that the next item cannot use.
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: this is the only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when decent open bins exist:
    // for the empty-bin candidate, add a penalty that grows with open bins count
    // and shrinks with stream progress (late stream: consolidation matters more).
    if bin_residual == bin_capacity {
        let open_penalty = 10.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
        score += open_penalty * (1.0 - 0.5 * progress);
    } else {
        // Favor bins whose residual is close to the mean (balance load across bins)
        // mildly, so no bin is left as an extreme outlier.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference early in the stream to spread items (keeps options open),
    // late in the stream to pack tightly.
    score += (1.0 - progress) * 2.0;

    score
}

