    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / bin_capacity as f64;
        let slack = norm_post - next_norm;
        if slack < 0.0 {
            score += 6.0 * slack.abs() * (1.0 - progress);
        } else {
            score -= 3.0 * slack * (1.0 - slack.abs());
        }
