        // modulo-10 banding: residuals near multiples of 10 are friendlier
        let m = r % 10;
        harmony_bonus -= (5 - m.max(10 - m)) as f64 * 0.8;
    }
    score += harmony_bonus;

    // Capacity fraction coupling: penalize wasting large fractions of the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 35.0;
        } else if next_item_size < r {
            let nm = r % next_item_size;
            score -= (1.0 - nm as f64 / r.max(1) as f64) * 12.0;
        } else {
            // next item cannot use this bin's leftover: slight penalty
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // prefer tighter bins among many candidates
        score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Late in stream: consolidation matters more; reward closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (r == 0) as i32 as f64 * 20.0;
    score += progress * 3.0;

    // Many open bins: encourage filling existing ones rather than opening new.
    score += open_bins_count as f64 * 0.5;
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when current item leaves bad residuals everywhere.
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin; offset by how bad typical fits would be
        score = 60.0 - fill_frac * 10.0 - (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if next_item_size > 0 && next_item_size >= bin_capacity * 9 / 10 {
            score -= 25.0; // large next item benefits from fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 120.0;
        }
    }
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 20.0;
    } else {
        score -= 14.0;
    }

