        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min size 1..100, but small gaps < ~20 are
    // practically dead) are heavily penalized super-linearly.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 20.0 {
        score += (20.0 - gap) * 6.0;
    }
    // Mid-range gaps (20..40) are mildly penalized: only useful for
    // small items, which are rarer than mid-size ones in most streams.
    if gap >= 20.0 && gap < 40.0 {
        score += (40.0 - gap) * 1.2;
    }

    // Reward near-perfect fits (very small gap) with a bonus.
    if gap <= 5.0 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage scattering items across many bins
    // when the residual is far above mean; encourage filling bins that
    // are already below-average residual (i.e., nearly full bins).
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += pressure * 1.5;

    // Favor bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post-residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size as f64 == gap {
        score -= 25.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when mean residual is small relative to the item or there
    // are no fitting bins beyond this one.
    if bin_residual == bin_capacity {
        let no_good_fit = mean_residual < item_size as f64 * 0.6
            || fitting_bins_count == 0;
        if no_good_fit {
            score -= 10.0;
        } else {
            score += 25.0 + open_bins_count as f64 * 0.0;
        }
    }

    score
}

