    let mut score = post_residual as f64;

    // Perfect 2-step fit: post residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item also fits after this placement: strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64 / bin_capacity as f64) * 20.0;
    } else if next_item_size > 0 {
