    // Many open bins: discourage spreading across too many bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 20.0;
        // If this is the only fitting option (no alternatives), opening a new bin is fine.
        if fitting_bins_count == 1 {
            new_bin_penalty = 5.0;
        }
        // If the next item is large and would leave a very tight fit here, prefer new bin.
        if next_item_size > 0 && item_size >= next_item_size {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    score
}

