        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    } else if post_residual <= 30 {
        score -= 10.0;
    } else {
        // Large dead space: penalize proportionally to how far it exceeds
        // the smallest useful item quantum (assume items >= 1, typical > 10).
        score += (frac * 40.0).min(50.0);
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common small item sizes (10, 20, 25, 50) are reusable slots.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 8.0;
    }
