        score += (pr as f64 - mean_residual).max(0.0) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the
    // item is large or the fit in open bins is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 50 {
            score -= 15.0; // large items start fresh bins cheaply
