        if gap > 0.0 {
            score += 0.05 * gap; // this bin is emptier than average -> penalize slightly
        } else {
            score -= 0.05 * (-gap); // fuller-than-average bin: prefer it
        }
    }

    // Time-horizon modulation: early on, tolerate looser fits to build
    // flexible bins; later, be strict about tightness.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.03 * post_residual as f64;

    // Small noise-free tiebreak by bin index proxy: prefer fewer open bins
    // implicitly via slight reward when open_bins_count is high.
    score -= 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 120.0;
        }
    } else if post_residual <= bin_capacity / 5 {
        score += 20.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 6.0;
    } else {
        score -= 18.0;
    }

    // Exact lookahead match: post residual equals next item => perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0;
            } else if after < class_width as f64 {
                score -= 20.0 + 0.5 * (class_width as f64 - after);
            } else {
                score -= 12.0 + 0.1 * after;
            }
            if after >= nxt {
                score -= 8.0;
                if after >= 2.0 * nxt {
                    score -= 6.0;
                }
            }
            if pr % nxt.max(1.0) == 0.0 && nxt <= pr {
                score -= 7.0;
            }
            if after > 0.0 && after <= 3.0 {
                score -= 13.0;
            }
            // Chain leaves residual absorbable by average open bin.
            if after > 0.0 && after <= mean_residual.max(1.0) {
                score -= 3.0;
            }
            if after >= 3.0 && after <= 15.0 {
                score -= 3.5;
            }
        } else {
            let gap = nxt - pr;
            if gap <= 8.0 {
                score += 60.0 + 6.0 * (8.0 - gap);
            } else {
                score += 25.0 * (1.0 - pr / nxt.max(1.0));
            }
        }
    }

    // Relative-to-mean: prefer tighter-than-average bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance: only fitting bin -> keep item out of a new bin.
    if fitting_bins_count == 1 {
        score -= 160.0;
    } else if fitting_bins_count == 0 {
        score += 80.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_cap = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                && mean_residual < next_item_size as f64 * 1.15
                && (fitting_bins_count as f64) < 4.0)
                || (total_fit_cap < next_item_size as f64 * 2.0
                    && fitting_bins_count <= 1));
        if big_item || crowded || next_needs_fresh {
            score -= 50.0;
        } else {
            score += 70.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            // Late-stream: open fresh bins eagerly when leftovers are tiny.
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 28.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Consolidation pressure early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mid-band residual (30..60) tends to pack well with typical sizes.
    if post_residual >= 30 && post_residual <= 60 {
        let remaining = (total_items - step_index) as f64;
        let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
        score -= 4.0 + 3.0 * stream_left;
    }

    // Dead-space shaping.
    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Sharp penalty for the 5..12% sliver band (hardest to fill later).
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band (20..45%) attraction toward center when next item can't fill it.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Chain into small residual in the 10..18% band.
        if dead_ratio > 0.10 && dead_ratio < 0.18 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
        }
        // Mid-range dead space early in stream: penalize mildly.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
        // Tiny residual left after chaining next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
        }
        // Large leftover after chain: strong reward (best-heuristic idea).
        if next_item_size > 0 && post_residual > next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
        }
        // Deep residual with few fitting bins: keep flexible space alive.
        if dead_ratio > 0.48 && fitting_bins_count <= 2 && next_item_size as f64 > post_residual as f64 {
            score += 3.0 * (dead_ratio - 0.48) * 20.0;
        }
        // Divisibility bonus scaled by fullness.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        // Small dead space with many fitting bins: penalize wasting good bins.
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        // Decile-granular residual after chain.
        let after2 = if next_item_size > 0 && post_residual >= next_item_size { (post_residual - next_item_size) as f64 } else { -1.0 };
        if after2 >= 0.0 && after2 < cap * 0.5 {
            let frac = after2 / cap;
            if (frac * 10.0).round() as i32 <= 1 {
                score -= 2.0 * (1.0 - frac * 10.0) * (1.0 - scarcity);
            }
        }
        // Next item barely misses: discourage near-miss placements when alternatives exist.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: aggressive waste penalty (favor tight fills); Late: keep residual flexible.
    let waste_weight = 3.0 - 2.0 * progress;
    score += waste_weight * (pr / cap).powi(2) * cap * 0.5;

    // Reward near-perfect fits more strongly as stream progresses.
    let tightness = 1.0 - (pr / cap);
    score -= tightness.powi(3) * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly encourage using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 4.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize mildly so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress) + 0.02 * open_bins_count as f64;
    }

    // Lookahead: penalize leaving a residual that exactly strands the next item,
    // reward residuals that can still host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni && pr > 0.0 {
            score += 1.5 + ni * 0.02; // stranded dead space
        } else if pr >= ni {
            score -= 1.0 * (pr - ni) / cap;
        }
    }

    // Coupling with mean residual: bins far from the mean are slightly demoted.
    score += ((pr - mean_residual) / cap).abs() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space is worse when it falls
    // into "unusable" modulo classes relative to typical item sizes.
    let pr = post_residual;
    if pr > 0 {
        // Waste classes: residuals that no item in [1,100] can pair nicely with.
        let class = pr % 10;
        match class {
            0 => score -= 8.0,            // perfectly aligned residual
            1 | 2 | 3 => score += 2.5,    // awkward slivers
            4 | 5 | 6 => score += 0.5,    // medium
            _ => score -= 1.0,            // 7,8,9 pair often
        }
        // Integer-division thresholds: penalize residuals too small for any
        // plausible next item (dead space).
        if pr < 10 {
            score += 12.0; // dead space below minimum item size
        } else if pr < 20 {
            score += 4.0;
        }
    } else {
        score -= 15.0; // perfect fill
    }

    // Lookahead coupling: reward residuals that can host the next item exactly
    // or leave it in a good harmonic class.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // exact next fit
        } else if next_item_size < pr {
            let nxt_post = pr - next_item_size;
            if nxt_post % 10 == 0 { score -= 6.0; }
            if nxt_post < 10 { score += 3.0; }
        } else {
            score += 5.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: score it as a moderate default so it only wins when
    // all open fits are poor (their scores inflated by dead-space penalties).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75 + 15.0;
        // Slightly cheaper to open new bins late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
        // If next item is huge, a fresh bin is attractive.
        if next_item_size > 60 { score -= 10.0; }
        return score;
    }

    // Tightness reward: the fuller the bin relative to capacity, the better.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Discourage spreading when many bins are open and residual is far above mean.
    if (post_residual as f64) > mean_residual + 20.0 {
        score += 3.0;
    }

    score
}

