pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits here afterwards: reward tightness of the chain
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item would NOT fit after this placement: penalize relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 30.0 * (gap / 100.0).min(1.0);
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers of dead space
    if post_residual as f64 > mean_residual {
        score += 0.8 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (step_index as f64 / total_items.max(1) as f64).max(0.1);
        score += 150.0 + 2.0 * pressure;
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Mild preference for tighter bins generally
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
