pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // dead space relative to next item's need
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        } else {
            // bonus if bin can still host the next item (keeps chains alive)
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize spreading across many open bins; encourage consolidation
    score += 0.6 * open_bins_count as f64;

    // Encourage filling bins whose residual is below the mean (waste recovery)
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.4 * (mean_residual - res);
    } else {
        score += 0.25 * (res - mean_residual);
    }

    // Time horizon: early on, be flexible; late, pack greedily
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate handling: only open a new bin when no open bin fits well
    if bin_residual == bin_capacity {
        let new_bin_cost = bin_capacity as f64 - item_size as f64;
        let poor_fit_penalty = if post_residual > 0 && post_residual < 10 {
            0.0 // perfect-ish fill of fresh bin
        } else {
            30.0
        };
        score = new_bin_cost + poor_fit_penalty + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer filling bins aggressively (waste tolerated late).
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = post * (0.35 * p2 + 0.55 * p3) - post * (0.45 * progress * (1.0 - progress) * 4.0);
    score += coupling;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Penalize dead space: post_residual too small to ever be useful.
    let min_useful = 10.0f64.min(cap * 0.1);
    if post < min_useful && post > 0.0 {
        score += (min_useful - post) * (2.0 + 3.0 * p2);
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let gap = post - next;
            score -= 10.0 * (1.0 - gap / cap) * (1.0 + 0.5 * progress);
        } else {
            score += 1.5 * ((next - post) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more when many open bins exist
    // and mean residual is high (existing bins are roomy enough).
    if bin_residual == bin_capacity {
        let roominess = (mean_residual / cap).clamp(0.0, 1.0);
        let crowd = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        score += 8.0 + 10.0 * roominess * crowd * (1.0 - 0.5 * p3);
    } else {
        // Prefer bins with residual close to item (best-fit flavor), smoothly.
        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 4.0 * fit_gap * fit_gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: never waste this bin again.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
    }

    // Harmonic class of post_residual.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Modulo-10 class of post_residual.
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.4;

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 48.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after < class_width {
                score -= 20.0 + 0.5 * (class_width - after) as f64;
            } else {
                score -= 12.0 + 0.1 * after as f64;
            }
            if post_residual % next_item_size == 0 {
                score -= 7.0;
            }
            if after <= 3 {
                score -= 13.0;
            } else if after >= 2 * next_item_size {
                score -= 14.0;
            } else if after >= next_item_size {
                score -= 10.0;
            } else if after < next_item_size {
                score += 4.0;
            }
            if after >= 3 && after <= 15 {
                score -= 3.5;
            }
            // Reward when leftover after this fit could be absorbed by open bins' mean residual.
            if after > 0 && (after as f64) <= mean_residual.max(1.0) {
                score -= 2.5;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if gap <= 8.0 {
                score += 3.0 + 0.5 * (8.0 - gap);
            }
            if post_residual >= 5 && post_residual % 5 == 0 {
                score += 2.0;
            }
        } else if bin_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 44.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            // Open a fresh bin more eagerly late in the stream when open bins are mostly small leftovers.
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer bins below the mean (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Small-residue dead-space shaping.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    // Scarcity-aware dead-space handling.
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band residue (30-60) is valuable for medium items.
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        // Chained fits.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 10.0;
            }
            if chain >= 2 * next_item_size {
                score -= 6.0;
            }
            if chain > 0 && chain % 10 == 0 {
                score -= 4.0;
            }
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
            if gap <= 20.0 && scarcity < 0.5 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }
        // Band-centered residue attraction around 0.325*cap.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        if dead_ratio > 0.10 && dead_ratio < 0.18 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
        }
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 4.0 * (0.08 - dead_ratio) * 100.0 * 0.5;
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
        }
        if dead_ratio > 0.48 && fitting_bins_count <= 2 && next_item_size as f64 > post_residual as f64 {
            score += 3.0 * (dead_ratio - 0.48) * 20.0;
        }
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        // Second-order lookahead: favor post-fit residuals in the lowest decile band.
        let after2 = if post_residual >= next_item_size { (post_residual - next_item_size) as f64 } else { -1.0 };
        if after2 >= 0.0 && after2 < cap * 0.5 {
            let frac = after2 / cap;
            if (frac * 10.0).round() as i32 <= 1 {
                score -= 2.0 * (1.0 - frac * 10.0) * (1.0 - scarcity);
            }
        }
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
        // Mild penalty for mid-range dead space when much of the stream remains.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
    }

    // Endgame: squeeze the last open bins hard.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-4 arithmetic on integer division thresholds
    let hclass = (post_residual / 10) % 4; // harmonic decade class: 0..3
    // Class 0 (post_residual in {0..9,40..49,80..99}) is bad dead space; penalize
    match hclass {
        0 => score += 18.0,
        2 => score -= 6.0,
        _ => {}
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // unusable dead space for items >= 10, but small items may exist
        score -= 25.0 * (post_residual as f64 / 10.0);
    }

    // Capacity fraction coupling: reward leaving residual near friendly fractions
    let frac = post_residual as f64 / cap_f;
    score -= 12.0 * (frac * std::f64::consts::PI).cos(); // favors frac ~ 0, 1, 0.5

    // Lookahead harmony: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact or harmonic fit of lookahead
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 45.0;
            } else if gap < 10 {
                score -= 20.0;
            } else {
                score -= 8.0 * (1.0 - gap as f64 / cap_f);
            }
        } else {
            // next item cannot use this residual; penalize proportionally
            score += 10.0 * (next_item_size - post_residual) as f64 / cap_f;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: prefer fuller bins when many bins are open
    let fill = 1.0 - bin_residual as f64 / cap_f;
    score -= 15.0 * fill * (open_bins_count as f64).ln().max(1.0);

    // Prefer bins whose residual is below mean residual (tighter bins)
    score += 6.0 * ((bin_residual as f64 - mean_residual) / cap_f);

    // Late-stream consolidation: as stream progresses, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost, discounted early, penalized late
        score = cap_f * (1.0 - 0.35 * progress) + 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

