pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size = 1, but practically tiny slivers < 4)
    // are pure waste. Penalize them super-linearly.
    if post_residual > 0 && post_residual < 4 {
        score += 40.0 * (4.0 - post_residual as f64);
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.25 * next_item_size as f64;
        } else if post_residual > 0 {
            // Residual too small for the next item: mild dead-space penalty.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones,
    // especially bins with below-average residual (tighter bins first).
    score += 0.35 * open_bins_count as f64;
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate (empty bin): make it unattractive unless the item
    // is large and no bin fits well. New bin residual = capacity - item.
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size > 70 {
            score -= 20.0; // large items deserve a fresh bin
        }
    }

    // Slight progress bias: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

