            score -= 25.0 - 0.4 * post2 as f64;
        } else {
            // Next item cannot use this bin's leftover; mild penalty proportional to gap.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer fullest packing.
