        if post_residual == next_item_size {
            score -= 500.0;
        } else {
            // Penalize gap relative to next item size (normalized mismatch).
            score += gap * (1.0 + next_item_size as f64 / 100.0);
            // Penalize leaving space too small for the next item (dead space).
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 2.0;
            }
        }
    } else {
        // Last item: only the immediate fit matters.
        score = post_residual as f64;
    }

    // Compare against mean residual: prefer bins whose post placement residual
    // is below average (tight packing), penalize above-average leftovers.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it moderately unattractive so it's chosen only
    // when all open bins fit poorly (its post_residual is large, so its base
    // score is already high; add a fixed opening penalty).
    if bin_residual == bin_capacity {
        score += 60.0;
        // A new bin is attractive if the next item could then chain into it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 400.0;
