pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A gap is "dead" if it is smaller than the minimum plausible item size.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_gap = 5.0;
    if (post_residual as f64) < min_gap + 10.0 * (1.0 - progress) {
        score += 40.0 + 30.0 * (1.0 - progress);
    }

    // Non-linear penalty: waste grows quadratically for tiny residuals.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (post_residual small but usable).
    if post_residual >= 1 && post_residual <= 20 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score += pressure * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is bad and bins are few.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 40 { 1.0 } else { 0.0 };
        score += 55.0 - bad_fit * 45.0 - pressure * 2.0;
    }

    // Slight preference for bins with less residual already (tighter bins first).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score += (post_residual as f64) * 0.01;

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leftover dead space penalized proportionally.
            let leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 + leftover * 0.3;
        } else {
            // Dead space: next item cannot use the remainder.
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Compare residual to mean residual across open bins.
    let res = post_residual as f64;
    if res < mean_residual {
        // Below-average residual: tight packing, reward.
        score -= (mean_residual - res) * 0.4;
    } else {
        // Above-average residual: wasteful bin, penalize.
        score += (res - mean_residual) * 0.25;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we prefer using existing bins,
    // unless the fit into open bins is terrible (lookahead terms dominate).
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Early in stream, be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
