        score -= 8.0;
    } else if post < 35.0 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Global state: many open bins with slack -> prefer consolidating into
    // low-residual bins to close them out.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.4 * open_bins_count as f64 * (bin_residual as f64 / cap);

    // Time horizon: early in the stream, be liberal opening bins; late, tighten.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
