        // all residuals; penalize when open bins are plentiful and item is small.
        score = 0.5 * cap - 30.0 * progress - 0.5 * item_size as f64
            + 2.0 * open_bins_count as f64 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        score -= 20.0 * progress * (1.0 - fill);
    }

    score
}

