pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls in
    // "usable" residue classes (multiples of common small item sizes) are favored.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit: strongly reward
    } else if pr % 10 == 0 {
        -12.0 // residue aligned with decimal item classes
    } else if pr % 5 == 0 {
        -6.0
    } else if pr >= 10 {
        -2.0
    } else {
        15.0 // dead space below minimum item size: heavy penalty
    };
    score += harmonic_bonus;

    // Lookahead coupling: reward when next item fits the post-residue exactly
    // or into its harmonic class; penalize when next item is stranded.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 20.0; // sets up a perfect follow-up fit
            } else if slack % 10 == 0 || slack % 5 == 0 {
                score -= 8.0;
            } else if slack < 10 {
                score += 5.0; // creates dead space after next item
            }
        } else {
            // next item won't fit here; mildly prefer larger leftovers
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Integer-division threshold on post_residual: leftovers >= half capacity
    // are "healthy" bins; leftovers in [1, 20) are junk.
    if pr >= bin_capacity / 2 {
        score -= 5.0;
    } else if pr < 20 && pr > 0 {
        score += 10.0;
    }

    // Fraction of capacity consumed by this placement (tight fits rewarded).
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 10.0;

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;

    // New-bin candidate: make the empty bin moderately attractive only when
    // no open bin offers a good harmonic fit (high score elsewhere implies it).
    if bin_residual == bin_capacity {
        score += 8.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
    }

