            score -= 60.0 * (1.0 - gap / 100.0);
            // Extra bonus for exact chain (post_residual == next_item_size)
            if gap < 0.5 {
                score -= 40.0;
            }
        } else {
            // Next item cannot follow: penalize dead space left behind.
            score += 0.5 * (nxt - post);
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far above the mean are
    // "roomy"; placing here wastes potential. Prefer bins below/at mean residual.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance logic: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity (poor fit elsewhere is likely).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Penalize new bins moderately; discount when item is large or stream
        // is early (more future items justify a fresh bin).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 30.0 * tightness - 15.0 * (1.0 - progress);
        // If next item is also large, a fresh bin can host both eventually.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

