pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is a multiple of a
    // "nice" quantum (e.g. 10) pair well with typical item sizes.
    let quantum = 10u32;
    let class = post_residual % quantum;
    let class_penalty = match class {
        0 => -6.0,          // perfectly aligned leftover
        5 => -3.0,          // half-quantum, still useful
        _ => (class as f64) * 0.4, // ragged leftovers penalized
    };
    score += class_penalty;

    // Integer-division thresholds: leftover >= 50 keeps a half-bin usable.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual >= half {
        score -= 5.0;
    } else if post_residual >= quarter {
        score -= 1.5;
    } else {
        // Dead space: small leftover with a big next item is waste.
        if next_item_size > post_residual && next_item_size > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Capacity-fraction coupling: item size relative to capacity.
    let frac = item_size as f64 / cap;
    if frac > 0.6 {
        score -= 4.0; // big items should go in now, prefer filling bins
    } else if frac < 0.2 {
        score += 2.0; // tiny items can wait, don't waste a good bin
    }

    // Lookahead: if next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mean residual context: if this bin is far below mean, it's the "worst" bin;
    // filling the emptiest bin first is good.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make empty bins attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * 0.5 + mean_residual / cap * 3.0;
        score += 12.0 - crowded;
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    }

    // Slight preference to keep number of open bins low.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

