pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 partition
    // dead-space quality. Residues near 0 (perfect fits) are rewarded,
    // residues in the awkward middle band (3..=7) are penalized.
    let residue_class = (post_residual % 10) as f64;
    score += 2.0 * residue_class * (1.0 - residue_class / 10.0) - 1.0;

    // Integer-division thresholds on post_residual: bins whose remaining
    // space falls into small quantiles are "sealed" bins — good, reward.
    let quantile = post_residual / 25; // 0..4 coarse class
    score -= match quantile {
        0 => 6.0,          // nearly full: excellent
        1 => 2.0,
        2 => 0.0,
        _ => -1.0,         // wide-open bins less urgent
    };

    // Capacity-fraction coupling: reward filling a large fraction of the bin.
    let fill_frac = item_size as f64 / cap;
    score -= 8.0 * fill_frac * fill_frac;

    // Next-item harmony: if next_item_size exactly divides or matches the
    // post_residual, this bin sets up a perfect follow-up placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 9.0;
        } else if next_item_size <= post_residual {
            // Harmonic compatibility: next item fits with small leftover.
            let nxt_left = (post_residual % next_item_size) as f64;
            score -= 4.0 * (1.0 - nxt_left / post_residual.max(1) as f64);
        } else {
            // Next item cannot use this bin's leftover: mild penalty if
            // leftover is small (dead space), reward if it is reusable later.
            if post_residual < 10 {
                score += 3.0;
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make the empty bin attractive only when the item
    // is large or no good fit exists; otherwise keep it mildly unattractive.
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * fill_frac;
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 3.0; // pairing potential in fresh bin
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - fill_frac);

    // Mean-residual coupling: when mean residual is low, avoid leaving
    // scattered small residuals; prefer bins that close cleanly.
    if (post_residual as f64) < mean_residual {
        score += 0.5 * (mean_residual - post_residual as f64) / cap;
    } else {
        score -= 0.5 * (post_residual as f64 - mean_residual) / cap;
    }

    // Penalize opening new bins when many bins are open and item is small.
    if bin_residual == bin_capacity && item_size < 30 && open_bins_count > 2 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: never waste this bin again.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
    }

    // Harmonic class of post_residual.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Modulo-10 class of post_residual.
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.4;

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 48.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after < class_width {
                score -= 20.0 + 0.5 * (class_width - after) as f64;
            } else {
                score -= 12.0 + 0.1 * after as f64;
            }
            if post_residual % next_item_size == 0 {
                score -= 7.0;
            }
            if after <= 3 {
                score -= 13.0;
            } else if after >= 2 * next_item_size {
                score -= 14.0;
            } else if after >= next_item_size {
                score -= 10.0;
            } else {
                score += 4.0;
            }
            if after >= 3 && after <= 15 {
                score -= 3.5;
            }
            // Reward when the leftover after placement could be absorbed elsewhere.
            if after > 0 && (after as f64) <= mean_residual.max(1.0) {
                score -= 2.5;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if gap <= 8.0 {
                score += 3.0 + 0.5 * (8.0 - gap);
            }
        } else if bin_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 44.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            // Open fresh bins more eagerly late in the stream when open bins hold tiny leftovers.
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins below the mean.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Small-residue dead-space shaping.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    // Scarcity-aware dead-space handling.
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band residue is valuable for medium items.
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        // Chained fits.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 10.0;
            }
            if chain >= 2 * next_item_size {
                score -= 6.0;
            }
            if chain > 0 && chain % 10 == 0 {
                score -= 4.0;
            }
        }
        // Penalize near-misses of the lookahead item when bins are scarce.
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
        }
        // Mid dead-band shaping toward a 32.5% residue target.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Reward leaving a tiny residue after placing the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
        }
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 4.0 * (0.08 - dead_ratio) * 100.0 * 0.5;
        }
        // Extra reward when post_residual is an exact multiple of next_item_size.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
    }

    // Endgame: squeeze the last bins hard.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // perfect fill, ideal
    }
    // Dead space: post_residual too small for the next item (or any typical item)
    let unusable = if next_item_size > 0 {
        post_residual < next_item_size
    } else {
        post_residual > 0 && post_residual < 10
    };
    if unusable {
        // Penalize proportionally to how close we were to a perfect fit (wasted capacity)
        score += 40.0 + 0.5 * post_residual as f64;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 15.0 * tightness;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new one is less costly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * (1.0 - progress));
    score += 8.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when the item leaves a large,
    // likely-usable residual there and existing bins would create dead space.
    if bin_residual == bin_capacity {
        let fresh_residual = bin_capacity - item_size;
        if unusable {
            score -= 30.0; // opening fresh bin beats creating dead space
        } else {
            score += 20.0 + 0.3 * fresh_residual as f64 * pressure;
        }
        // Lookahead: fresh bin is great if next item fits its residual
        if next_item_size > 0 && fresh_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight preference for bins below mean residual (balancing usable space)
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

