        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Reward residual large enough to still be flexible
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Last item: just minimize waste
        score += 0.0;
    }

    // Dead-space penalty: tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins already below-average residual (tighter bins)
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening cost grows as stream progresses (fewer future items to amortize)
        let mut new_bin_score = 60.0 + 40.0 * progress;
        // If next item could exactly fill this fresh bin alongside current item, opening is great
        if next_item_size > 0 && (bin_capacity as u32).saturating_sub(item_size) >= next_item_size {
            new_bin_score -= 45.0;
        }
        // With many open bins, prefer packing into existing ones
        new_bin_score += 2.0 * open_bins_count as f64;
        score = score.min(new_bin_score * 0.0 + new_bin_score) - score * 0.0 + new_bin_score - new_bin_score;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (waste minimization), superlinear in residual.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer filling it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize new-bin candidates mildly; allow them only when fits are poor.
    if bin_residual == bin_capacity {
        let tightness = if fitting_bins_count > 0 {
            (post_residual as f64) // for new bin this is capacity - item
        } else {
            0.0
        };
        let _ = tightness;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening new bins is more acceptable late in the stream when residuals are fragmented.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let new_bin_penalty = 35.0 + 45.0 * (1.0 - progress) - 25.0 * fragmentation;
        score += new_bin_penalty;
    }

    // Lookahead: if next item could exactly use the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 50.0; // chains a perfect second fit
            } else {
                score += slack as f64 * 0.3; // mild penalty for leaving lookahead-unfriendly space
            }
        } else {
            // Next item won't fit here anyway; small bonus for using this bin now.
            score -= 5.0;
        }
    }

    // Prefer bins with residual below mean (consolidate small leftovers).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.4;
    } else {
        score += (resid_f - mean_residual) * 0.2;
    }

    // Mild pressure to close out bins when many are open.
    score += open_bins_count as f64 * 0.15;

    score
