    // Mild penalty when many bins are open and residual is large (fragmentation).
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 6.0 * open_norm * norm_pr * norm_pr;

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere; smooth in progress and item size.
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - norm_item) * (1.0 - 0.5 * progress);
