        if next_item_size > 0 && post_residual > next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
        }
        if dead_ratio > 0.48 && fitting_bins_count <= 2 && next_item_size as f64 > post_residual as f64 {
            score += 3.0 * (dead_ratio - 0.48) * 20.0;
        }
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size && post_residual > 0 {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        let after2 = if next_item_size > 0 && post_residual >= next_item_size { (post_residual - next_item_size) as f64 } else { -1.0 };
        if after2 >= 0.0 && after2 < cap * 0.5 {
            let frac = after2 / cap;
            if (frac * 10.0).round() as i32 <= 1 {
                score -= 2.0 * (1.0 - frac * 10.0) * (1.0 - scarcity);
            }
        }
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
        // mild penalty for mid-range dead space when much of the stream remains
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
    }

    // Endgame: squeeze leftover space hard.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1): later on, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized fill quality: reward bins that end up well-filled.
    let fill_ratio = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large dead space, more so late in the stream.
    score += (post_residual as f64 / bin_capacity as f64) * (20.0 + 40.0 * progress);

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize small leftover slivers.
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * progress;
        }
    } else {
        // Last item: prefer minimal leftover.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Prefer using bins whose residual is already small (consolidate fragments).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Mild preference for reusing existing bins over opening new ones.
    if bin_residual < bin_capacity {
        score -= 5.0;
    } else {
        // New-bin candidate: only attractive when many items are still coming
        // and open bins are nearly full on average.
        let pressure = mean_residual / bin_capacity as f64;
        score += 12.0 * (1.0 - pressure);
        score -= 6.0 * progress;
    }

    // Penalize scattering across many open bins early on.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

