    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 0.4 * (nxt / cap) * (1.0 - norm_pr);
        } else {
            score += 0.25 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 0.8;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.02 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins near/below average residual usage
    let mean_norm = mean_residual / cap;
    score += 0.2 * (norm_pr - mean_norm).abs();

    // New-bin candidate: keep it neutral-to-slightly-high unless residual is tiny
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by 10 are "harmonic"
    // (usable by the widest range of future item sizes).
    let class = if post_residual == 0 { 0 } else if post_residual % 10 == 0 { 1 } else if post_residual % 5 == 0 { 2 } else { 3 };
    score += match class { 0 => -50.0, 1 => -10.0, 2 => 0.0, _ => 8.0 };

    // Integer-division dead-space threshold: post_residual below 10 is near-unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item won't fit here; penalize wasting a tight residual
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 6.0 * waste;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when this placement
    // would leave a large, non-harmonic residual and open bins are few.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 0.6 * bin_capacity as f64 && class == 3;
        score = if bad_fit && open_bins_count == 0 { -60.0 } else { 60.0 + 0.1 * open_bins_count as f64 };
    }

    // Slight pressure to consolidate: prefer fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (0.5 + progress);

    // Deviation from mean residual: prefer bins near/below mean residual (tighter).
    score += 0.15 * (post_residual as f64 - mean_residual).abs().signum()
        * (post_residual as f64 - mean_residual).abs().min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 120.0;
