        score += 25.0 * (dead_threshold / pr).powi(2);
    }

    // Reward tight fits: post_residual small relative to capacity
    score -= 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

