    // proportionally to open_bins_count so it only wins when fits are awful.
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * (open_bins_count as f64);
        // Allow a new bin if the current best fits would leave terrible gaps
        if (post_residual as f64) >= 0.5 * (bin_capacity as f64) {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward leaving that gap; if next item can't use the gap, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
