    // --- Harmonic capacity-fraction tiers of post_residual (C/16, C/8, C/4, C/2) ---
    if post_residual == 0 {
        score -= 3.0 * c; // perfect closure: best possible outcome
    } else if post_residual <= bin_capacity / 16 {
        score -= 0.40 * c;
    } else if post_residual <= bin_capacity / 8 {
        score -= 0.25 * c;
    } else if post_residual <= bin_capacity / 4 {
        score -= 0.10 * c;
    } else if post_residual > bin_capacity / 2 {
        score += 0.12 * c; // leaving a bin more than half empty is wasteful
    }

    // --- Harmonic residue class: round residuals (mod 10) align with item granularity ---
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // --- Lookahead coupling with next_item_size (integer-division size classes) ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let nclass = (next_item_size / 25) as f64; // 0: tiny, 1: medium, 2: large, 3: huge
        if post_residual == next_item_size {
            score -= 1.2 * c; // exact chain fit: next item closes this bin perfectly
        } else if post_residual > next_item_size {
            if post_residual % next_item_size == 0 {
                score -= 0.35 * c; // harmonic multiple: k exact copies of next item fit
            }
            let after_next = post - nxt;
            score -= 0.30 * (c - after_next).max(0.0); // reward near-closure after next lands
            if post_residual >= next_item_size + bin_capacity / 4 {
                score += 0.08 * c; // but excessive leftover slack after next is dead weight
