        // No lookahead (final items): pure tightness preference
        score -= 0.10 * (c - post).max(0.0);
    }

    // --- Last-chance bin: the only open bin that fits, before a new bin is opened ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 0.40 * (bin_residual - post_residual) as f64; // ~0.40 * item_size reward
    }

    // --- New-bin candidate discipline: prefer consolidation when slack exists elsewhere ---
    if is_new_bin && open_bins_count > 0 {
        score += 3.0
            + 0.06 * open_bins_count as f64
            + 0.08 * mean_residual.max(0.0).min(c)
            + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=9) are nearly unusable
    // for future items (min size 10) — heavily penalize them.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Usable-gap quality: reward residuals that can still host a typical item.
    if post_residual >= 10 {
        score -= 12.0;
    }

    // Coupling with open bins pressure: many open bins -> prefer filling existing
    // bins rather than spreading; few open bins -> new bins are cheaper.
    let bin_pressure = open_bins_count as f64 / (bin_capacity as f64 / 10.0);
    score += bin_pressure * 3.0;

    // New-bin candidate logic: an empty bin has perfect residual but wastes the
    // chance to consolidate. Penalize it unless no good fit exists.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 1
            || (fitting_bins_count == 1 && post_residual >= 10 && post_residual < 50);
        if good_fit_exists {
            score += 25.0 + mean_residual * 0.3;
        } else {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual - next_item_size < 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    }

    // Slight progression term: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

