pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled mildly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.5 * tightness * (bin_residual as f64);

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining bonus: next item fills this bin further.
            let chain_fit = (next_item_size as f64) / (post_residual as f64);
            score -= 6.0 * chain_fit;
            // Extra reward if chain nearly exhausts the bin.
            if post_residual - next_item_size <= 5 {
                score -= 4.0;
            }
        } else {
            // Penalize leaving residual the next item cannot use (dead space).
            let gap = (post_residual - next_item_size) as f64;
            score += 0.3 * gap;
            // Heavy penalty if next item is large and this bin becomes wasted.
            if next_item_size >= 40 {
                score += 0.2 * gap * (next_item_size as f64 / 100.0);
            }
        }
    } else {
        // Last item: just minimize final residual.
        score -= 2.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarcer;
    // placing into a below-mean-residual bin is efficient consolidation.
