    score += 0.15 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
        // Especially if this is a decent fit.
        if post_residual <= 20 {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the
    // current item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit_elsewhere = (post_residual as f64) < 10.0;
        if pressure > 0.0 || (item_size >= 60 && poor_fit_elsewhere) {
            score -= 3.0;
        } else {
            score += 15.0; // discourage wasting a fresh bin on small items
        }
    }

    // Stream progression: early on, be conservative (keep bins flexible);
    // later, allow tighter, riskier packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * tightness;

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: the smaller the waste relative to capacity, the better.
    let waste_frac = post_residual as f64 / cap;
    score += waste_frac * waste_frac * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - leftover_after_next as f64 / cap);
        } else {
            // Post-residual too small for next item: penalize dead space creation.
            score += (post_residual as f64) * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // Prefer new bin only if this item would leave a very awkward residual elsewhere,
        // or if open bins are already quite full on average.
        let awkward = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            10.0
