    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling of post residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 30.0 * poly * (0.5 + progress);
    // Penalize large dead space more as stream advances
    score += progress * norm_pr * norm_pr * cap * 0.15;
    // Reward tight fits, weighted by scarcity of fitting bins
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (fitting_bins_count as f64).recip() * 12.0;
