    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
