pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let t = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - t * t);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
        // Reward leaving room exactly compatible with the next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: pure tightness, no future concerns.
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * (1.0 - waste_ratio);
    }

    // New-bin candidate handling: neutral baseline, slightly discouraged early,
    // encouraged when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 18.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 25.0; // all open bins too fragmented; new bin is good
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 8.0; // pair the current item with next in a fresh bin
        }
    }

    // Prefer bins below mean residual (fill emptier bins first keeps big holes alive).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.08 * diff;

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for larger items filling larger residuals.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, slightly convex to punish dead space
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling with stream progress: prefer tight fits more as stream advances
    let tightness = 1.0 - norm_pr;
    score -= (2.0 + 14.0 * progress * progress) * tightness * tightness * cap * 0.1;

    // Smooth interaction: post_residual vs lookahead item fit
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        let nx_fit = if pr >= nx { 1.0 } else { 0.0 };
        // reward if next item can fit in post residual, scaled smoothly
        let reward = nx_fit * (1.0 - (fit_gap / cap).powf(1.5)) * (6.0 + 10.0 * progress);
        score -= reward;
        // penalize post residual that is just barely too small for next item (dead space trap)
