        score += near_miss * 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Mild penalty when many bins are open and this one deviates from mean residual
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate should generally lose unless open bins are very fragmented
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
    }

