            score -= 40.0 + 30.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // Penalize creating dead space the next item cannot use.
            let waste = (post_residual as f64).min(next_item_size as f64);
            score += 0.5 * waste;
        }
    }

    // Penalize poor absolute fit (large leftover that few future items can use).
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual > 50 {
        score += 8.0; // wasteful half-empty bin
    }

    // Relative to mean residual: prefer bins tighter than average.
