        }
        // Combined: penalize leaving residuals that neither the next item nor the
        // mean open-bin residual can absorb (dead-space coupling fix).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < next_item_size as f64 && after > mean_residual.max(1.0) {
                score += 3.0 * (1.0 - after / (next_item_size as f64)) * (1.0 - progress);
            }
        }
        // Avoid residuals in the awkward 12..20% band when many items remain
        // and no chain is possible — these tend to become permanent dead space.
        if dead_ratio >= 0.12 && dead_ratio < 0.20 && stream_left2 > 0.5
            && (next_item_size == 0 || next_item_size > post_residual) {
            score += 3.0 * (dead_ratio - 0.12) * 50.0 * stream_left2;
        }
        // NEW: reward residuals that can chain the next item and remain
        // divisible-friendly for repeated sizes (harmonic packing).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after % next_item_size == 0 {
                score -= 2.0 + 0.2 * (after / next_item_size) as f64;
            }
            // Chain leaves residual absorbable by mean open-bin leftover.
            if after > 0 && (after as f64) <= mean_residual.max(1.0) {
                score -= 2.5 * (1.0 - stream_left2 * 0.5);
            }
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: integer division into capacity-fraction bands.
    // Residuals that are "usable" (large enough for typical items) should be preferred
    // over dead space, so we add a penalty that grows as post_residual falls into
    // small, hard-to-fill classes.
    let class = post_residual / 10; // harmonic class of leftover space (0..10)
    match class {
        0 => score += 45.0,                 // dead space: 0..9 left
        1 => score += 30.0,                 // 10..19: only tiny items fit
        2 => score += 18.0,                 // 20..29
        3 => score += 10.0,                 // 30..39
        4 => score += 4.0,                  // 40..49
        5 => score += 0.0,                  // 50..59: sweet spot
        6 => score -= 1.0,                  // 60..69
        7 => score -= 2.0,                  // 70..79
        8 => score -= 2.5,                  // 80..89
        9 => score -= 3.0,                  // 90..99
        _ => score -= 3.0,                  // full-ish
    }

    // Perfect fit reward: modular arithmetic on capacity.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        // Round leftover aligned to the 10-grid is more likely reusable.
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (sets up a perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how snugly.
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this leftover: penalize large leftover slightly.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual, but opening
    // a new bin when good fits exist wastes capacity. Penalize the fresh bin
    // proportionally to how many bins already fit the item, and to stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 12.0 + 10.0 * open_pressure + 15.0 * (1.0 - progress) * (fitting_bins_count as f64);
        // But if the item is huge relative to mean residual, allow the new bin.
        if mean_residual > 0.0 && (item_size as f64) > mean_residual * 0.9 {
            score -= 20.0;
        }
    }

    // Slight global pressure: prefer filling bins when many are open (consolidation).
    score += 0.05 * open_bins_count as f64;

    // Prefer tighter fits overall: reward small post_residual relative to capacity.
    score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 120.0;
        }
    } else if post_residual <= bin_capacity / 5 {
        score += 20.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 4.0;
    } else {
        score -= 18.0;
    }

    // Exact lookahead match: perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0;
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0;
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
                score -= 12.0 + 0.15 * (pr - nxt);
            }
            if after >= nxt {
                score -= 10.0;
                if after >= 2.0 * nxt {
                    score -= 6.0;
                }
            }
            if nxt > 0 && (pr as u32) % (nxt as u32) == 0 {
                score -= 7.0;
            }
            if after > 0.0 && after <= mean_residual.max(1.0) {
                score -= 3.0;
            }
            if after >= 3.0 && after <= 15.0 {
                score -= 3.5;
            }
            if after > 0.0 && after % nxt.max(1.0) == 0.0 && after >= nxt {
                score -= 2.0 + 0.15 * (after / nxt);
            }
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
            // Combined feature: two-item lookahead — residual after placing next item
            // should either be zero or absorbable by the average open bin.
            if after > 0.0 && after < cap * 0.5 {
                let frac = after / cap;
                if (frac * 10.0).round() as i32 <= 1 {
                    let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                    score -= 2.0 * (1.0 - frac * 10.0) * (1.0 - scarcity);
                }
            }
            // Deep lookahead compaction: chain residual absorbable by typical size band.
            if after > 0.0 && after >= mean_residual.max(1.0) * 2.0 && after <= cap * 0.35 {
                score += 2.0 * (after / cap);
            }
            // NEW: double-chain bonus — next item fits twice into post residual.
            if after >= nxt && after - nxt < class_width as f64 {
                score -= 5.0;
            }
        } else {
            let gap = nxt - pr;
            if gap <= 8.0 {
                score += 60.0 + 6.0 * (8.0 - gap);
            } else {
                score += 25.0 * (1.0 - pr / nxt.max(1.0));
            }
            if gap <= 15.0 {
                let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
            if gap <= 20.0 && ((fitting_bins_count as f64) / 5.0).min(1.0) < 0.5 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }
    }

    // Relative-to-mean: prefer tighter-than-average bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance: only fitting bin -> keep item out of a new bin.
    if fitting_bins_count == 1 {
        score -= 160.0;
    } else if fitting_bins_count == 0 {
        score += 80.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_cap = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                && mean_residual < next_item_size as f64 * 1.15
                && (fitting_bins_count as f64) < 4.0)
                || (total_fit_cap < next_item_size as f64 * 2.0
                    && fitting_bins_count <= 1));
        if big_item || crowded || next_needs_fresh {
            score -= 55.0;
        } else {
            score += 70.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
            // Fresh-bin capacity check: collective absorption of current + next.
            if open_bins_count > 0 && next_item_size > 0 {
                if total_fit_cap < (item_size + next_item_size) as f64 * 0.9 {
                    score -= 12.0;
                }
            }
            // Fresh bin leaving a residual exactly matching next item = perfect chain.
            if next_item_size > 0 && post_residual == next_item_size {
                score -= 45.0;
            }
            // NEW: fresh bin is better when open bins' residuals are all smaller
            // than the next item and numerous — avoid fragmenting further.
            if open_bins_count > 25 && mean_residual < 0.10 * cap {
                score -= 6.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 27.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Consolidation pressure early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mid-band residual (30..60) packs well with typical sizes.
    if post_residual >= 30 && post_residual <= 60 {
        let remaining = (total_items - step_index) as f64;
        let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
        score -= 5.0 + 3.0 * stream_left;
    }

    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Sharp penalty for the 5..12% sliver band.
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band attraction toward center.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Chain into small residual in the 10..18% band.
        if dead_ratio > 0.10 && dead_ratio < 0.18 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
        }
        // Mid-range dead space early in stream: penalize mildly.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
        // Tiny residual left after chaining next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
        }
        // Hard-to-fill residual with few fitting bins: avoid creating it.
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 2.0 * (0.08 - dead_ratio) * 100.0;
        }
        // Wide-open bins with next item smaller: strong chain candidate.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // Gap-based penalty when next item doesn't fit.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
        // Divisibility bonus.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        // Small-residual avoidance when many bins can still fit.
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        // Penalize residuals neither the next item nor mean residual can absorb.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < next_item_size as f64 && after > mean_residual.max(1.0) {
                score += 3.0 * (1.0 - after / (next_item_size as f64)) * (1.0 - progress);
            }
        }
        // Avoid awkward 12..20% band residuals when no chain is possible.
        if dead_ratio >= 0.12 && dead_ratio < 0.20 && stream_left2 > 0.5
            && (next_item_size == 0 || next_item_size > post_residual) {
            score += 3.0 * (dead_ratio - 0.12) * 50.0 * stream_left2;
        }
        // NEW: penalize residuals that cannot absorb the next item even in two
        // steps, when the stream is long — these become permanent dead space.
        if next_item_size > 0 && post_residual < next_item_size
            && stream_left2 > 0.4 && dead_ratio < 0.25 && fitting_bins_count >= 2 {
            score += 2.0 * (1.0 - dead_ratio / 0.25) * stream_left2;
        }
        // NEW: reward residuals that are sums of small typical sizes (divisible
        // by 5 or 10) — easier to fill later from unknown distributions.
        if post_residual % 5 == 0 && dead_ratio > 0.10 && dead_ratio < 0.40 {
            score -= 2.0;
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (item consumes most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from open bins: with many open bins, prefer filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual is a dead gap for the next item.
        score += 10.0;
    }

    // New-bin candidate: only attractive when item is large or no good fits exist.
    if bin_residual == bin_capacity {
        let base = 45.0 + (open_bins_count as f64) * 2.0;
        let big_item_bonus = if item_size >= 60 { 25.0 } else { 0.0 };
        let last_chance_penalty = if fitting_bins_count <= 1 { 60.0 } else { 0.0 };
        score = base - big_item_bonus + last_chance_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
