            score -= 100.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted space
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when reasonable open bins exist
    if bin_residual == bin_capacity {
        score += 80.0 + post_residual as f64;
        if mean_residual > item_size as f64 {
            score += 40.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    }

    score
}

