pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post residual, softly normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let coupling = prn * prn * (1.0 - progress) + prn * progress * (1.0 - prn);
