    score += 1.5 * dead * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual relative to item)
    let tight = (item_size as f64) / cap;
    score -= 0.6 * tight * (1.0 - prn);

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 1.0 * (next_item_size as f64 / cap);
    } else if next_item_size > post_residual {
        score += 0.3 * (1.0 - progress);
    }

    // Last-chance bonus: only fitting bin -> avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.2;
    }

    // New-bin candidate: mildly discouraged early, more acceptable late
    if bin_residual == bin_capacity {
        score += 0.5 - 0.4 * progress;
    }

    // Discourage bins far from mean residual (fragmentation)
    let dev = (pr - mean_residual).abs() / cap;
    score += 0.2 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
