pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but treat tiny residuals as dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // unusable sliver (items >= 1, but mostly larger)
    }

    // Harmonic class of post_residual: classify by integer division thresholds.
    let class = post_residual / 10; // 0..=10
    let class_penalty = match class {
        0 => 12.0,               // 0..9 : nearly dead
        1 => 6.0,                // 10..19: only tiny items fit
        2 => 2.0,                // 20..29
        3 | 4 => 0.0,            // 30..49: moderate utility
        5 | 6 => -1.5,           // 50..69: flexible
        7 | 8 | 9 => -3.0,       // 70..99: very flexible
        _ => -4.0,               // full empty bin
    };
    score += class_penalty;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next_item_size fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how well the next item uses leftover
            let waste = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leaving large residual unused
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Neutral-ish base; add pressure so it loses to decent fits.
        score += 10.0;
        // But if all open bins would leave big waste, new bin becomes attractive:
        // compare current bin's waste vs a fresh bin's (capacity - item_size).
        let fresh_waste = bin_capacity - item_size;
        let this_waste = post_residual;
        if this_waste > fresh_waste + 25 {
            score -= (this_waste - fresh_waste) as f64 * 0.5;
        }
        // Early in stream, opening bins is cheap and diversifies residual classes.
        if step_index as f64 / (total_items.max(1) as f64) < 0.3 {
            score -= 4.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far above mean, it's a
    // "straggler" bin — prefer filling it down to close it out.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.05;
    } else {
        score += (-dev) * 0.03;
    }

    // Modulo harmonic bonus: residuals divisible by common item granularities
    // (10/20/25) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    // Many open bins: encourage consolidation (closing bins) over spreading.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * 0.1;
    }

    score
}

