        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        // Chained fits: post_residual can host next item twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 10.0;
            }
            if chain >= 2 * next_item_size {
                score -= 6.0;
            }
            if chain > 0 && chain % 10 == 0 {
                score -= 4.0;
            }
        }
        // Near-miss gap penalties scaled by scarcity.
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
            if gap <= 20.0 && scarcity < 0.5 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }
        // Mid-band residue attraction around 0.325 * cap.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Scarce fitting bins and moderate residue that can't host next item.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // Post-fit residue nearly exhausted.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * (1.0 - after / cap) * (1.0 - scarcity);
            }
        }
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 4.0 * (0.08 - dead_ratio) * 100.0 * 0.5;
        }
        // Very large post-fit residues can still host more.
        if next_item_size > 0 && post_residual > next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
        }
        if dead_ratio > 0.48 && fitting_bins_count <= 2 && next_item_size as f64 > post_residual as f64 {
            score += 3.0 * (dead_ratio - 0.48) * 20.0;
        }
        // Exact divisibility reward.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        // Sparse fitting bins and tight residue: keep it usable.
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        // Post-fit residue in the lower half of capacity.
        let after2 = if next_item_size > 0 && post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            -1.0
        };
        if after2 >= 0.0 && after2 < cap * 0.5 {
            let frac = after2 / cap;
            if (frac * 10.0).round() as i32 <= 1 {
                score -= 2.0 * (1.0 - frac * 10.0) * (1.0 - scarcity);
            }
        }
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
        // Mild penalty for mid-range dead space when many items remain.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
    }

    // Endgame: squeeze residual space hard when the stream is nearly done.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match for the next item (small slack).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 25.0;
    }
    // Penalize dead space: post_residual too small for any plausible next item (min size 1, typical > 10).
    if post_residual < 10 {
        score += 30.0;
    }
    // Penalize if next item can't fit here (forces split across bins).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward bins tighter than the mean residual (good fits concentrate space).
    score -= (mean_residual - post_residual as f64) * 0.4;
    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // Early in the stream: allow opening bins more freely to build diverse residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize slightly unless it's early or nothing fits well.
        score += 8.0 + 15.0 * progress;
        if post_residual == bin_capacity && next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }
    // Prefer filling nearly-full bins.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.98;
