}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio through the stream
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits (low post residual) more strongly as stream progresses
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that is too small for typical items (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if we waste most residual
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins with much more space than average
    // should be penalized slightly for squandering capacity
    let mean_res = mean_residual;
    if (bin_residual as f64) > mean_res * 1.5 {
        score += 4.0;
    } else if (bin_residual as f64) < mean_res * 0.5 {
        score -= 4.0;
    }

    // New-bin candidate: default moderate score; opened only when existing fits are bad
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in stream when consolidation is hard
        score = 55.0 - 20.0 * progress;
        // If next item is large, a fresh bin is more attractive
        if next_item_size >= item_size {
            score -= 8.0;
        }
    }

