    // New-bin candidate: only attractive when the item fits badly everywhere
    // else (large item, high mean residual spread). Penalize default new bin,
    // but relax penalty when item is large relative to capacity.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 55.0 - 0.4 * item_size as f64;
        score += new_bin_penalty;
        // If next item is large, a fresh bin may be valuable for it.
        if next_item_size >= 70 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item exactly fits the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item could fit in post_residual, mild reward.
    if next_item_size > 0 && next_item_size < post_residual && post_residual - next_item_size < 10 {
        score -= 15.0;
    }

    // Slight preference for tighter bins (below mean residual) as stream progresses.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

