        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
            // decile-aligned small leftovers fill easily with common sizes
            if after > 0.0 && after % 10 == 0 && after <= 40 {
                score -= 2.0 * (1.0 - scarcity);
            }
        }
        // Sliver band with few fitting bins: strongly discourage.
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 4.0 * (0.08 - dead_ratio) * 100.0 * 0.5;
        }
        // Reward bins that can still absorb a small extra item after chaining.
        if next_item_size > 0 && post_residual > next_item_size {
            let after = (post_residual - next_item_size) as f64;
