pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills: small post_residual is good.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize leaving large post_residuals that waste space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(40.0);
        }
    }

    // Dead-space penalty: residuals too small for typical items are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Compare against mean residual: bins with residual below mean are scarcer; prefer
    // filling tighter bins, penalize draining bins that are already roomy.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        if res < mean_residual {
            score -= 0.3 * (mean_residual - res);
        } else {
            score += 0.2 * (res - mean_residual);
        }
    }

    // New-bin candidate: penalize opening a new bin when stream is early/mid and
    // open bins exist that could take the item; allow new bins late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // If no open bin fits tightly, opening new bin is more attractive.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but avoid exact-zero
    // dead space only when it wastes a nearly-full bin on a small item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward mid-range gaps that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        score += 2.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item can still fit in the post-residual, reward;
    // if this placement would block the next item while another bin could
    // have taken the current one, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // New-bin candidate handling: opening a bin is expensive early when few
    // bins are open, cheaper late when many bins are open anyway.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress) - 2.0 * (open_bins_count.min(20) as f64);
        // Opening a new bin is justified if the item fits nowhere tightly.
        if fit_ratio < 0.35 && fitting_bins_count > 2 {
            score -= 15.0;
        }
    } else {
        // Mild preference for filling bins that are already well-loaded
        // relative to the mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    // Slight time discount: late in the stream, closing bins tightly matters
    // more than keeping options open.
    score -= 2.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 120.0;
        }
    } else if post_residual <= bin_capacity / 5 {
        score += 20.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 4.0;
    } else {
        score -= 18.0;
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0;
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0;
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
                score -= 12.0 + 0.15 * (pr - nxt);
            }
            if after >= nxt {
                score -= 10.0;
                if after >= 2.0 * nxt {
                    score -= 6.0;
                }
            }
            if nxt > 0 && (pr as u32) % (nxt as u32) == 0 {
                score -= 7.0;
            }
            if after > 0.0 && after <= mean_residual.max(1.0) {
                score -= 3.0;
            }
            if after >= 3.0 && after <= 15.0 {
                score -= 3.5;
            }
            if after > 0.0 && after % nxt.max(1.0) == 0.0 && after >= nxt {
                score -= 2.0 + 0.15 * (after / nxt);
            }
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
            if after > 0.0 && after < cap * 0.5 {
                let frac = after / cap;
                if (frac * 10.0).round() as i32 <= 1 {
                    let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                    score -= 2.0 * (1.0 - frac * 10.0) * (1.0 - scarcity);
                }
            }
            if after > 0.0 && after >= mean_residual.max(1.0) * 2.0 && after <= cap * 0.35 {
                score += 2.0 * (after / cap);
            }
            // NEW: reward after-residuals divisible by 10 (common size bands)
            if after > 0.0 && (after as u32) % 10 == 0 && after <= cap * 0.4 {
                score -= 3.0;
            }
        } else {
            let gap = nxt - pr;
            if gap <= 8.0 {
                score += 60.0 + 6.0 * (8.0 - gap);
            } else {
                score += 25.0 * (1.0 - pr / nxt.max(1.0));
            }
            if gap <= 15.0 {
                let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
            if gap <= 20.0 && ((fitting_bins_count as f64) / 5.0).min(1.0) < 0.5 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }
    }

    score -= 0.5 * (mean_residual - post_residual as f64);

    if fitting_bins_count == 1 {
        score -= 160.0;
    } else if fitting_bins_count == 0 {
        score += 80.0;
    }

    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_cap = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                && mean_residual < next_item_size as f64 * 1.15
                && (fitting_bins_count as f64) < 4.0)
                || (total_fit_cap < next_item_size as f64 * 2.0
                    && fitting_bins_count <= 1));
        if big_item || crowded || next_needs_fresh {
            score -= 55.0;
        } else {
            score += 70.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
            if open_bins_count > 0 && next_item_size > 0 {
                if total_fit_cap < (item_size + next_item_size) as f64 * 0.9 {
                    score -= 12.0;
                }
            }
            if next_item_size > 0 && post_residual == next_item_size {
                score -= 45.0;
            }
            // NEW: fresh-bin residual in the 30..60 sweet band is a good anchor
            if post_residual >= 30 && post_residual <= 60 && next_item_size > 0 && next_item_size <= post_residual {
                score -= 8.0;
            }
        }
