        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
        }
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 2.0 * (0.08 - dead_ratio) * 100.0;
        }
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < next_item_size as f64 && after > mean_residual.max(1.0) {
                score += 3.0 * (1.0 - after / (next_item_size as f64)) * (1.0 - progress);
            }
        }
        if dead_ratio >= 0.12 && dead_ratio < 0.20 && stream_left2 > 0.5
            && (next_item_size == 0 || next_item_size > post_residual) {
            score += 3.0 * (dead_ratio - 0.12) * 50.0 * stream_left2;
        }
        // NEW: avoid creating residuals larger than next item but smaller than
        // next item + 10 when few fitting bins — near-miss dead space.
        if next_item_size > 0 && post_residual > next_item_size
            && post_residual < next_item_size + 10 && fitting_bins_count <= 2 {
            score += 4.0 * (1.0 - scarcity);
        }
    }

    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: post residual, with smooth non-linear coupling to stream progress.
    // Early on, prefer tight fits modestly; late in stream, dead space matters more.
    let mut score = post * (1.0 + 0.8 * progress * norm_post * norm_post);

    // Penalize large post residual non-linearly (quadratic dead-space waste).
    score += 6.0 * norm_post * norm_post * (1.0 + progress);

    // Reward filling bins with small remaining space (smooth inverse coupling).
    score -= 10.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - norm_post);
    }

    // Lookahead: reward leaving space that fits the next item smoothly.
    let nis = next_item_size as f64;
    if nis > 0.0 {
        let gap = (post - nis).abs();
        let fit_next = if post >= nis { 1.0 } else { -1.0 };
        score += fit_next * 4.0 * (gap / cap) * (gap / cap) - 3.0 * (post / cap) * (nis / cap);
    }

    // Mild penalty when many bins are open relative to progress (encourage consolidation).
    score += 0.15 * open_bins_count as f64 * (0.3 + progress);

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic).
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
