pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with common item sizes get rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = post / cap;

    // Penalize large leftover (wasted capacity) superlinearly.
    score += 0.6 * frac * frac * cap;

    // Modulo classes: post_residual in {0, 10, 20, 25, 50} are "harmonic" complements
    // likely reusable by future items (multiples of common sizes).
    let harmonic = match post_residual % 100 {
        0 => -14.0,
        10 | 20 | 25 | 50 => -6.0,
        r if r % 10 == 0 => -3.0,
        _ => 0.0,
    };
    score += harmonic;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + 0.05 * next_item_size as f64;
        } else {
            score += 5.0; // dead space relative to lookahead
        }
        // Harmonic pairing: post_residual mod next_item_size small => tighter future fit.
        if next_item_size > 0 && post_residual > 0 {
            let m = post_residual % (next_item_size as f64).max(1.0);
            score -= 0.15 * (next_item_size as f64 - m);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: discourage opening a new bin unless current bin leaves bad residue.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if the item is large (harmonic class of big items), a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 22.0;
        }
    }

    // Slight preference for tighter bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.05 * (bin_residual as f64 - post);

    // Coupling with mean residual: if this bin is much tighter than average, prefer it.
    score -= 0.3 * (mean_residual - post).max(0.0);

    score
}

