pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling with stream progress:
    // later in the stream, tighter fits matter more (dead space is costlier)
    let tightness = 1.0 - x * x; // favors small x
    score -= tightness * (cap * (0.35 + 0.65 * progress));

    // Penalize moderately-large but unusable residuals via cubic term
    score += 40.0 * x * (1.0 - x) * x * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Discourage scattering across many open bins late in stream
    score += 0.6 * open_bins_count as f64 * (0.3 + 0.7 * progress) * x;

    // Pull toward mean residual to keep bins balanced early
    score += 0.15 * (mean_residual - pr) * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline, only attractive when fit is bad
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.45 * (1.0 - progress)) + 0.5 * (fitting_bins_count as f64);
        if fitting_bins_count == 0 {
            score = -100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // capacity fractions (eighths). Small, "usable" leftovers get rewarded.
    let frac = post_residual as f64 / bin_capacity as f64; // 0..1
    let octave = (frac * 8.0).floor() as i32; // 0..7 harmonic class

    // Reward small-but-not-zero leftovers (tight fits) in the lower octaves.
    match octave {
        0 => score -= 12.0,                       // near-perfect fit
        1 => score -= 7.0,                        // good fit
        2 => score -= 3.0,                        // decent fit
        3 => score -= 0.5,                        // neutral
        4 => score += 1.5,                        // half-full leftover
        5 => score += 4.0,
        6 => score += 7.0,
        _ => score += 10.0,                       // mostly empty: wasteful
    }

    // Dead-space penalty: leftovers too small for the minimum plausible item
    // (items 1..100, so leftover 1..3 is nearly dead) are heavily penalized.
    if post_residual >= 1 && post_residual <= 3 {
        score += 25.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Modulo-class coupling with the lookahead item: if the next item
    // divides the post residual cleanly (post_residual % next_item_size == 0),
    // this bin is on a harmonic packing path — reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 6.0;
        } else if post_residual % next_item_size <= 4 {
            score -= 2.5;
        }
    }
    // If the next item cannot fit here anyway, mild bonus (no competition loss).
    if next_item_size > 0 && next_item_size > post_residual {
        score -= 1.0;
    }

    // Last-chance bin: only one bin fits the item; strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current leftovers
    // are badly fragmented. Scale penalty with stream progress (early on,
    // keep bins open to learn structure; late, prefer consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * progress;
        // But if open bins are very fragmented (high mean residual), opening
        // a fresh bin is fine.
        if mean_residual > 60.0 {
            score -= 20.0;
        }
    }

    // Prefer filling bins with low residual relative to the fleet mean
    // (consolidation toward the emptiest-fitting bin).
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    // Mild preference for fewer open bins.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
