            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
        }
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 2.0 * (0.08 - dead_ratio) * 100.0;
        }
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < next_item_size as f64 && after > mean_residual.max(1.0) {
                score += 3.0 * (1.0 - after / (next_item_size as f64)) * (1.0 - progress);
            }
        }
        if dead_ratio >= 0.12 && dead_ratio < 0.20 && stream_left2 > 0.5
            && (next_item_size == 0 || next_item_size > post_residual) {
            score += 3.0 * (dead_ratio - 0.12) * 50.0 * stream_left2;
        }
        // MUTATION: global waste coupling — penalize bins whose post residual
        // cannot be absorbed by the collective open capacity per remaining
        // item; favors tight fits when the stream is nearly exhausted.
        if next_item_size > 0 && post_residual < next_item_size {
            let per_item_cap = if total_items > step_index + 1 {
                mean_residual / ((total_items - step_index - 1) as f64).max(1.0)
            } else {
                mean_residual
            };
            if per_item_cap < dead_ratio * cap * 0.05 {
                score += 4.0 * dead_ratio * 10.0 * stream_left2;
            }
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with common item sizes (10..80)
    let resid = post_residual as i64;
    let cap = bin_capacity as i64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward post-residuals divisible by small harmonic steps (they admit more future items)
    for d in [5i64, 10, 20, 25, 50] {
        if resid % d == 0 && resid > 0 {
            score -= 4.0 + d as f64 * 0.1;
        }
    }

    // Penalize "dead zone" residuals: too small for any item (1..=100, min item 1)
    if resid > 0 && resid < 10 {
        score += 30.0;
    }

    // Penalize residuals in awkward modulo classes (e.g. 1 mod 10 leaves prime-like gaps)
    if resid % 10 != 0 && resid > 0 {
        score += 3.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual (perfect chaining)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let chain = (post_residual - next_item_size) as f64;
            score -= 8.0 - 0.05 * chain;
        } else {
            score += 5.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current residuals are highly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (mean_residual as u32 % 10) as f64) / cap as f64;
        score += 12.0 - 20.0 * fragmentation;
        if post_residual % 50 == 0 {
            score -= 6.0; // fresh bin with harmonic half-capacity is attractive for big items
