    }

    // Early stream: prefer tight packing; late stream: tolerate slight slack to close bins
    if progress > 0.8 && post_residual < 15 {
        score -= 6.0;
    }

    // Mean-residual coupling: prefer bins below the mean (pack the emptier ones tighter)
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

