            score += (50.0 - post_residual as f64) * 0.3;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item is large and this bin would leave it stranded, mild penalty.
    if next_item_size > post_residual && next_item_size > 50 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
