        score -= 35.0;
    } else if fitting_bins_count > 3 {
        score += 5.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Prefer fuller bins relative to average residual state.
    if (bin_residual as f64) > mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Early in stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score -= 5.0 * (bin_residual != bin_capacity) as i32 as f64;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no open bin is a good fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size >= 60 && (bin_residual - item_size) <= 20 {
            score -= 70.0; // large item with poor fit elsewhere -> open new bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

