        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += diff * 20.0;
    }

    // New-bin candidate handling: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many items remain or item is large.
        let mut new_bin_score = 60.0;
        if item_size > 60 {
            new_bin_score -= 15.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 70.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
            new_bin_score -= 10.0; // pairing potential in a fresh bin
        }
        score = new_bin_score + score * 0.1;
    }

    score
}

