pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: any small unusable gap is heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item
    // (items are 1..=100; treat gaps < 10 as dead, and taper the penalty up to 30).
