    // Last-chance bin: if this is the only bin that fits, strongly prefer using
    // it over opening a new bin (unless the gap penalty above is extreme).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when no open bin offers a decent fit. Give it a
    // baseline score that tracks the mean residual of open bins: if open bins
    // are already tight (low mean residual), opening fresh is cheap; if open
    // bins are roomy, discourage new bins.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.8 * mean_residual + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 120.0; // discourage opening when some bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

