            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    } else {
        // last item: just minimize waste
        score += 0.2 * post_residual as f64;
    }

    // Penalize very small post_residual (classic dead-space trap)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

