    let res = post_residual as f64;
    if res < mean_residual - 20.0 {
        score += 8.0; // much tighter than average: riskier
    } else if res > mean_residual + 20.0 {
        score -= 5.0; // roomier than average: good candidate
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Early in stream: favor consolidation into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when current fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * mean_residual.min(60.0);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 0.0;
        }
        if post_residual == bin_capacity && fitting_bins_count == 0 {
            score -= 15.0; // no open bin fits at all: open new bin
        }
    }

    score
}

