        score -= 5.0 + 6.0 * (1.0 - norm_pr);
    }
    // lookahead: reward leaving space that next item could use
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = pr - ns;
        if diff >= 0.0 {
            score -= 3.0 * (diff / cap);
        } else {
            score += 2.0 * (-diff / cap);
        }
    }
    // slight penalty for spreading across many open bins
