            score -= 4.0;
        } else if pr >= 10 && pr <= 20 {
            score += 6.0; // awkward dead space zone
        }
    } else {
        score -= 15.0; // perfect fit
    }

    // Very small residual is dead space unless it exactly fits next item.
    if pr > 0 && pr < 10 {
        score += 10.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
