                score -= 5.0;
            }
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin is a fallback.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins when they fit decently (post_residual small-ish),
