    }

    // Mild preference to spread load when many bins open and mean residual high.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Stream progression: tighten packing near the end.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * t * 0.2;

    score
}

