        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer bins whose residual is close to the item (minimize fragmentation).
    score += 0.3 * ((bin_residual as f64 - item_size as f64).abs());

    score
