pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1) are pure waste, but gaps that cannot fit a
    // "typical" mid-size item are much worse than large usable gaps.
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold {
        // Small unusable gap: heavy penalty proportional to how close it
        // is to being completely empty (perfect fit) vs. leaving a sliver.
