    }

    // Reward very tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Reward if the leftover gap exactly fits the lookahead item (k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > next_item_size && (post_residual as f64) < dead_threshold {
        // Gap too small for next item but nonzero: extra dead-space penalty.
        score += 8.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening more
    // (penalize the new-bin candidate) but encourage closing out bins.
