        // New-bin candidate: penalize more when open bins are plentiful.
        score += 20.0 + 4.0 * open_bins_count as f64;
        // But allow new bins early in the stream or when nothing fits well.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    } else {
        // Fitting into an existing bin relieves open-bin pressure.
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual is above the mean (consolidate space).
    if bin_residual != bin_capacity {
        score += 0.5 * (mean_residual - bin_residual as f64);
    }

    score
}

