    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive later.
        score += 20.0 * progress - 5.0 * (1.0 - progress);
        if post_residual == 0 { score -= 50.0; } // item fills a fresh bin exactly
    } else {
        score -= 10.0 * progress; // favor reuse as stream advances
    }

    // Tightness coupling: reward using most of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 18.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear penalty on dead space: quadratic in normalized residual,
    // growing with stream progress (dead space matters more later).
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: item filling most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill * fill;

    // Lookahead coupling: if the next item exactly fits the post-residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let chain = (1.0 - diff / cap).max(0.0);
        score -= 6.0 * chain * chain;
        // Penalize leaving residual too small for the next item (wasted space).
        if pr < next_item_size as f64 {
            score += 3.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Many open bins: prefer consolidation into low-residual bins.
    let pressure = (open_bins_count as f64 / 8.0).min(1.0);
    score -= pressure * (mean_residual - pr) / cap;

