    }

    // Harmonic classes: classify post_residual into capacity-fraction classes
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c / 4.0;

    // Dead-space penalty for residuals too small to be useful (below smallest item class)
