    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;

    // Mean residual coupling: prefer bins near the mean residual (balanced usage)
    score += (pr - mean_residual).abs() * 0.3;

    // Too many open bins: discourage spreading
    if open_bins_count > 8 {
        score += 5.0;
    }

    score
}

