            score -= 60.0; // perfect next-item fit
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64); // next item still fits
        } else {
            score += 10.0 + diff; // dead space relative to next item
        }
        // Bonus when this placement leaves room for both next item and a margin
        if post_residual >= next_item_size && post_residual - next_item_size >= 10 {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize waste.
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: bins with residuals below mean are more
    // valuable to fill; bins above mean are natural targets for dumping.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize new-bin candidate when decent fitting bins exist.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size >= 50 {
            score -= 5.0; // big item: fresh bin is fine
        } else {
            score += 15.0; // prefer filling open bins for small items
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Many open bins: encourage consolidation into emptier bins.
    if open_bins_count > 4 {
        score += 0.1 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if post_residual exactly accommodates next item,
    // penalize post_residual that is just barely too small for next item (dead space).
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap == 0.0 {
            score -= 20.0; // perfect chain fit
        } else if gap > 0.0 {
            score -= 6.0 * (1.0 - gap / bin_capacity as f64); // next item still fits
        } else {
            // dead space relative to lookahead: penalize proportionally to wasted room
            score += 0.15 * (-gap);
        }
    }

    // Time horizon: early in stream, keep bins flexible (mild penalty for very low residual);
    // late in stream, prioritize packing tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        score += 0.05 * post_residual as f64 * (1.0 - progress / 0.3);
    } else {
        score -= 5.0 * progress;
    }

    // Global state: many open bins -> favor consolidation (reward filling existing bins).
    if open_bins_count > 3 {
        score -= (open_bins_count as f64).ln() * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Mean residual coupling: prefer bins whose residual is below the mean (tighter than average)
    // to balance residual distribution, avoiding many half-empty bins.
    let dev = mean_residual - post_residual as f64;
    score += 0.08 * dev;

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count > 0 && post_residual + item_size >= bin_capacity / 2 {
            score += 10.0; // extra penalty when a reasonable existing bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
