pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual (chained packing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly-ish: reward tighter matches
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leaving a large unusable gap
            let gap = post_residual as f64;
            score += 0.3 * gap;
            if gap < 10.0 {
                score -= 20.0; // small dead space is acceptable
            }
        }
    }

    // Compare post residual against mean residual: prefer bins left below mean (balance)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin if existing fits are terrible
    if bin_residual == bin_capacity {
        // neutral-ish baseline; make it slightly unattractive unless post_residual large
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin can chain next item well
        }
    }

    // Early in stream: be liberal with bins to build good residual structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
