        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Medium-small gaps: mild penalty, they may still fit tiny items.
        score += 5.0;
    }

    // Reward bins whose residual was already small (tight packing tendency).
    if bin_residual < 20 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + next_item_size as f64 * 0.3;
    }
    // If post residual is a dead gap relative to next item, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when nothing fits or pressure is high.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: open new bin
        } else {
            score += 80.0 + 10.0 * open_bins_count as f64; // prefer reusing open bins
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing ones.
    score += open_bins_count as f64 * 1.5;
    // Prefer bins with residual close to mean (balanced packing) slightly.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.2;

    score
}

