pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
    }

    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.4;

    // Lookahead coupling.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 48.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after < class_width {
                score -= 20.0 + 0.5 * (class_width - after) as f64;
            } else {
                score -= 12.0 + 0.1 * after as f64;
            }
            if post_residual % next_item_size == 0 {
                score -= 7.0;
            }
            if after <= 3 {
                score -= 13.0;
            } else if after >= 2 * next_item_size {
                score -= 14.0;
            } else if after >= next_item_size {
                score -= 10.0;
            } else if after < next_item_size {
                score += 4.0;
            }
            if after >= 3 && after <= 15 {
                score -= 3.5;
            }
            if after > 0 && (after as f64) <= mean_residual.max(1.0) {
                score -= 2.5;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if gap <= 8.0 {
                score += 3.0 + 0.5 * (8.0 - gap);
            }
        } else if bin_residual >= next_item_size {
            score -= 10.0;
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 44.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score -= (mean_residual - post_residual as f64) * 0.15;

    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        if post_residual >= 30 && post_residual <= 60 {
            let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 10.0;
            }
            if chain >= 2 * next_item_size {
                score -= 6.0;
            }
            if chain > 0 && chain % 10 == 0 {
                score -= 4.0;
            }
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
            if gap <= 20.0 && scarcity < 0.5 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
        }
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        // Combined: penalize mid-band dead space late in stream only when scarcity is high.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 && scarcity < 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
    }

    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: buckets by integer division on capacity fractions.
    let pr = post_residual as u32;
    let class = pr / 10; // harmonic class 0..10
    // Penalize dead-space classes: residuals that few item sizes (1..100) can use
    let usable = match class {
        0 => 0.0_f64,           // perfect fit, best
        1 => 0.5,               // residual 10-19: usable by most items
        2 => 1.5,
        3 => 3.0,
        4 => 5.0,
        5 => 7.0,               // residual 50-59: awkward middle
        6 => 6.0,
        7 => 4.0,
        8 => 2.5,
        9 => 1.0,
        _ => 0.0,               // empty new bin
    };
    score += usable * 2.0;

    // Modulo arithmetic on post_residual: residuals divisible by common sizes (10,20,25,50) are reusable
    let mod_bonus = if pr % 10 == 0 { 3.0 }
        else if pr % 20 == 0 { 2.5 }
        else if pr % 25 == 0 { 2.5 }
        else if pr % 50 == 0 { 2.0 }
        else if pr % 5 == 0 { 1.0 }
        else { 0.0 };
    score -= mod_bonus;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let tight = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - tight / cap);
        } else {
            // next item cannot use this residual: penalize leaving large residual
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Fraction of capacity used by this placement
    let fill = item_size as f64 / cap;
    score -= fill * 8.0;

    // Coupling with mean residual: prefer bins whose residual is near mean (keep spread tight)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Early stream: be greedy on fill; late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= fill * progress * 6.0;

    // Many open bins: discourage opening new ones
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 2.0 + 5.0;
    }

    score
}

