        score += 55.0;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // fresh bin useful for a bigger follow-up item
        }
    }

    // Penalize tiny dead space (fragmentation) nonlinearly
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight pressure to consolidate as stream progresses
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance boost: only bin that fits — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: bonus if next item fits in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 14.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Prefer bins with residuals below mean (compact bins), penalize outliers.
    score += 0.6 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: early in stream, be pickier about wasted space; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Many open bins: discourage opening new ones; favor consolidation.
