pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, mildly damped
    let mut score = pr;

    // Non-linear polynomial coupling: residual waste grows super-linearly
    score += 40.0 * pr_norm * pr_norm * (1.0 + 0.5 * progress);

    // Tight fit reward: strongly subtract when post_residual is small
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead coupling: penalize if next item fits well in post residual (keep space),
    // reward if next item would NOT fit (no reason to save space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
