    // late in the stream or when open bins are many
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64) / (1.0 + progress * 10.0);
        score = 55.0 + 20.0 * (1.0 - progress) - 2.0 * open_pressure.min(10.0);
