        // Avoid awkward 12..20% residuals when no chain is possible.
        if dead_ratio >= 0.12 && dead_ratio < 0.20 && stream_left2 > 0.5
            && (next_item_size == 0 || next_item_size > post_residual) {
            score += 3.0 * (dead_ratio - 0.12) * 50.0 * stream_left2;
        }
        // Reward exact multi-fit chains — residual divisible by next item
        // with at least two repetitions.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
        // Prefer bins whose post-residual can absorb next item AND leaves
        // a residual >= mean_residual (recyclable dead space).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= mean_residual.max(1.0) {
                score -= 1.5;
            }
        }
        // NEW: fine-grained coupling — when the post-residual is only
        // slightly above the next item, the leftover sliver is nearly
        // unfillable; penalize proportionally to stream remaining.
        if next_item_size > 0 && post_residual > next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < 6.0 {
                score += 4.0 * (6.0 - after) * stream_left2 * (1.0 - scarcity);
            }
        }
        // NEW: combine lookahead with scarcity — when few bins can fit the
        // item, prefer the bin that leaves the largest usable residual for
        // future items (post_residual >= item's share of capacity).
        if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= cap * 0.25 {
                score -= 3.0 * (1.0 - scarcity);
            }
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls into
    // "unusable" residue classes (small, awkward slivers).
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Penalize tiny slivers strongly (dead space that nothing can use).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward perfect fit.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo-class logic: residuals congruent to awkward classes relative to
    // common item sizes get penalized.
    let awkward = |r: u32| -> f64 {
        let mut pen = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50] {
            let rem = r % m;
            if rem > 0 && rem < 5 {
                pen += 3.0;
            }
        }
        pen
    };
    score += awkward(post_residual);

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nxt_rem = post_residual - next_item_size;
            // Prefer leaving residuals that are "harmonic" (divisible by common sizes)
            let mut bonus = 8.0;
            for m in [10u32, 20, 25, 50] {
                if post_residual % m == 0 {
                    bonus += 6.0;
                }
            }
            score -= bonus - awkward(nxt_rem);
        } else {
            // Next item cannot fit here; penalize slightly more if this is the last fitting bin.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity; make it
    // attractive only when the current fit is poor.
    if bin_residual == bin_capacity {
        // Empty bin: baseline score = full capacity, adjusted by stream position.
        score = cap - (item_size as f64);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // If many bins are open and mean residual is large, discourage new bin.
        score += 0.15 * open_bins_count as f64;
        if mean_residual > item_size as f64 + 5.0 {
            score += 15.0;
        }
        // If no open bin fits well (post_residual large relative), new bin ok.
        if post_residual > 0 && (post_residual as f64) < cap * 0.35 {
            score -= 20.0;
        }
    }

    // Coupling with mean residual: prefer bins tighter than average (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Fraction-of-capacity fill reward: high fill ratio is good.
    let fill_ratio = (bin_capacity - post_residual) as f64 / cap;
    score -= 10.0 * fill_ratio;

    score
}

