    }

    // Endgame: squeeze the last bins hard.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    let min_size = 1u32;
    if post_residual < min_size {
        score -= 500.0; // perfect fit, ideal
    } else if post_residual < 10 {
        // Unusable dead space: penalize heavily, worse the closer to full-but-unusable.
        score += (10 - post_residual) as f64 * 40.0;
    } else {
        // Usable residual: reward tightness mildly.
        score -= (bin_capacity - post_residual) as f64 * 0.15;
    }

    // Reward exact residual matches with lookahead item (k=2 chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Leaving enough room for next item is good, but not excessively more.
        score -= 15.0;
    } else if next_item_size > 0 {
        // Next item cannot fit here afterwards: slight penalty.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: discourage proliferation of open bins unless residual is attractive.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are already open, unless this is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 + open_pressure * 3.0 - progress * 30.0;
        // New bin is attractive if mean residual of open bins is small (they are all crammed).
        score -= (mean_residual - 20.0).max(0.0) * 1.5;
    } else {
        // Using an existing bin relieves pressure.
        score -= open_pressure * 0.8;
        // Prefer bins whose residual is below mean (tighter bins first).
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

