            }
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
            if gap <= 20.0 && scarcity < 0.5 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
