    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward, amplified late in the stream.
    if post_residual == 0 {
        score -= 40.0 + 60.0 * progress;
    }

    // Small dead space is worse than it looks: quadratic penalty on tiny residuals,
    // scaled by stream progress (dead space matters more as stream matures).
    let pr = post_residual as f64;
    let small_dead = (1.0 - pr / bin_capacity as f64).powi(3);
    score -= 12.0 * small_dead * (0.5 + progress);

    // Lookahead coupling: reward if next item fits in post_residual (chain packing),
    // penalize if next item almost fits (near-miss creates temptation waste).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 * tightness * (0.3 + 0.7 * progress);
        } else {
            let miss = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25) * (1.0 - progress);
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only when
    // open bins have poor fits; the penalty grows with number of open bins.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    } else {
        // Prefer bins with residuals close to item_size (tight fit) among open bins.
        let tight = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 5.0 * tight * tight;
    }

    // Smooth coupling with mean residual: favor bins deviating below the mean
    // (filling the emptiest-ish bins first keeps a spread of usable residuals).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild non-linear progress tilt: slightly prefer consolidation early,
    // aggressive filling late.
    score *= 1.0 - 0.1 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

