pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect match with the next item (2-step lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // ideal: next item fills this bin exactly
        } else if post_residual > next_item_size {
            // residual left for next item, penalize leftover after that hypothetical placement
            let second_leftover = post_residual - next_item_size;
            score += second_leftover as f64 * 0.6;
            if second_leftover < 10 {
                score -= 15.0; // near-perfect two-step chain
            }
        } else {
            // next item cannot fit here; penalize proportionally to the gap
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.35;
        }
    } else {
        // last item: prefer tightest fit
        score += post_residual as f64 * 0.5;
    }

    // Penalize dead space below typical minimum item size (1..100 range: harsh below ~15).
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Reward using bins whose residual is already below average (consolidating space).
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Mild preference for keeping the number of open bins low when many are open.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Early in the stream, be slightly more willing to open fresh bins (spread items).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if no open bin offers a tight fit.
        let tightness = post_residual as f64; // = capacity - item for new bin
        score = tightness - 25.0 * (1.0 - progress) - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size as f64 <= tightness as f64 {
            score -= 20.0; // fresh bin can also host next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small waste relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves more slack: mild reward scaled by fit quality.
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * (1.0 - slack);
        } else {
            // Next item won't fit here: penalize bins that hoard large residuals
            // when the next item is big.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when existing bins
    // offer bad fits. Penalize the new bin by the mean residual of open bins
    // (if open bins have lots of space, avoid opening new ones).
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * mean_residual + 2.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is less costly (fewer future items
        // to fill them), so discount the penalty over time.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
    } else {
        // Existing bin: mild preference to keep bins consolidated when many are open.
        score += 0.05 * open_bins_count as f64;
    }

    // Penalize leaving awkward small residuals (dead space that few items can use).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Time-horizon coupling: early in the stream, avoid fragmenting capacity
    // since many items remain; late, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.2 * post_residual as f64;

    // Compare against mean residual: bins far from the mean residual may be
    // either very full (good) or very empty (wasteful to use for big items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

