    // only when open bins are crowded or fit is poor.
    let is_new = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new {
        // base: neutral-ish; adjust with state
        score -= 5.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0 * (1.0 - progress);
        }
        if open_bins_count > 8 {
            score += (open_bins_count as f64 - 8.0) * 2.0;
        }
        if fitting_bins_count > 0 && post_residual < 20 {
            score += 25.0; // don't open new bin when a decent fit exists
