            if gap == 0.0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: penalize dead space relative to next item
            score += 0.35 * (nxt - post).min(nxt);
        }
    }

    // Relative to mean residual: placing in a bin tighter than average is good
    score += 0.5 * (mean_residual - post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = post > 45.0 || (next_item_size > 0 && (next_item_size as f64) > post && post > 25.0);
        if bad_fit {
            score -= 18.0 + 10.0 * progress;
        } else {
            score += 30.0;
        }
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
