        if pr % 25 == 0 { score -= 2.0; }
    } else {
        // Dead space below minimum item size: penalize.
        score += 40.0;
    }

    // If the next item fits exactly into the post residual, big reward
    // (chained perfect fit).
    if next_item_size > 0 && next_item_size == pr {
        score -= 60.0;
    }
    // If next item fits but post residual would be dead for it, slight penalty
    if next_item_size > 0 && next_item_size <= pr && (pr - next_item_size) < 10 && pr - next_item_size > 0 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // or open bins would leave large waste. Penalize mildly by default so
    // existing bins win, but relax as stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 10.0 * progress;
        // If item is large, a fresh bin is fine.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer bins below mean residual (tighter bins first).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Slight preference for filling fuller bins (capacity fraction).
    score -= 0.2 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 120.0;
        }
    } else if post_residual <= bin_capacity / 5 {
        score += 20.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 4.0;
    } else {
        score -= 18.0;
    }

    // Exact lookahead match: perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0;
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0;
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
                score -= 12.0 + 0.15 * (pr - nxt);
            }
            if after >= nxt {
                score -= 10.0;
                if after >= 2.0 * nxt {
                    score -= 6.0;
                }
            }
            if nxt > 0 && (pr as u32) % (nxt as u32) == 0 {
                score -= 7.0;
            }
            if after > 0.0 && after <= mean_residual.max(1.0) {
                score -= 4.0;
            }
            if after >= 3.0 && after <= 15.0 {
                score -= 3.5;
            }
            if after > 0.0 && after % nxt.max(1.0) == 0.0 && after >= nxt {
                score -= 2.0 + 0.15 * (after / nxt);
            }
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
            // Two-item lookahead: residual after placing next item should be
            // zero or absorbable by the average open bin.
