        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are 1..=100, so gaps < 10 are almost certainly dead).
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 12.0;
    } else if post_residual < 25 {
        // Moderately risky gap, mild penalty scaled by how tight it is.
        score += (25.0 - pr) * 1.5;
    }

    // Reward leaving room for the known next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + next_item_size as f64 * 0.5;
    }
    // Penalize if this bin could have fit the next item but placement breaks it.
    if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    let pressure = open_bins_count as f64;
    if bin_residual != bin_capacity {
        score -= pressure * 2.0;
    } else {
        // New-bin candidate: penalize when open bins are fragmented,
        // reward when current bins are mostly full (high mean fill).
        let mean_fill = bin_capacity as f64 - mean_residual;
        score += pressure * 1.5 - mean_fill * 0.8;
        // Late in the stream, avoid spawning extra bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Slight preference for bins with least residual among equals (tightness).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

