pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 defines "dead space" quality.
    let post_class = post_residual % 10;
    // Residuals near multiples of 10 pair well with common item sizes; reward them.
    if post_class == 0 {
        score -= 12.0;
    } else if post_class <= 3 || post_class >= 7 {
        score += 4.0; // awkward dead space
    }

    // Integer-division thresholds: post_residual bucketed by 20s.
    let bucket = post_residual / 20;
    score -= bucket as f64 * 3.0; // larger usable residual preferred

    // Perfect-fit reward: post_residual exactly 0 is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does next item fit exactly in post_residual?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
        // Harmonic pair: post_residual + next_item_size near capacity multiple
