        if sum % bin_capacity == 0 {
            score -= 20.0;
        } else if sum > bin_capacity {
            score += (sum - bin_capacity) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but reward it late in the stream when many bins are open (consolidation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - 10.0 * progress;
        if open_bins_count > 4 && mean_residual > item_size as f64 {
            score += 6.0; // plenty of room elsewhere; avoid new bin
        }
    }

