        score += 12.0 + 0.25 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward bins whose residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
