            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < next_item_size as f64 && after > mean_residual.max(1.0) {
                score += 3.0 * (1.0 - after / (next_item_size as f64)) * (1.0 - progress);
            }
        }
        // Avoid awkward 12..20% residuals when no chain is possible.
        if dead_ratio >= 0.12 && dead_ratio < 0.20 && stream_left2 > 0.5
            && (next_item_size == 0 || next_item_size > post_residual) {
            score += 3.0 * (dead_ratio - 0.12) * 50.0 * stream_left2;
        }
        // Reward exact multi-fit chains — residual divisible by next item
        // with at least two repetitions.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
        // Prefer bins whose post-residual can absorb next item AND leaves
        // a residual >= mean_residual (recyclable dead space).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= mean_residual.max(1.0) {
                score -= 1.5;
            }
        }
        // When many items remain, prefer bins whose post-residual is a
        // multiple of a common small size (5 or 10) — easier future packing.
        if stream_left2 > 0.4 && post_residual % 10 == 0 {
            score -= 1.5;
        } else if stream_left2 > 0.4 && post_residual % 5 == 0 {
            score -= 0.8;
        }
        // Late stream — strongly prefer tightest bins regardless of band.
        if stream_left2 < 0.25 {
            score += 0.08 * post_residual as f64;
        }
        // Combined coupling — when the stream is far from over and the
        // next item cannot use the leftover, penalize residuals that no
        // plausible future item (next item ± 10) can absorb either.
        if stream_left2 > 0.5 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < 10.0 {
                score -= 2.0 * (1.0 - after / 10.0) * stream_left2;
            }
        }
        // NEW: dead-space coupling — penalize residuals that are too small
        // for the next item yet exceed the mean absorbable residual, scaled
        // by how many items remain (likely permanent waste).
        if next_item_size > 0 && post_residual < next_item_size
            && post_residual as f64 > mean_residual.max(1.0) * 1.5 && stream_left2 > 0.3 {
            score += 2.0 * (1.0 - dead_ratio) * stream_left2;
        }
        // NEW: reward residuals in the 20..35% band when the next item can
        // chain into them and leave an absorbable remainder.
        if dead_ratio >= 0.20 && dead_ratio < 0.35 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after == 0.0 || after <= mean_residual.max(1.0) {
                score -= 4.0 * (1.0 - scarcity);
            }
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals in [1, 9] are practically unusable
    // for typical items (min size 1..100 unknown, but small gaps rarely match).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit bonus: strongly reward leaving exactly 0 residual.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item exactly fits the post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        // Partial reward if next item still fits in the gap.
        score -= 5.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; prefer
    // filling existing bins and penalize opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual.
        score += 10.0 + 2.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // If nothing else fits well, a new bin may still win; soften slightly
        // late in the stream when consolidation matters less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    } else {
        // Reward placing into bins with larger residual (best-fit family),
        // modulated by open bins count to close bins faster.
        score -= 0.1 * open_bins_count as f64;
    }

    // Slight preference for bins already below mean residual (balance avoidance
    // of many half-empty bins).
    if bin_residual != bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

