            score -= 8.0; // all bins nearly full: new bin is fine
        } else {
            score += 15.0 + 20.0 * crowdedness; // discourage abandoning usable space
        }
        // Early in the stream, having a fresh bin available is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
