        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 25.0 * (1.0 - gap / cap);
        } else {
            score += 12.0 * (-gap / cap);
        }
    }

    // Penalize bins deviating from mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 3.0 * dev * dev / cap;

    // New-bin candidate: mildly discouraged unless residual structure suggests it
    score += is_new_bin * (20.0 + 30.0 * progress);

    // Fewer open bins: slight preference to consolidate into existing bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
