            && post_residual as f64 > mean_residual.max(1.0) * 1.5 && stream_left2 > 0.3 {
            score += 2.0 * (1.0 - dead_ratio) * stream_left2;
        }
        // Reward residuals in the 20..35% band when the next item can
        // chain into them and leave an absorbable remainder.
        if dead_ratio >= 0.20 && dead_ratio < 0.35 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after == 0.0 || after <= mean_residual.max(1.0) {
                score -= 4.0 * (1.0 - scarcity);
            }
        }
        // NEW: when the stream is young and open bins are plentiful, mildly
        // discourage creating residuals below the next item size that the
        // mean residual also cannot absorb — double-dead space.
        if stream_left2 > 0.6 && next_item_size > 0 && post_residual < next_item_size
            && (post_residual as f64) > mean_residual.max(1.0) && fitting_bins_count >= 3 {
            score += 1.5 * (1.0 - dead_ratio);
        }
        // NEW: late-stream tight-fit squeeze — when few items remain, boost
        // preference for the very smallest non-zero post-residuals.
        if stream_left2 < 0.35 && dead_ratio < 0.06 {
            score -= 4.0 * (1.0 - dead_ratio / 0.06);
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
