    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" residue
    // classes (multiples of common small item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let harmonic_bonus = if pr % 10 == 0 { 6.0 }
            else if pr % 5 == 0 { 3.0 }
            else if pr % 2 == 0 { 1.0 }
            else { -2.0 };
        score -= harmonic_bonus;
    }

    // Penalize dead space: leftover too small for the smallest plausible item (1..100 range,
    // but below ~10 it is nearly unusable).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this leftover: penalize proportional to waste class
            score += (next_item_size - pr).min(20) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        // Opening a bin is penalized more as pressure/mean residual grows.
        score += 30.0 + 15.0 * (1.0 - progress) + 10.0 * tight_pressure.min(2.0);
        // But if the item is large relative to typical residual, opening may be wise.
        if item_size as f64 > mean_residual {
            score -= 18.0;
        }
    }

    // Fractional-capacity threshold: bins with residual in the top quartile of capacity
    // are "roomy"; mildly prefer filling them to consolidate.
    if bin_residual * 4 >= bin_capacity * 3 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Tight-bin preference: residual barely above item size is a great fit.
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.15;

    // Mean-residual drift: if this bin is far above mean residual, deprioritize slightly
    // (keeps residuals balanced, preserves small bins for small items).
    score += ((bin_residual as f64 - mean_residual) * 0.05).max(-5.0).min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Gap is "dead" if no plausible future item fits it (items >= 1, but
        // typical item sizes suggest gaps below ~10 are nearly useless).
        if post_residual < 10 {
            score += 60.0 + (10.0 - post_residual as f64) * 8.0;
        } else if post_residual < 25 {
            score += 20.0 + (25.0 - post_residual as f64) * 2.0;
        } else {
            // Larger gaps are reusable; slight superlinear penalty anyway.
            score += (post_residual as f64).powf(1.15) * 0.05;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 35.0;
        } else if slack < 10 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Next item won't fit and gap is dead: extra penalty.
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // with few open bins, opening a fresh bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above well-fitting existing bins.
        score += 10.0 + pressure - 15.0 * (1.0 - progress);
    } else {
        // Prefer bins whose residual is close to the item (tight fits).
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    // Mean residual coupling: bins far below the mean residual waste space elsewhere.
    score += (mean_residual - bin_residual as f64) * 0.08;

    score
}

