            }
            // Fresh bin residual >= next item (chainable) is better than
            // a fresh bin that strands space when the stream is young.
            let progress1 = step_index as f64 / total_items.max(1) as f64;
            if next_item_size > 0 && post_residual >= next_item_size && progress1 < 0.7 {
                score -= 4.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 27.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Consolidation pressure early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mid-band residual (30..60) packs well with typical sizes.
    if post_residual >= 30 && post_residual <= 60 {
        let remaining = (total_items - step_index) as f64;
        let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
        score -= 5.0 + 3.0 * stream_left;
    }

    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Sharp penalty for the 5..12% sliver band.
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band attraction toward center.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Chain into small residual in the 10..18% band.
        if dead_ratio > 0.10 && dead_ratio < 0.18 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
        }
        // Mid-range dead space early in stream: penalize mildly.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
        // Tiny residual left after chaining next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
        }
        // Hard-to-fill residual with few fitting bins: avoid creating it.
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 2.5 * (0.08 - dead_ratio) * 100.0;
        }
        // Wide-open bins with next item smaller: strong chain candidate.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // Gap-based penalty when next item doesn't fit.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
        // Divisibility bonus.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        // Small-residual avoidance when many bins can still fit.
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        // Penalize residuals that neither the next item nor the mean open-bin
        // residual can absorb (dead-space coupling fix).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < next_item_size as f64 && after > mean_residual.max(1.0) {
                score += 3.0 * (1.0 - after / (next_item_size as f64)) * (1.0 - progress);
            }
        }
        // Avoid awkward 12..20% residuals when no chain is possible.
        if dead_ratio >= 0.12 && dead_ratio < 0.20 && stream_left2 > 0.5
            && (next_item_size == 0 || next_item_size > post_residual) {
            score += 3.0 * (dead_ratio - 0.12) * 50.0 * stream_left2;
        }
        // Reward exact multi-fit chains — residual divisible by next item
        // with at least two repetitions.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
        // Prefer bins whose post-residual can absorb next item AND leaves
        // a residual >= mean_residual (recyclable dead space).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= mean_residual.max(1.0) {
                score -= 1.5;
            }
        }
        // When many items remain, prefer bins whose post-residual is a
        // multiple of a common small size (5 or 10) — easier future packing.
        if stream_left2 > 0.4 && post_residual % 10 == 0 {
            score -= 1.5;
        } else if stream_left2 > 0.4 && post_residual % 5 == 0 {
            score -= 0.8;
        }
        // Late stream — strongly prefer tightest bins regardless of band.
        if stream_left2 < 0.25 {
            score += 0.08 * post_residual as f64;
        }
        // Combined coupling — when the stream is far from over and the
        // next item cannot use the leftover, penalize residuals that no
        // plausible future item (next item ± 10) can absorb either.
        if stream_left2 > 0.5 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < 10.0 {
                score -= 2.0 * (1.0 - after / 10.0) * stream_left2;
            }
        }
        // Dead-space coupling — penalize residuals that are too small
        // for the next item yet exceed the mean absorbable residual, scaled
        // by how many items remain (likely permanent waste).
        if next_item_size > 0 && post_residual < next_item_size
            && post_residual as f64 > mean_residual.max(1.0) * 1.5 && stream_left2 > 0.3 {
            score += 2.0 * (1.0 - dead_ratio) * stream_left2;
        }
        // Reward residuals in the 20..35% band when the next item can
        // chain into them and leave an absorbable remainder.
        if dead_ratio >= 0.20 && dead_ratio < 0.35 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after == 0.0 || after <= mean_residual.max(1.0) {
                score -= 4.0 * (1.0 - scarcity);
            }
        }
        // NEW: strong extra reward for multi-repetition chains — residual
        // that can hold the next item twice or more with zero remainder.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 && stream_left2 > 0.3 {
            score -= 4.0 * stream_left2;
        }
        // NEW: when the next item nearly fills the post-residual (gap <= 3),
        // this bin is one stream step from closing — reward it.
        if next_item_size > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) <= 3 {
            score -= 6.0 * (1.0 - (next_item_size - post_residual) as f64 / 4.0);
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // penalize dead space that blocks the next item
            let waste_ratio = post_residual as f64 / next_item_size.max(1) as f64;
            score += waste_ratio * 6.0;
        }
    } else {
        // last item: prefer zero residual strongly
        score -= tightness * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing ones
    let open_pressure = open_bins_count as f64 / (1.0 + step_index as f64).sqrt();
    score -= open_pressure * 2.5;

    // Compare against mean residual: bins with residual near mean are "typical" targets
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate handling: only open a new bin when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins more when many bins are open or fit exists elsewhere
        score += 30.0 + open_bins_count as f64 * 3.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 10.0; // fresh bin can't host next item either
        }
        let _ = progress;
    }

    // Time horizon: late in stream, be greedier about tight fits
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= tightness * t * 15.0;

    // Penalize leaving residuals that are awkward (small but nonzero)
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: never waste this bin again.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
    }

    // Harmonic class of post_residual.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Modulo-10 class of post_residual.
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.4;

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 48.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after < class_width {
                score -= 20.0 + 0.5 * (class_width - after) as f64;
            } else {
                score -= 12.0 + 0.1 * after as f64;
            }
            if post_residual % next_item_size == 0 {
                score -= 7.0;
            }
            if after <= 3 {
                score -= 13.0;
            } else if after >= 2 * next_item_size {
                score -= 14.0;
            } else if after >= next_item_size {
                score -= 10.0;
            } else {
                score += 4.0;
            }
            if after >= 3 && after <= 15 {
                score -= 3.5;
            }
            // Residue left after the lookahead can be absorbed by another open bin.
            if after > 0 && (after as f64) <= mean_residual.max(1.0) {
                score -= 2.5;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if gap <= 8.0 {
                score += 3.0 + 0.5 * (8.0 - gap);
            }
        } else if bin_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 44.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            // Open a fresh bin eagerly late in the stream when open bins are mostly tiny leftovers.
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer bins below the mean residual.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Small-residue dead-space shaping.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);

        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }

        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }

        // Mid-band residue (30-60) is valuable for medium items.
        if post_residual >= 30 && post_residual <= 60 {
            let remaining = (total_items - step_index) as f64;
            let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
            score -= 4.0 + 3.0 * stream_left;
        }

        // Chained fits: post_residual can host next item multiple times.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 10.0;
            }
            if chain >= 2 * next_item_size {
                score -= 6.0;
            }
            if chain > 0 && chain % 10 == 0 {
                score -= 4.0;
            }
        }

        // Tight-gap penalty when next item nearly fits.
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
            if gap <= 20.0 && scarcity < 0.5 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }

        // Attractor band around 0.325 capacity.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }

        // Small leftovers after placing next item.
        if dead_ratio > 0.10 && dead_ratio < 0.18 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
        }

        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
        }

        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 2.0 * (0.08 - dead_ratio) * 100.0;
        }

        if next_item_size > 0 && post_residual > next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
        }

        if dead_ratio > 0.48 && fitting_bins_count <= 2 && next_item_size as f64 > post_residual as f64 {
            score += 3.0 * (dead_ratio - 0.48) * 20.0;
        }

        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }

        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }

        // Penalize mid-range dead space when much of the stream remains.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
    }

    // Endgame: strongly prefer filling existing bins tightly.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let smooth = progress * progress * (3.0 - 2.0 * progress);

    // Non-linear penalty on wasted residual: dead space matters quadratically.
    score += (post / cap) * (post / cap) * (30.0 + 40.0 * smooth);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - post / cap) * (1.0 - post / cap) * (8.0 + 12.0 * smooth);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * smooth;
    }

    // Lookahead coupling: if next item exactly fills the post residual, reward.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= (1.0 - gap / cap).max(0.0) * (6.0 + 10.0 * smooth);
        // Penalize leaving residual too small for next item (dead space creation).
        if next_item_size as f64 > post && post > 0.0 {
            score += (next_item_size as f64 - post) * (0.3 + 0.4 * smooth);
        }
    }

    // Prefer bins below mean residual (consolidating waste) via smooth coupling.
    score += ((post - mean_residual) / cap) * (4.0 + 6.0 * smooth);

    // Mild pressure against proliferating bins late in stream.
    score += (open_bins_count as f64 / (1.0 + open_bins_count as f64)) * (3.0 * smooth);

    score
}

