pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let base = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let norm_post = base / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = base;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + progress) - norm_post * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits more aggressively as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 20.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let waste = (next_item_size as f64 - base).min(cap);
        score += 6.0 * waste * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 && base >= norm_next * cap {
        // Smooth reward when post residual still accommodates next item
        score -= 4.0 * (1.0 - (base - norm_next * cap) / cap);
    }

    // Last-chance bin bonus (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure toward consolidating into few bins
    score += 0.3 * open_bins_count as f64 * norm_post;

    // Deviation from mean residual: prefer bins near mean to balance load
    score += 0.5 * (base - mean_residual).abs() * (1.0 - progress);

    // New-bin candidate: penalize slightly so open bins are preferred unless very poor fit
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress) - 5.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 120.0;
        }
    } else if post_residual <= bin_capacity / 5 {
        score += 20.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 4.0;
    } else {
        score -= 18.0;
    }

    // Exact lookahead match: perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0;
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0;
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
                score -= 12.0 + 0.15 * (pr - nxt);
            }
            if after >= nxt {
                score -= 10.0;
                if after >= 2.0 * nxt {
                    score -= 14.0;
                }
                if after >= 3.0 * nxt {
                    score -= 6.0;
                }
            }
            if nxt > 0 && (pr as u32) % (nxt as u32) == 0 {
                score -= 7.0;
            }
            if after > 0.0 && after <= mean_residual.max(1.0) {
                score -= 6.0;
            }
            if after >= 3.0 && after <= 15.0 {
                score -= 3.5;
            }
            if after > 0.0 && after % nxt.max(1.0) == 0.0 && after >= nxt {
                score -= 2.0 + 0.15 * (after / nxt);
            }
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
            // Two-item lookahead: residual after placing next item should be
            // zero or absorbable by the average open bin.
            if after > 0.0 && after < cap * 0.5 {
                let frac = after / cap;
                if (frac * 10.0).round() as i32 <= 1 {
                    let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                    score -= 2.5 * (1.0 - frac * 10.0) * (1.0 - scarcity);
                }
            }
            // Penalize chains that leave a mid-range residual far above the
            // mean absorbable residual — likely permanent dead space.
