    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0) * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive when open bins have poor residuals
    // relative to the item, or late in the stream with many bins.
    if bin_residual == bin_capacity {
