pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses
    let tight = (fill * fill) * (1.0 + 2.0 * prog);
    score -= 8.0 * tight;

    // Penalize dead space quadratically, scaled by stream progress
    let dead = (pr / cap).powi(2);
    score += 6.0 * dead * (0.5 + prog);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let nx = next_item_size as f64 / cap;
        score -= 4.0 * nx * (1.0 - nx);
    }

    // New-bin candidate: penalize opening a bin unless current residual is unusable
    if bin_residual == bin_capacity {
        let unusable = (pr / cap).powi(2);
        score += 3.0 + 10.0 * (1.0 - unusable) - 4.0 * prog;
        if fitting_bins_count > 0 {
            score += 4.0;
        }
    }

