        }
        if pr % 20 == 0 {
            score -= 4.0;
        }
        if pr % 25 == 0 {
            score -= 3.0;
        }
        // Penalize tiny dead-space classes
        if pr < 10 {
            score += 15.0 * (1.0 - pr as f64 / 10.0);
        }
        // Mid-range awkward residuals (11..=19) are semi-dead
        if pr >= 11 && pr <= 19 {
            score += 5.0;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly/nicely?
