    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_cap = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                && mean_residual < next_item_size as f64 * 1.15
                && (fitting_bins_count as f64) < 4.0)
                || (total_fit_cap < next_item_size as f64 * 2.0
                    && fitting_bins_count <= 1));
        if big_item || crowded || next_needs_fresh {
            score -= 50.0;
        } else {
            score += 55.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
            // NEW: if total leftover capacity can absorb the next item, prefer open bins.
            if next_item_size > 0
                && open_bins_count > 0
                && total_fit_cap >= next_item_size as f64 * 2.5
                && mean_residual >= next_item_size as f64
            {
                score += 6.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 28.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Consolidation pressure early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mid-band residual (30..60) tends to pack well with typical sizes.
    if post_residual >= 30 && post_residual <= 60 {
        let remaining = (total_items - step_index) as f64;
        let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
        score -= 4.0 + 3.0 * stream_left;
    }

    // Dead-space shaping.
    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Sharp penalty for the 5..12% sliver band (hardest to fill later).
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band (20..45%) attraction toward center when next item can't fill it.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Chain into small residual in the 10..18% band.
        if dead_ratio > 0.10 && dead_ratio < 0.18 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
        }
        // Mid-range dead space early in stream: penalize mildly.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
        // Tiny residual left after chaining next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
            if after > 0.0 && after % 10 == 0 && after <= 40 {
                score -= 2.0 * (1.0 - scarcity);
            }
        }
        // Sliver band with few fitting bins: strongly discourage.
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 4.0 * (0.08 - dead_ratio) * 100.0 * 0.5;
        }
        // Reward bins that can still absorb a small extra item after chaining.
        if next_item_size > 0 && post_residual > next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
        }
        // 45-55% band with scarce fits and small next item: attract.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // Next item can't fit here with few fits: mild penalty scaled by fill.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
        // Wide-open bins with many fits: mild attraction to consolidate there.
        if dead_ratio > 0.15 && fitting_bins_count >= 4 {
            score -= 2.0 * (dead_ratio - 0.15) * 10.0 * scarcity;
        }
        // Penalize slivers that even after chaining leave a tiny unusable remainder
        if next_item_size > 0 && post_residual >= next_item_size {
            let after2 = (post_residual - next_item_size) as f64;
            let frac = after2 / cap;
            if after2 > 0.0 && frac < 0.10 {
                score += 3.0 * (0.10 - frac) * 10.0 * (1.0 - scarcity);
            }
        }
        // Divisible residual by next item is a clean chain.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size && post_residual > 0 {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        // Many fitting bins and low dead ratio: discourage (use tighter bins first).
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        // NEW: high dead-ratio bins (>0.6) with many fits: attract strongly to avoid
        // leaving huge empty bins open at the end.
        if dead_ratio > 0.60 && fitting_bins_count >= 3 {
            score -= 4.0 * (dead_ratio - 0.60) * 10.0;
        }
        // NEW: residual exactly in the 12..20% band is a good landing zone for mid items;
        // reward when the next item is small enough to fit elsewhere anyway.
        if dead_ratio >= 0.12 && dead_ratio < 0.20 && next_item_size > 0 && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for the smallest plausible
    // future item are nearly worthless — punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (exact or near-exact packing).
    if post_residual == 0 {
        score -= 80.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 40.0 * tightness * tightness;
    }

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual > next_item_size {
            let nxt_left = post_residual - next_item_size;
            if nxt_left < 10 {
                score += 20.0; // would create dead space after next item
            } else {
                score -= 15.0;
            }
        }
        // If next item cannot fit here anyway, slight penalty for hoarding space.
        if next_item_size > post_residual && post_residual < 15 {
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it only
    // when open-bin fits are poor; otherwise penalize it to consolidate load.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        // Base cost of opening a new bin, reduced when many bins already open
        // (fragmentation already high, consolidation less valuable).
        score += 45.0 - pressure.min(30.0);
        // If existing bins fit poorly (large mean residual but many bins), allow new bin.
        if mean_residual > 45.0 && fitting_bins_count <= 2 {
            score -= 55.0;
        }
        // Late in the stream, prefer using existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Open-bin count pressure: mildly discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins whose residual is close to what we consume (good global matching).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 120.0;
        }
    } else if post_residual <= bin_capacity / 5 {
        score += 20.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 4.0;
    } else {
        score -= 18.0;
    }

    // Exact lookahead match: perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0;
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0;
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
                score -= 12.0 + 0.15 * (pr - nxt);
            }
            if after >= nxt {
                score -= 12.0;
                if after >= 2.0 * nxt {
                    score -= 9.0;
                }
            }
            if nxt > 0 && (pr as u32) % (nxt as u32) == 0 {
                score -= 7.0;
            }
            if after > 0.0 && after <= mean_residual.max(1.0) {
                score -= 6.0;
            }
            if after >= 3.0 && after <= 15.0 {
                score -= 3.5;
            }
            if after > 0.0 && after % nxt.max(1.0) == 0.0 && after >= nxt {
                score -= 2.0 + 0.15 * (after / nxt);
            }
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
            // Two-item lookahead: residual after placing next item should be
            // zero or absorbable by the average open bin.
            if after > 0.0 && after < cap * 0.5 {
                let frac = after / cap;
                if (frac * 10.0).round() as i32 <= 1 {
                    let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                    score -= 3.0 * (1.0 - frac * 10.0) * (1.0 - scarcity);
                }
            }
            // Penalize chains that leave a mid-range residual far above the
            // mean absorbable residual — likely permanent dead space.
            if after > 0.0 && after >= mean_residual.max(1.0) * 2.0 && after <= cap * 0.35 {
                score += 3.0 * (after / cap);
            }
            // Penalize chains leaving a residual that is neither absorbable
            // by the mean open-bin residual nor by the next item itself.
            if after > 0.0 && after < nxt && after > mean_residual.max(1.0) {
                score += 4.0 * (1.0 - after / nxt) * (1.0 - ((fitting_bins_count as f64) / 5.0).min(1.0));
            }
            // Triple-chain bonus — residual divisible by next item with
            // room for at least two more of the same size.
            if after >= 2.0 * nxt && (pr as u32) % (next_item_size) == 0 {
                score -= 6.0;
            }
            // Chain that leaves a residual divisible by 10 is easily
            // reusable by typical stream sizes.
            if after > 0.0 && after % 10.0 == 0.0 {
                score -= 2.5;
            }
        } else {
            let gap = nxt - pr;
            if gap <= 8.0 {
                score += 60.0 + 6.0 * (8.0 - gap);
            } else {
                score += 25.0 * (1.0 - pr / nxt.max(1.0));
            }
            if gap <= 15.0 {
                let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
            if gap <= 20.0 && ((fitting_bins_count as f64) / 5.0).min(1.0) < 0.5 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }
    }

    // Relative-to-mean: prefer tighter-than-average bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance: only fitting bin -> keep item out of a new bin.
    if fitting_bins_count == 1 {
        score -= 160.0;
    } else if fitting_bins_count == 0 {
        score += 80.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_cap = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                && mean_residual < next_item_size as f64 * 1.15
                && (fitting_bins_count as f64) < 4.0)
                || (total_fit_cap < next_item_size as f64 * 2.0
                    && fitting_bins_count <= 1));
        if big_item || crowded || next_needs_fresh {
            score -= 55.0;
        } else {
            score += 70.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
            // Fresh-bin capacity check: open bins collectively cannot absorb
            // the current item plus the next one.
            if open_bins_count > 0 && next_item_size > 0 {
                if total_fit_cap < (item_size + next_item_size) as f64 * 0.9 {
                    score -= 14.0;
                }
            }
            // Fresh bin leaving a residual exactly matching the next item is
            // a perfect chain — reward strongly.
            if next_item_size > 0 && post_residual == next_item_size {
                score -= 45.0;
            }
            // Fresh bin leaves a residual the next item almost fills: good.
            if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
                score -= 18.0;
            }
            // Fresh bin whose post-residual is a multiple of the next item
            // enables a clean multi-item chain — reward.
            if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
                score -= 6.0;
            }
            // Fresh bin residual exactly matching a common small size.
            if post_residual % 10 == 0 && post_residual <= 50 {
                score -= 4.0;
            }
            // Fresh bin residual >= next item (chainable) is better than
            // a fresh bin that strands space when the stream is young.
            let progress1 = step_index as f64 / total_items.max(1) as f64;
            if next_item_size > 0 && post_residual >= next_item_size && progress1 < 0.7 {
                score -= 4.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 27.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Consolidation pressure early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mid-band residual (30..60) packs well with typical sizes.
    if post_residual >= 30 && post_residual <= 60 {
        let remaining = (total_items - step_index) as f64;
        let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
        score -= 5.0 + 3.0 * stream_left;
    }

    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Sharp penalty for the 5..12% sliver band.
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band attraction toward center.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Chain into small residual in the 10..18% band.
        if dead_ratio > 0.10 && dead_ratio < 0.18 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
        }
        // Mid-range dead space early in stream: penalize mildly.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
        // Tiny residual left after chaining next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
        }
        // Hard-to-fill residual with few fitting bins: avoid creating it.
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 2.5 * (0.08 - dead_ratio) * 100.0;
        }
        // Wide-open bins with next item smaller: strong chain candidate.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // Gap-based penalty when next item doesn't fit.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
        // Divisibility bonus.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        // Small-residual avoidance when many bins can still fit.
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        // Penalize residuals that neither the next item nor the mean open-bin
        // residual can absorb (dead-space coupling fix).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < next_item_size as f64 && after > mean_residual.max(1.0) {
                score += 3.0 * (1.0 - after / (next_item_size as f64)) * (1.0 - progress);
            }
        }
        // Avoid awkward 12..20% residuals when no chain is possible.
        if dead_ratio >= 0.12 && dead_ratio < 0.20 && stream_left2 > 0.5
            && (next_item_size == 0 || next_item_size > post_residual) {
            score += 3.0 * (dead_ratio - 0.12) * 50.0 * stream_left2;
        }
        // Reward exact multi-fit chains — residual divisible by next item
        // with at least two repetitions.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
        // Prefer bins whose post-residual can absorb next item AND leaves
        // a residual >= mean_residual (recyclable dead space).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= mean_residual.max(1.0) {
                score -= 1.5;
            }
        }
        // When many items remain, prefer bins whose post-residual is a
        // multiple of a common small size (5 or 10) — easier future packing.
        if stream_left2 > 0.4 && post_residual % 10 == 0 {
            score -= 1.5;
        } else if stream_left2 > 0.4 && post_residual % 5 == 0 {
            score -= 0.8;
        }
        // Late stream — strongly prefer tightest bins regardless of band.
        if stream_left2 < 0.25 {
            score += 0.08 * post_residual as f64;
        }
        // Combined coupling — when the stream is far from over and the
        // next item cannot use the leftover, penalize residuals that no
        // plausible future item (next item ± 10) can absorb either.
        if stream_left2 > 0.5 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < 10.0 {
                score -= 2.0 * (1.0 - after / 10.0) * stream_left2;
            }
        }
        // Dead-space coupling — penalize residuals that are too small
        // for the next item yet exceed the mean absorbable residual, scaled
        // by how many items remain (likely permanent waste).
        if next_item_size > 0 && post_residual < next_item_size
            && post_residual as f64 > mean_residual.max(1.0) * 1.5 && stream_left2 > 0.3 {
            score += 2.0 * (1.0 - dead_ratio) * stream_left2;
        }
        // Reward residuals in the 20..35% band when the next item can
        // chain into them and leave an absorbable remainder.
        if dead_ratio >= 0.20 && dead_ratio < 0.35 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after == 0.0 || after <= mean_residual.max(1.0) {
                score -= 4.0 * (1.0 - scarcity);
            }
        }
        // NEW: two-step lookahead — prefer bins whose post-residual can
        // chain the next item AND whose remainder can still absorb a
        // typical-sized follow-up (>= next item or divisible by 5).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let nxt = next_item_size as f64;
            if after >= nxt && stream_left2 > 0.3 {
                score -= 2.0 * (after / cap).min(1.0);
            } else if after > 0.0 && after % 5.0 == 0.0 && after < nxt && stream_left2 > 0.4 {
                score -= 1.2;
            }
        }
        // NEW: mean-residual convergence — bins whose post-residual lands
        // close to the current mean residual are easier to fill later by
        // the same stream distribution; reward the closeness.
        if stream_left2 > 0.35 {
            let dist_mean = (post_residual as f64 - mean_residual).abs();
            if dist_mean < 12.0 {
                score -= 1.5 * (1.0 - dist_mean / 12.0);
            }
        }
        // NEW: waste-avoidance when many fitting bins exist — with plenty of
        // alternatives, strongly avoid creating tiny unusable residuals
        // (< 8) that no plausible future item can absorb.
        if post_residual < 8 && fitting_bins_count >= 3 && stream_left2 > 0.2 {
            score += 4.0 * (8.0 - post_residual as f64) * stream_left2;
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match (post_residual == next_item_size) gets a big reward
        if gap == 0.0 {
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64) > 0 {
            // next item fits with slack; penalize proportionally to slack
            score -= 25.0 / (1.0 + gap * 0.15);
        } else {
            // next item won't fit in the residual; mild penalty scaled by closeness
            score += gap * 0.10;
        }
        // Extra reward if post_residual can hold next item tightly relative to capacity
        if post_residual >= next_item_size {
            let tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 20.0 * tightness;
        }
    }

    // Reward tight fits: small post_residual relative to capacity
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize creating dead space: post_residual too small for any future item (min size 1, but typical >= 10)
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // nearly-full bin is fine only if post_residual == 0
    }
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins)
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res - mean_residual) / mean_residual;
        score += 10.0 * rel.max(-1.5).min(1.5);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // Penalize new bin mildly; lookahead can overcome it on perfect matches
        score += 15.0;
        // But if item fills a good chunk, opening fresh is reasonable
        let usage = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * usage;
        // If next item pairs well with the complement, encourage new bin
        if next_item_size > 0 {
            let comp = bin_capacity as i64 - item_size as i64;
            if (comp - next_item_size as i64).abs() <= 5 {
                score -= 45.0;
            }
        }
    }

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 8.0 * progress * fill_ratio;

    // Many open bins: prefer filling existing ones over spreading
    score += 0.5 * open_bins_count as f64 * (res / bin_capacity as f64);

    score
}

