pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable dead space (waste), scaled by how unusable it is.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Lookahead: reward if the leftover residual exactly accommodates next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 30.0 + (next_item_size as f64) * 0.5;
        } else {
            // leftover can't fit next item: penalize proportionally to how far off
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize slightly when other bins exist and are tight,
    // but reward opening a fresh bin when current bins are badly fragmented
    // (mean residual low relative to item) or stream is late (fewer future gains).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        score += 80.0 - 60.0 * progress - 0.5 * fragmentation;
        if open_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
    } else {
        // Mild preference for filling existing bins as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Tie-break: prefer bins whose residual deviates most from mean (consolidation).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for bins with larger residual consumed fraction.
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

    score
}

