    score -= 25.0 * fill * fill * fill;

    // Lookahead: reward residual that matches next item size smoothly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.35 * diff;
        // bonus if post residual can exactly host next item
        score -= 15.0 * (1.0 / (1.0 + diff * diff * 0.05));
    }

    // Last-chance bin: strongly favor using it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize scattering residual when many bins are open
    score += 0.5 * (open_bins_count as f64).sqrt() * fit_norm * cap * (1.0 - urgency);

    // Nudge toward bins whose residual is near the mean (balance load)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: make it moderately attractive only when nothing fits well
    if bin_residual == bin_capacity {
        score += 8.0 + 40.0 * (1.0 - urgency) - 30.0 * urgency;
    }

    score
}

