        // next_item_size (exact two-item closure) — strong compaction signal.
        if next_item_size > 0 && post_residual == item_size + next_item_size {
            score -= 8.0;
        }
        // MUTATION: penalize leftovers in the 21..30 range after chaining when
        // the stream is long — dead space that small items rarely close.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 21.0 && after < 30.0 && stream_left2 > 0.5 {
                score += 1.2 * (after - 21.0) / 9.0 * stream_left2 * (1.0 - scarcity);
            }
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 / 20 / 50.
    // Residues that are "harmonic" (multiples of 10 or 20) pair well with
    // typical item sizes; odd residues create dead space.
    let res = post_residual;
    let harm10 = (res % 10 == 0) as f64;
    let harm20 = (res % 20 == 0) as f64;
    let harm50 = (res % 50 == 0) as f64;
    score -= 6.0 * harm50 + 3.0 * harm20 + 1.5 * harm10;

    // Integer-division thresholds on post_residual: small unusable slivers.
    if res <= 10 {
        score += 25.0; // dead space: can never hold a future item (min size 1..10 typical)
    } else if res <= 20 {
        score += 8.0;
    } else if res <= 30 {
        score += 2.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward (perfect pairing).
    if next_item_size > 0 {
        if next_item_size == res {
            score -= 40.0;
        } else if next_item_size <= res {
            let q = res / next_item_size.max(1);
            let r = res % next_item_size.max(1);
            score -= 8.0 * (q as f64).min(3.0);
            score += 2.0 * (r as f64) / 10.0;
        } else {
            score += 5.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when the stream is early or
    // the fit into existing bins would be very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress) - 10.0 * (fitting_bins_count as f64).recip();
        // penalize opening new bins when mean residual across open bins is large
        score += (mean_residual - item_size as f64).max(0.0) * 0.5;
    }

    // Tight fits are best: reward small post_residual relative to item size.
    score -= 20.0 * (item_size as f64) / (bin_capacity as f64) * (1.0 - post_residual as f64 / bin_capacity.max(1) as f64);

    // Slight preference to keep many open bins balanced late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 - mean_residual) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot fit even the smallest plausible item.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Tightness ratio: fraction of the bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 15.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * 2.5 * (1.0 - tightness);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual - item_size as f64;
        // If the best average outcome across open bins is poor, opening fresh is fine.
        if mean_fit >= 0.0 && mean_fit < 20.0 {
            score += 30.0; // open bins can absorb it decently -> penalize new bin
        } else {
            score -= 5.0; // poor fits everywhere -> allow a fresh bin
        }
        // Early in the stream, opening bins is cheap and flexible.
        score -= (1.0 - progress) * 8.0;
    }

    // Lookahead coupling: if the next item would fit into the resulting gap,
    // reward leaving exactly that much room; otherwise penalize a gap that
    // is almost-but-not-quite large enough for the next item.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let nx = next_item_size as f64;
        if nx <= gap {
            score -= 8.0; // chain placement possible
        } else if gap > 0.0 && nx - gap <= 10.0 {
            score += (nx - gap) * 1.5; // teasing gap: near-miss dead space
        }
    }

    // Mild preference for bins whose residual is already below average
    // (consolidate fullness into fewer bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

