pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fit (small post_residual), normalized.
    let mut score = post / capacity;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next > 0.0 && post >= next {
        let gap = post - next;
        // Perfect match -> big bonus; decays quadratically with gap.
        score -= 0.6 * (1.0 - (gap / capacity)) * (1.0 - (gap / capacity));
        // Small extra nudge for near-perfect matches (gap <= 5).
        if gap <= 5.0 {
            score -= 0.25;
        }
    } else if next > 0.0 && post < next {
        // Post-residual too small for the next item: penalize dead space
        // proportionally to how wasted it is.
        let dead = post / capacity;
        score += 0.35 * dead * dead;
    }

    // Prefer bins whose residual is already below mean (consolidate emptier
    // space into fuller bins), keeping emptier bins flexible.
    let mean = mean_residual / capacity;
    let post_n = post / capacity;
    score += 0.3 * (post_n - mean);

    // Last-chance bin: if this is the only bin that fits, heavily favor using
    // it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 0.8;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // fits poorly everywhere else. Penalize the empty-bin candidate mildly,
    // but less when many bins are open (bin proliferation less costly) or
    // when post_residual of the new bin would be huge (tiny item).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 0.45;
        if open_bins_count as f64 > 6.0 {
            new_bin_penalty -= 0.1;
        }
        if (item_size as f64) < 0.35 * capacity {
            new_bin_penalty += 0.2; // small items should go into existing space
        }
        score += new_bin_penalty;
    }

    // Mild time-based consolidation pressure: later in the stream, tighten up.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 0.15 * progress * post_n;
    }

