        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits: reward tightness of the match.
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize small dead space that nothing can use.
            score += 25.0 * gap / (bin_capacity as f64);
        }
        // Chain bonus: post_residual - next_item leaves room for a medium item later.
        if post_residual > next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= 10 {
                score -= 15.0 * (chain as f64 / bin_capacity as f64);
            }
        }
    }

    // Penalize creating dead space below the minimum item size (unusable waste).
    if post_residual > 0 && post_residual < 1 {
        score += 500.0;
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (tighter bins first), keeping large-residual bins for bigger future items.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Many open bins: discourage fragmentation, prefer filling existing bins.
    if open_bins_count > 4 {
        score += 0.3 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).abs() as f64
        } else {
            0.0
        };
        score += 80.0 - 2.0 * poor_fit;
        // Early in stream, opening bins is cheaper; late, avoid it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 60.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving little dead space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Lookahead: reward if the next item fits the post residual exactly-ish,
    // penalize if the leftover is too small to be useful for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
