pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction classes (1/8 granularity)
    let item_class = item_size / 13;
    let post_class = post_residual / 13;

    // Reward small post_residual, especially when it lands on a "clean" class
    let progress = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * progress;

    // Dead-space penalty: residuals that cannot accommodate the smallest item (1)
    // are fine, but residuals in awkward mid-ranges are penalized harmonically.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 33 {
        // mid dead zone: penalize proportionally to distance from usable sizes
        let usable = (next_item_size <= post_residual && next_item_size > 0) as u32;
        if usable == 0 {
            score += 8.0 + (post_residual % 7) as f64;
        }
    }

    // Harmonic pairing bonus: post_residual matches next item class exactly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect lookahead fit
        } else if next_item_size < post_residual && (post_residual - next_item_size) <= 10 {
            score -= 25.0; // near-perfect lookahead fit
        } else if next_item_size > post_residual {
            // next item won't fit here; if this is the last fitting bin, still prefer tight fit
            if fitting_bins_count == 1 {
                score -= 20.0;
            } else {
                score += 5.0 + (post_residual % 5) as f64;
            }
        }
    }

    // Class alignment bonus: item class equals residual class (harmonic resonance)
    if item_class == post_class && post_residual > 0 {
        score -= 6.0;
    }

    // New-bin candidate handling: only open a new bin when item is large
    // and no bin offers a good fit (avoid wasting fresh capacity on small items).
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (bin_capacity - item_size) > 0
            && open_bins_count > 0
            && mean_residual >= item_size as f64 * 0.9;
        if good_fit_exists && item_size < 50 {
            score += 500.0; // strongly discourage new bin
        } else if item_size >= 50 && fitting_bins_count > 0 {
            let best_possible = mean_residual; // proxy: is any open bin tighter?
            if best_possible - item_size as f64 > 25.0 {
                score -= 30.0; // open fresh bin for large item over poor fits
            } else {
                score += 100.0;
            }
        } else if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 10.0 * (1.0 - progress);

    // Mild penalty proportional to open bins to encourage consolidation
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
