            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0;
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0;
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
