            if after > 0.0 && after < 10.0 {
                score -= 2.0 * (1.0 - after / 10.0) * stream_left2;
            }
        }
        // Dead-space coupling — penalize residuals too small for the next
        // item yet above the mean absorbable residual.
        if next_item_size > 0 && post_residual < next_item_size
            && post_residual as f64 > mean_residual.max(1.0) * 1.5 && stream_left2 > 0.3 {
            score += 2.0 * (1.0 - dead_ratio) * stream_left2;
        }
        // Reward residuals in the 20..35% band when the next item can
        // chain into them and leave an absorbable remainder.
        if dead_ratio >= 0.20 && dead_ratio < 0.35 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after == 0.0 || after <= mean_residual.max(1.0) {
                score -= 4.0 * (1.0 - scarcity);
            }
        }
        // COMBINE (from best): chain bonuses — after >= nxt and after % 10.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= next_item_size {
                score -= 3.0;
            }
            if chain > 0 && chain % 10 == 0 {
                score -= 2.0;
            }
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (items >= 1, but tiny gaps < 10 are nearly dead)
    // are heavily penalized, scaled by how dead the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Semi-dead gaps: too small for typical mid-size items (10..80).
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
        score -= 15.0 * tightness;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage scattering across many bins.
    score += 0.8 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps bin states balanced), slight effect.
    score += 0.3 * ((bin_residual as f64) - mean_residual).abs();

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use this gap -> dead space risk
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large and current bins would leave very poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper if current open bins would leave large dead space.
        let best_gap_penalty = (post_residual as f64) / bin_capacity as f64;
        score -= 30.0 * best_gap_penalty;
        // If no existing bin fits well (this call context), reduce penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: never waste this bin again.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
    }

    // Harmonic class of post_residual.
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    if (post_residual as f64) >= half {
        score -= 18.0;
    } else if (post_residual as f64) >= quarter {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 8.0;
    }

    // Modulo-10 class of post_residual.
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.4;

    // Lookahead coupling with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 48.0;
        } else if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after < class_width {
                score -= 20.0 + 0.5 * (class_width - after) as f64;
            } else {
                score -= 12.0 + 0.1 * after as f64;
            }
            if post_residual % next_item_size == 0 {
                score -= 7.0;
            }
            if after <= 3 {
                score -= 13.0;
            } else if after >= 2 * next_item_size {
                score -= 14.0;
            } else if after >= next_item_size {
                score -= 10.0;
            } else if after < next_item_size {
                score += 4.0;
            }
            if after >= 3 && after <= 15 {
                score -= 3.5;
            }
            // Reward when after leaves a small residual that any open bin could absorb.
            if after > 0 && (after as f64) <= mean_residual.max(1.0) {
                score -= 2.5;
            }
        } else if post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if gap <= 8.0 {
                score += 3.0 + 0.5 * (8.0 - gap);
            }
            if post_residual >= 5 && post_residual % 5 == 0 {
                score += 2.0;
            }
        } else if bin_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let bins_crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_capacity = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0 && mean_residual < next_item_size as f64 * 1.15 && (fitting_bins_count as f64) < 4.0)
                || (total_fit_capacity < next_item_size as f64 * 2.0 && fitting_bins_count <= 1));
        if big_item || bins_crowded || next_needs_fresh {
            score -= 44.0;
        } else {
            score += 45.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            // Open a fresh bin more eagerly late in the stream when open bins are mostly small leftovers.
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins below the mean (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Small-residue dead-space shaping.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        let waste = (bin_capacity / 4 - post_residual) as f64 / cap;
        score += waste * 14.0;
    }

    // Scarcity-aware dead-space handling.
    if post_residual > 0 {
        let dead_ratio = (post_residual as f64) / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
