pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space: post residual that is too small to hold a typical item.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 40.0;
    }
    // Harsh penalty for leaving awkward small gaps (unusable dead space).
