        // gap smaller than current item is inherently awkward; scale by gap size
        score += 0.35 * post_residual as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slightly penalize bins that become useless
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // later, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 25.0 * progress - 10.0 * (1.0 - progress);
        // Prefer new bin when open bins are mostly full on average.
        score -= 0.15 * mean_residual;
        // Penalize excessive bin proliferation late in the stream.
        score += 0.5 * open_bins_count as f64 * progress;
    } else {
        // Existing bin: mild reward proportional to how full it already is.
        score -= 8.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Global fragmentation pressure: when mean residual is low, avoid wasting space.
    if mean_residual < item_size as f64 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

