        let nxt = next_item_size as f64;
        if nxt <= post {
            // next item can use this residual: reward proportionally to how well it fills it
            let fill = nxt / post.max(1.0);
            score -= 25.0 * fill * (1.0 - (fill - 1.0).abs());
        } else {
            // dead space relative to next item: penalize smoothly
