pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post > 0.0 {
        let gap = post_residual.min(item_size.saturating_sub(1)).max(1) as f64;
        if post_residual < 10 {
            score += 25.0; // residual below minimum item size is pure dead space
