pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space relative to capacity (waste measure).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after hypothetically placing the next item too.
            let slack_after_next = post_residual - next_item_size;
            // Reward tight two-item packing: smaller slack_after_next is better.
            score -= 30.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
            // Extra bonus for exact or near-exact two-item fill.
            if slack_after_next <= 5 {
                score -= 20.0;
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally to the gap.
            let gap = next_item_size - post_residual;
            score += 0.3 * gap as f64;
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // residual than typical is mildly penalized (fragmentation tendency).
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large relative to capacity or no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin by default.
        score += 40.0;
        // But if the item is huge, a new bin is fine (perfect fit region).
        if fill_ratio > 0.8 {
            score -= 55.0;
        }
        // If next item is also large, a fresh bin can host both well.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && fill_ratio > 0.5 {
            score -= 15.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 120.0;
        }
    } else if post_residual <= bin_capacity / 5 {
        score += 20.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 4.0;
    } else {
        score -= 18.0;
    }

    // Exact lookahead match: perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0;
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0;
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
                score -= 12.0 + 0.15 * (pr - nxt);
            }
            // COMBINED: strong chain bonuses borrowed from best heuristic —
            // residual after placing next item that still fits more items.
            if after >= nxt {
                score -= 14.0;
                if after >= 2.0 * nxt {
                    score -= 10.0;
                }
            } else if after > 0.0 {
                score += 4.0;
            }
            if nxt > 0 && (pr as u32) % (next_item_size) == 0 {
                score -= 8.0;
            }
            if after > 0.0 && after <= mean_residual.max(1.0) {
                score -= 8.0;
            }
            if after >= 3.0 && after <= 15.0 {
                score -= 3.5;
            }
            if after > 0.0 && after % nxt.max(1.0) == 0.0 && after >= nxt {
                score -= 2.0 + 0.15 * (after / nxt);
            }
            if after > 0.0 && after % 10.0 == 0.0 {
                score -= 4.0;
            }
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
            // Two-item lookahead: residual after placing next item should be
            // zero or absorbable by the average open bin.
            if after > 0.0 && after < cap * 0.5 {
                let frac = after / cap;
                if (frac * 10.0).round() as i32 <= 1 {
                    let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                    score -= 3.0 * (1.0 - frac * 10.0) * (1.0 - scarcity);
                }
            }
            // Penalize chains that leave a mid-range residual far above the
            // mean absorbable residual — likely permanent dead space.
            if after > 0.0 && after >= mean_residual.max(1.0) * 2.0 && after <= cap * 0.35 {
                score += 3.0 * (after / cap);
            }
            // Penalize chains leaving a residual that is neither absorbable
            // by the mean open-bin residual nor by the next item itself.
            if after > 0.0 && after < nxt && after > mean_residual.max(1.0) {
                score += 4.0 * (1.0 - after / nxt) * (1.0 - ((fitting_bins_count as f64) / 5.0).min(1.0));
            }
            // Triple-chain bonus.
            if after >= 2.0 * nxt && (pr as u32) % (next_item_size) == 0 {
                score -= 6.0;
            }
        } else {
            let gap = nxt - pr;
            if gap <= 8.0 {
                score += 60.0 + 6.0 * (8.0 - gap);
            } else {
                score += 25.0 * (1.0 - pr / nxt.max(1.0));
            }
            if gap <= 15.0 {
                let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
            if gap <= 20.0 && ((fitting_bins_count as f64) / 5.0).min(1.0) < 0.5 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
            if pr >= 5 && pr % 5 == 0 {
                score -= 2.0;
            }
        }
    }

    // Relative-to-mean: prefer tighter-than-average bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance: only fitting bin -> keep item out of a new bin.
    if fitting_bins_count == 1 {
        score -= 160.0;
    } else if fitting_bins_count == 0 {
        score += 80.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_cap = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                && mean_residual < next_item_size as f64 * 1.15
                && (fitting_bins_count as f64) < 4.0)
                || (total_fit_cap < next_item_size as f64 * 2.0
                    && fitting_bins_count <= 1));
        if big_item || crowded || next_needs_fresh {
            score -= 55.0;
        } else {
            score += 70.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
