pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual too small for any plausible item (min size 1..10)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into post_residual, strongly reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // stranded residual that next item cannot use
