        score -= 12.0;
    } else if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr < 10 && pr > 0 {
        // dead space penalty: nothing (>=1) can ever fit below 10... but sizes 1..100 allowed
