            score += 30.0 * (1.0 - pr as f64 / 3.0);
        } else {
            score += 4.0;
        }
    }

    // Coupling with next item: does post_residual admit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // perfect chaining: next item exactly fills remaining space
            if post_residual == next_item_size {
                score -= 40.0;
            } else {
