    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 5.0 + 20.0 * t;
        // But if no open bin fits well, allow opening a fresh bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward more heavily late in the stream.
        score -= 8.0 * t;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let prog_sq = progress * progress;
    let prog_cube = prog_sq * progress;

    // Reward tight fits more strongly as stream progresses (dead space matters later)
    let tightness_reward = prn * prn * (0.5 + 2.0 * progress) * cap;
    score -= tightness_reward;

    // Penalize large residual bins early (save big spaces for big items)
    let early_save_penalty = prn * (1.0 - progress) * (1.0 - progress) * cap * 0.4;
    score += early_save_penalty;

    // Smooth interaction: post_residual vs mean_residual deviation
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: penalize if next item could have used this residual better
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste = (pr - ni).max(0.0) as f64 / cap;
        score += waste * waste * cap * (0.5 + 0.5 * progress);
        // Reward if next item fits exactly in the post residual
        if ni <= pr as f64 && (pr - ni) <= 5.0 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Mild penalty for proliferating bins
    score += (open_bins_count as f64).ln() * (1.0 + 3.0 * progress);

    // New-bin candidate: bias toward using open bins early, allow opening later
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 34.0; // tiny dead space is actually great -> reward (borrowed from best)
    } else if post_residual <= bin_capacity / 5 {
        score += 12.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 4.0;
    } else {
        score -= 14.0; // large residual after placement = roomy bin, good
    }

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0; // exact 2-chain
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0;
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
                score -= 12.0 + 0.15 * after;
            }
            if after >= nxt {
                score -= 10.0; // room for a third item
                if after >= 2.0 * nxt {
                    score -= 6.0;
                }
                if after % nxt as u32 == 0 {
                    score -= 5.0; // divisible chain
                }
            }
            // after-leaves-small-residual absorbable by mean leftover
            if after > 0.0 && after <= mean_residual.max(1.0) {
                score -= 3.0;
            }
        } else {
            let gap = nxt - pr;
            if gap <= 8.0 {
                score += 60.0 + 6.0 * (8.0 - gap);
            } else {
                score += 25.0 * (1.0 - pr / nxt.max(1.0));
            }
        }
