            score -= 60.0;
        } else {
            score += 70.0;
            // eager fresh-bin when next item is large and leftovers small
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
        }
        // late-stream: open fresh bins when open bins are mostly tiny leftovers
