pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in small classes are "dead space".
    let class = post_residual / 10;
    match class {
        0 => score -= 30.0,           // 0..9: near-perfect fill, strongly reward
        1 => score -= 12.0,           // 10..19: still usable for smallest items
        2 => score += 4.0,            // 20..29: mediocre
        3 => score += 8.0,            // 30..39
        4 => score -= 2.0,            // 40..49: half-bin, mild reward
        _ => {}                        // large residuals: keep raw value
    }

    // Modulo-10 coupling: residual that pairs with common small sizes (next item)
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits exactly here: reward proportionally to tightness
        let tight = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - tight / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot follow here: penalize, worse if residual is tiny
        if post_residual < 10 {
            score += 18.0;
        } else {
            score += (post_residual as f64).min(25.0) * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless residual would be badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin early or when open bins are crowded/fragmented
        let fragmentation = mean_residual / bin_capacity as f64;
        score = post_residual as f64 + 10.0 - 25.0 * (1.0 - fragmentation) * (1.0 - progress);
        if post_residual > 60 {
            score += 20.0; // don't open new bin for tiny items
        }
    }

    // Reward filling bins that are already below half full (consolidation)
    if bin_residual < bin_capacity / 2 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Small penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
