    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize new-bin candidate (bin_residual == bin_capacity) unless item is huge
    if bin_residual == bin_capacity {
        score += 250.0;
        if item_size >= bin_capacity / 2 {
            score -= 200.0;
        }
