    // Prefer fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.2;

    // Early in stream: be slightly more willing to open bins (flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 80.0;
