pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead-space penalty: post residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward if next item can fit into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else if next_item_size == post_residual {
            score -= 120.0;
        } else {
            // Next item won't fit: penalize proportionally to wasted potential.
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > (item_size as f64 * 1.5) {
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Late in stream: consolidate; early: allow new bins for big items.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or when good fits exist.
        let mut new_bin_penalty = 55.0 + 90.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 35.0 * (fitting_bins_count as f64).ln();
        }
        if item_size > 60 && progress < 0.3 {
            new_bin_penalty -= 45.0; // early big items may deserve fresh bins
        }
        score += new_bin_penalty;
    } else {
        // Mild reward for using existing bins proportional to openness.
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    }

    score
}

