}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues that are "dead space" for
    // typical item sizes get penalized. Classes modulo 10.
    let post_mod = post_residual % 10;
    score -= match post_mod {
        0 => 30.0,                    // round residual, highly reusable
        5 => 15.0,                    // half-class, moderately reusable
        1 | 9 => -8.0,                // awkward slivers, penalize (add)
        2 | 8 => -4.0,
        _ => 0.0,
    };

    // Dead-space threshold: residual below 10 can never be used
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // If lookahead item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 25.0 + slack as f64 * 0.3;
        // exact chain fit
        if slack == 0 {
            score -= 50.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // lookahead cannot use this bin's leftover: penalize proportionally
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it rather than opening new
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets baseline score
    if bin_residual == bin_capacity {
        // neutral-ish but slightly worse than a good existing fit;
        // more attractive late in stream or when few bins fit
        score = bin_capacity as f64 * 0.55;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item followed by bigger: maybe fresh bin ok
        }
        if fitting_bins_count <= 2 {
            score -= 15.0;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    // Prefer filling bins that are already relatively full (small residual)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Mild bonus for tight fits relative to item size
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 5.0;

    score
}

