            let filler = mean_residual.max(1.0).min(cap * 0.25);
            if (after as f64) >= filler && (after as f64) - filler <= 4.0 {
                score -= 6.0 * (1.0 - scarcity);
            }
        }
        // NEW: penalize residuals just barely above the next item (leaves unusable sliver)
        if next_item_size > 0 && post_residual > next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after < 6 && fitting_bins_count > 2 {
                score += 3.0 + 0.5 * (6 - after) as f64;
            }
        }
    }

    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: classify post_residual by integer division into
    // "dead zones" (residuals too small to host typical items) vs reusable zones.
    let classes: [u32; 6] = [10, 20, 30, 45, 60, 80];
    let mut post_class: usize = 0;
    for (i, c) in classes.iter().enumerate() {
        if post_residual >= *c { post_class = i + 1; }
    }

    // Reward exact/near-perfect fits (post_residual in the lowest classes).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 80.0;
    } else {
        // Dead-space penalty grows super-linearly for unusable leftovers.
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += (dead / 10.0) * (dead / 10.0) * 2.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 { score -= 150.0; }
            else { score += slack as f64 * 0.5; }
        } else {
            // Next item cannot fit here regardless; mild bonus for keeping residual usable.
            score += 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let base = 60.0 + post_residual as f64; // post_residual == capacity here
        let scarcity = if fitting_bins_count == 0 { -400.0 } else if fitting_bins_count == 1 { -50.0 } else { 150.0 };
        // Encourage new bins early (fresh capacity), discourage when many bins open.
        let phase = step_index as f64 / (total_items.max(1) as f64);
        score = base + scarcity + open_bins_count as f64 * 3.0 - phase * 50.0;
    } else {
        // Prefer fuller bins relative to the mean residual of open bins.
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Harmonic class coupling: bins whose post_residual lands exactly on a class
    // boundary are more likely reusable; reward them.
    for &c in classes.iter() {
        if post_residual == c {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let class_width: u32 = 10;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < class_width {
        score -= 34.0;
        if next_item_size == 0 || (next_item_size as u32) > post_residual {
            score += 120.0;
        }
    } else if post_residual <= bin_capacity / 5 {
        score += 20.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 4.0;
    } else {
        score -= 18.0;
    }

    // Exact lookahead match: perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let after = pr - nxt;
            if after == 0.0 {
                score -= 500.0;
            } else if after < 4.0 {
                score -= 90.0 + (4.0 - after) * 12.0;
            } else if after <= 30.0 {
                score -= 40.0 * (1.0 - after / 30.0);
            } else {
                score -= 12.0 + 0.15 * (pr - nxt);
            }
            if after >= nxt {
                score -= 10.0;
                if after >= 2.0 * nxt {
                    score -= 8.0;
                }
                if after >= 3.0 * nxt {
                    score -= 4.0;
                }
            }
            if nxt > 0 && (pr as u32) % (nxt as u32) == 0 {
                score -= 7.0;
            }
            if after > 0.0 && after <= mean_residual.max(1.0) {
                score -= 5.0;
            }
            if after >= 3.0 && after <= 15.0 {
                score -= 3.5;
            }
            if after > 0.0 && after % nxt.max(1.0) == 0.0 && after >= nxt {
                score -= 2.0 + 0.15 * (after / nxt);
            }
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
            // Two-item lookahead: residual after placing next item should be
            // zero or absorbable by the average open bin.
            if after > 0.0 && after < cap * 0.5 {
                let frac = after / cap;
                if (frac * 10.0).round() as i32 <= 1 {
                    let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                    score -= 2.5 * (1.0 - frac * 10.0) * (1.0 - scarcity);
                }
            }
            // Penalize chains that leave a mid-range residual far above the
            // mean absorbable residual — likely permanent dead space.
            if after > 0.0 && after >= mean_residual.max(1.0) * 2.0 && after <= cap * 0.35 {
                score += 2.5 * (after / cap);
            }
        } else {
            let gap = nxt - pr;
            if gap <= 8.0 {
                score += 60.0 + 6.0 * (8.0 - gap);
            } else {
                score += 25.0 * (1.0 - pr / nxt.max(1.0));
            }
            if gap <= 15.0 {
                let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
                score += 2.5 * (15.0 - gap) / 15.0 * (1.0 - scarcity);
            }
            if gap <= 20.0 && ((fitting_bins_count as f64) / 5.0).min(1.0) < 0.5 {
                score += 3.0 * (20.0 - gap) / 20.0;
            }
        }
    }

    // Relative-to-mean: prefer tighter-than-average bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance: only fitting bin -> keep item out of a new bin.
    if fitting_bins_count == 1 {
        score -= 160.0;
    } else if fitting_bins_count == 0 {
        score += 80.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let big_item = item_size > bin_capacity / 2;
        let crowded = mean_residual < cap * 0.2 && open_bins_count > 0;
        let total_fit_cap = mean_residual * open_bins_count as f64;
        let next_needs_fresh = next_item_size > 0
            && open_bins_count > 0
            && ((fitting_bins_count > 0
                && mean_residual < next_item_size as f64 * 1.15
                && (fitting_bins_count as f64) < 4.0)
                || (total_fit_cap < next_item_size as f64 * 2.0
                    && fitting_bins_count <= 1));
        if big_item || crowded || next_needs_fresh {
            score -= 55.0;
        } else {
            score += 70.0;
            if next_item_size > 60 && post_residual > 25 {
                score -= 30.0;
            }
            if open_bins_count > 40 && next_item_size >= 50 {
                score -= 8.0;
            }
            let leftover_share = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
            let progress0 = step_index as f64 / total_items.max(1) as f64;
            if leftover_share < 0.12 && progress0 > 0.5 {
                score -= 10.0 * (0.12 - leftover_share) * 100.0 * progress0;
            }
            // Fresh-bin capacity check: open bins collectively cannot absorb
            // the current item plus the next one.
            if open_bins_count > 0 && next_item_size > 0 {
                if total_fit_cap < (item_size + next_item_size) as f64 * 0.9 {
                    score -= 12.0;
                }
            }
            // Fresh bin leaving a residual exactly matching the next item is
            // a perfect chain — reward strongly.
            if next_item_size > 0 && post_residual == next_item_size {
                score -= 45.0;
            }
            // Fresh bin leaves a residual the next item almost fills: good.
            if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
                score -= 18.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 27.0 * progress;
    } else {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Consolidation pressure early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mid-band residual (30..60) packs well with typical sizes.
    if post_residual >= 30 && post_residual <= 60 {
        let remaining = (total_items - step_index) as f64;
        let stream_left = (remaining / total_items.max(1) as f64).min(1.0);
        score -= 5.0 + 3.0 * stream_left;
    }

    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let scarcity = ((fitting_bins_count as f64) / 5.0).min(1.0);
        if dead_ratio < 0.10 {
            let crowd = ((open_bins_count as f64) / 60.0).min(1.0);
            score += dead_ratio * 120.0 * (0.5 + crowd) * (0.6 + 0.4 * scarcity);
        } else if dead_ratio > 0.55 && next_item_size > 0 && next_item_size as f64 > dead_ratio * cap {
            score -= 12.0 + 8.0 * (1.0 - scarcity);
        } else if dead_ratio > 0.35 && fitting_bins_count >= 3 && next_item_size > post_residual {
            score += 6.0 * (dead_ratio - 0.35) * 10.0;
        }
        // Sharp penalty for the 5..12% sliver band (softened near upper edge).
        if dead_ratio > 0.05 && dead_ratio < 0.12 {
            score += 10.0 * (0.12 - dead_ratio) * 100.0;
        }
        // Mid-band attraction toward center.
        if dead_ratio >= 0.20 && dead_ratio <= 0.45 && next_item_size > 0 {
            let band_center = 0.325 * cap;
            let dist = (post_residual as f64 - band_center).abs();
            score -= 6.0 * (1.0 - dist / (0.125 * cap)).max(0.0);
        }
        // Chain into small residual in the 10..18% band.
        if dead_ratio > 0.10 && dead_ratio < 0.18 && next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < cap * 0.10 {
                score -= 2.5 * (1.0 - after / (cap * 0.10)) * (1.0 - scarcity);
            }
        }
        // Mid-range dead space early in stream: penalize mildly.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
        // Tiny residual left after chaining next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let fill = 1.0 - after / cap;
            if after > 0.0 && after <= 5.0 {
                score -= 3.5 * fill * (1.0 - scarcity);
            }
        }
        // Hard-to-fill residual with few fitting bins: avoid creating it.
        if dead_ratio < 0.08 && fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 2.5 * (0.08 - dead_ratio) * 100.0;
        }
        // Wide-open bins with next item smaller: strong chain candidate.
        if dead_ratio > 0.45 && dead_ratio < 0.55 && fitting_bins_count <= 2 && next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0 * (1.0 - scarcity);
        }
        // Gap-based penalty when next item doesn't fit.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }
        // Divisibility bonus.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }
        // Small-residual avoidance when many bins can still fit.
        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }
        // Penalize residuals that neither the next item nor the mean open-bin
        // residual can absorb (dead-space coupling fix).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after < next_item_size as f64 && after > mean_residual.max(1.0) {
                score += 3.0 * (1.0 - after / (next_item_size as f64)) * (1.0 - progress);
            }
        }
        // Avoid awkward 12..20% residuals when no chain is possible.
        if dead_ratio >= 0.12 && dead_ratio < 0.20 && stream_left2 > 0.5
            && (next_item_size == 0 || next_item_size > post_residual) {
            score += 3.0 * (dead_ratio - 0.12) * 50.0 * stream_left2;
        }
        // Reward exact multi-fit chains — residual divisible by next item
        // with at least two repetitions.
        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
        // Prefer bins whose post-residual can absorb next item AND leaves
        // a residual >= mean_residual (recyclable dead space).
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= mean_residual.max(1.0) {
                score -= 1.5;
            }
        }
        // Combined fine-grained + lookahead coupling — reward bins whose
        // post-residual sits just below the next item size (small gap), so the
        // next item nearly closes this bin; stronger when bins are scarce.
        if next_item_size > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 6.0 && fitting_bins_count <= 3 {
                score -= 4.0 * (1.0 - gap / 6.0) * (1.0 - scarcity);
            }
        }
        // Penalize creating residuals in the 13..19% band when the next
        // item cannot chain and mean residual is also too small to absorb it.
        if dead_ratio >= 0.13 && dead_ratio < 0.19
            && (next_item_size == 0 || next_item_size as f64 > post_residual as f64)
            && mean_residual.max(1.0) < dead_ratio * cap {
            score += 4.0 * (1.0 - scarcity);
        }
        // Fine-grained chain quality — when chaining the next item, grade
        // the leftover residual against both the mean absorbable residual and
        // divisibility, coupling lookahead with tight fitting.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            let mean_abs = mean_residual.max(1.0);
            if after > 0.0 {
                if after <= mean_abs * 0.5 {
                    score -= 4.0 * (1.0 - after / (mean_abs * 0.5).max(1.0)) * (1.0 - scarcity);
                } else if after > mean_abs * 2.0 && after < cap * 0.25 {
                    score += 3.0 * (after / (cap * 0.25)) * (1.0 - progress);
                }
                if next_item_size >= 2 && after % next_item_size.max(1) == 0 && after >= next_item_size as f64 {
                    score -= 2.0;
                }
            }
        }
        // Avoid leaving residuals that no plausible future item can close.
        if dead_ratio >= 0.22 && dead_ratio < 0.32 && stream_left2 > 0.7
            && fitting_bins_count <= 2 && (next_item_size == 0 || next_item_size as f64 > post_residual as f64) {
            score += 2.0 * (dead_ratio - 0.22) * 30.0 * stream_left2 * (1.0 - scarcity);
        }
        // Strong reward for bins where the next TWO items would fit
        // (post_residual >= 2 * next_item_size) with little slack left after.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            let after2 = post_residual - 2 * next_item_size;
            if after2 <= 8 {
                score -= 7.0 * (1.0 - after2 as f64 / 8.0) * (1.0 - scarcity);
            }
        }
        // After chaining the next item, reward leftovers that a typical
        // small item (<= 20) could still close, coupling fine-grained fitting
        // with multi-step lookahead; stronger when bins are plentiful.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after > 0.0 && after <= 20.0 {
                let crowd = ((open_bins_count as f64) / 40.0).min(1.0);
                score -= 2.0 * (1.0 - after / 20.0) * (0.5 + 0.5 * crowd);
            }
            // Penalize chains leaving leftover slightly above a plausible
            // small-item band (20..28) — awkward dead space late in stream.
            if after > 20.0 && after < 28.0 && stream_left2 > 0.6 {
                score += 1.5 * (after - 20.0) / 8.0 * stream_left2;
            }
        }
        // Prefer bins whose current residual is close to item_size +
        // next_item_size (exact two-item closure) — strong compaction signal.
        if next_item_size > 0 && post_residual == item_size + next_item_size {
            score -= 8.0;
        }
        // MUTATION: reward residual exactly divisible by a coarse bucket of
        // the next item (chain-friendly multiples), tuned by scarcity.
        if next_item_size >= 4 && post_residual >= next_item_size {
            let bucket = ((next_item_size as f64) / 2.0).ceil() as u32;
            if bucket > 0 && post_residual % bucket == 0 {
                score -= 2.0 * (1.0 - scarcity);
            }
        }
        // MUTATION: late-stream — strongly prefer any open bin that can chain
        // the next item, to avoid opening bins near the end.
        if stream_left2 < 0.25 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0 * (0.25 - stream_left2) / 0.25;
        }
        // MUTATION: penalize residuals in the 32..44% band when the next item
        // cannot chain and stream is long — classic dead-space window.
        if dead_ratio >= 0.32 && dead_ratio < 0.44 && stream_left2 > 0.5
            && (next_item_size == 0 || next_item_size as f64 > post_residual as f64) {
            score += 2.5 * (dead_ratio - 0.32) * 20.0 * stream_left2;
        }
    }

    // Endgame: squeeze remaining items into open bins.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 10.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow new bins.
    let obp = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + 2.0 * obp;
    } else {
        score -= 1.5 * obp;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 && (post_residual as f64) < 10.0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose post residual stays near the mean.
    let mr = mean_residual;
    if mr > 0.0 {
        let dev = (post_residual as f64 - mr).abs();
        score += 0.3 * dev;
    }

    // Early stream: be slightly more open to new bins; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

