        score -= 60.0; // perfect fill
    } else if pr % 10 == 0 {
        score -= 25.0;
    } else if pr % 5 == 0 {
        score -= 12.0;
    } else {
        // penalize awkward classes; worst near the middle of a decade
        score += (5.0 - harmonic_class).abs() * 1.5;
    }

    // Integer-division thresholds on post_residual: classify leftover space.
    let leftover_class = pr / 10; // 0..=9
