            score += 4.0 * (0.08 - dead_ratio) * 100.0 * 0.5;
        }

        if next_item_size > 0 && post_residual > next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after >= 100.0 {
                score -= 4.0 * ((after - 100.0) / cap).min(1.0);
            }
        }

        if dead_ratio > 0.48 && fitting_bins_count <= 2 && next_item_size as f64 > post_residual as f64 {
            score += 3.0 * (dead_ratio - 0.48) * 20.0;
        }

        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - dead_ratio);
        }

        if dead_ratio < 0.15 && fitting_bins_count >= 4 {
            score += 5.0 * (0.15 - dead_ratio) * 10.0;
        }

        // Fractional leftover band after lookahead placement.
        let after2 = if next_item_size > 0 && post_residual >= next_item_size { (post_residual - next_item_size) as f64 } else { -1.0 };
        if after2 >= 0.0 && after2 < cap * 0.5 {
            let frac = after2 / cap;
            if (frac * 10.0).round() as i32 <= 1 {
                score -= 2.0 * (1.0 - frac * 10.0) * (1.0 - scarcity);
            }
        }

        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1 {
            score += 5.0 * (1.0 - dead_ratio);
        }

        // Mild penalty for mid-range dead space when much stream remains.
        let stream_left2 = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
        if dead_ratio >= 0.18 && dead_ratio <= 0.30 && stream_left2 > 0.6 {
            score += 2.0 * (dead_ratio - 0.18) * 20.0 * stream_left2;
        }
    }

    // Endgame: strongly prefer filling open bins tightly.
    let stream_left = ((total_items - step_index) as f64 / total_items.max(1) as f64).min(1.0);
    if stream_left < 0.15 && bin_residual != bin_capacity && post_residual > 0 {
        score -= 8.0 * (0.15 - stream_left) / 0.15 * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..100 stream, but small sizes are common)
    // are "dead space". Penalize residuals in the awkward range hard.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny unusable sliver -> strong penalty (waste of capacity).
            score += 25.0;
        } else if post_residual < item_size {
            // Gap too small for the current item class; mild extra penalty
            // scaled by how close it is to being useless.
            score += 0.5 * (10.0 - post_residual as f64 / 10.0).max(0.0);
        }
    } else {
        // Perfect fill: reward heavily.
        score -= 30.0;
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, reward strongly; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; residual likely becomes dead space.
            score += 3.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += 0.3 * open_bins_count as f64;

    // Last-chance bonus: if this is the ONLY bin that can fit the item,
    // strongly favor it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large (poor fit elsewhere) or no good residual is left.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Large items pack better in fresh bins.
        score -= 0.35 * item_size as f64;
        // Early in the stream, fresh bins are cheap (long horizon to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins already fit the item, opening new is wasteful.
        if fitting_bins_count > 1 {
            score += 12.0;
        }
        // If the mean residual across open bins is large, use them instead.
        score += 0.15 * mean_residual;
        // Lookahead: fresh bin leaves room for the next item too.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Mean-residual alignment: prefer bins whose residual is close to the
    // item size (best-fit behavior relative to fleet state).
    let dev = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * dev;

    score
}

