pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual), but punish leaving dead space
    // that no plausible item can use.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize very small unusable leftovers more strongly than medium gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 6.0; // sweet spot: still usable by mid-size items
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item won't fit here after placement; slight penalty
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit badly
    // (post_residual very small / dead space) or the stream is early and we
    // have few bins to work with.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // A fresh bin gives full flexibility; make it costly so it only wins
        // when open bins would create dead space.
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
        if progress < 0.2 {
            score -= 8.0; // early stream: slight openness to new bins
        }
        if open_bins_count > 20 {
            score += 10.0; // discourage bin sprawl late in the stream
        }
    }

    // Global residual pressure: when mean residual across open bins is high,
    // we can afford slightly looser fits; when low, be pickier.
    let mr = mean_residual;
    if mr < 25.0 {
        score += 5.0 * (25.0 - mr) / 25.0;
    } else if mr > 60.0 {
        score -= 3.0 * (mr - 60.0) / 40.0;
    }

    // Mild preference for filling bins that are already quite full
    // (first-fit-like behavior emerges from this).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    score
}

