pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets via integer division.
    // Residuals in [1,10] are "prime" slots (tight fit), [11,25] usable, >25 wasteful.
    let pr = post_residual;
    let tight_bonus = if pr == 0 {
        -80.0 // perfect fill
    } else if pr <= 10 {
        -40.0
    } else if pr <= 25 {
        -8.0
    } else if pr <= 40 {
        10.0
    } else {
        25.0
    };
    score += tight_bonus;

    // Modulo arithmetic on capacity fractions: post_residual divisible by small
    // harmonics (2,4,5,10) is more likely reusable by future items.
    let reusability = if pr > 0 {
        let mut r = 0.0;
        if pr % 10 == 0 { r -= 12.0; }
        else if pr % 5 == 0 { r -= 6.0; }
        else if pr % 2 == 0 { r -= 3.0; }
        if pr % 25 == 0 { r -= 8.0; }
        r
    } else { 0.0 };
    score += reusability;

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0; // perfect chain
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item can't use this residual; large residual becomes dead space
            score += 0.08 * (pr as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits more aggressively
        score += 0.05 * (fitting_bins_count as f64) * (post_residual as f64) / cap;
    }

    // New-bin candidate handling: opening a bin is penalized unless current
    // fits are all terrible (large post_residual everywhere).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        score += 45.0
            + 20.0 * (open_bins_count as f64).sqrt()
            + 15.0 * progress;
        // if mean residual of open bins is large, opening is less bad
        score -= 0.15 * mean_residual;
        // a new bin gives post_residual = capacity - item; if that's a harmonic class
        // matching common sizes, soften penalty
        if pr % 10 == 0 && pr > 0 { score -= 10.0; }
    } else {
        // mild reward for keeping bin count down
        score -= 3.0;
    }

    // Dead-space penalty: residual that no item (min size 1..=10 heuristic band)
    // can plausibly fill given typical granularity.
    if pr > 0 && pr < 4 {
        score += 18.0; // tiny unusable sliver
    }

    // Small tie-breaker noise via deterministic coupling on step parity.
    if step_index % 2 == 0 { score -= 0.01; } else { score += 0.01; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
