            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize creating small unusable fragments (below minimum item size 1..10 band).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Prefer bins with residual below mean (tight packing), discourage very loose bins.
