    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins would waste a lot.
    if bin_residual == bin_capacity {
        let waste = mean_residual - post_residual as f64;
        if waste > 25.0 {
            score -= waste * 0.8;
        } else {
            score += 50.0;
        }
    }

    // Slight preference to fill older bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

