    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits perfectly in post_residual, reward strongly
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
