    // late in the stream, strongly prefer existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 20.0 * progress;
        if post_residual as f64 > bin_capacity as f64 - item_size as f64 + 0.5 { /* unreachable guard */ }
    } else {
        score -= 6.0 * progress;
    }

    // Slight preference for bins with moderate residual over extreme ones.
    let rel = bin_residual as f64 / bin_capacity as f64;
    score += 4.0 * (rel - 0.5).abs();

    score
