    let mut score = post_residual as f64;

    // Base: prefer tight fits, but avoid tiny unusable residuals.
    if post_residual == 0 {
        score -= 200.0; // perfect fit is gold
    } else if post_residual < 10 {
        score -= 120.0; // near-perfect
    } else if post_residual <= 20 {
        score -= 30.0; // still usable for small items
    } else if post_residual > 80 {
        score += 40.0; // large dead space after placement
