        6..=12 => 8.0,            // awkward zone
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: residual in half/third/quarter bands.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    if pr >= half { score += 15.0; }
    else if pr >= third { score -= 5.0; }

    // Lookahead: does next item fit in post_residual?
