            score -= 40.0 + 30.0 * tightness;
            // Harmonic coupling: next_item_size mod classes
            if next_item_size % 25 == 0 { score -= 15.0; }
        } else {
            // Next item won't chain here; penalize slightly more for mid residuals.
            score += 10.0 + 0.1 * (pr as f64);
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // current fits are poor. Make empty-bin score moderately high by default.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin ~ its full residual, plus opening overhead.
        score = bin_capacity as f64 + 60.0
            - 0.3 * mean_residual
            + (open_bins_count as f64).sqrt() * 10.0;
