        score -= 25.0;
    }

    // Penalize opening a new bin when open bins give a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // A new bin is only attractive when no existing bin fits well
        // (large post residual elsewhere) or many bins are open.
